
CREATE OR REPLACE FUNCTION academy_private.lesson_validation(p_version uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO ''
AS $function$
DECLARE
 v public.academy_lesson_versions;
 errors jsonb := '[]'::jsonb;
 warnings jsonb := '[]'::jsonb;
 n integer;
 kinds text[];
BEGIN
 SELECT * INTO v FROM public.academy_lesson_versions WHERE id=p_version;
 IF NOT FOUND THEN RAISE EXCEPTION 'Version not found'; END IF;
 SELECT count(*),coalesce(array_agg(DISTINCT block_type),'{}') INTO n,kinds
 FROM public.academy_lesson_blocks WHERE version_id=p_version;
 IF btrim(v.objective)='' THEN errors:=errors||jsonb_build_array('missing_objective'); END IF;
 IF btrim(v.hook)='' THEN errors:=errors||jsonb_build_array('missing_hook'); END IF;
 IF n<5 THEN errors:=errors||jsonb_build_array('too_few_blocks'); END IF;
 IF NOT (kinds && ARRAY['sequence_sort','matching','image_hotspot','decision_tree','scenario','client_simulation','calculator','prompt_builder','practical_response','reflection','checklist','quiz','homework','submission','flip_cards']) THEN
  errors:=errors||jsonb_build_array('missing_interaction');
 END IF;
 IF NOT ('quiz'=ANY(kinds)) THEN errors:=errors||jsonb_build_array('missing_knowledge_check'); END IF;
 IF NOT (
  kinds && ARRAY['prompt_builder','practical_response','homework','submission']
  OR (
   EXISTS (
    SELECT 1 FROM public.academy_lessons l
    WHERE l.id=v.academy_lesson_id
      AND l.module_id IN ('s02-m01','s02-m02','s02-m03','s02-m04','s02-m05','s02-m06')
   )
   AND kinds && ARRAY['sequence_sort','matching','image_hotspot','decision_tree','scenario','client_simulation','calculator']
  )
 ) THEN errors:=errors||jsonb_build_array('missing_practice'); END IF;
 IF NOT ('summary'=ANY(kinds)) THEN errors:=errors||jsonb_build_array('missing_summary'); END IF;
 IF EXISTS (SELECT 1 FROM public.academy_lesson_blocks b WHERE b.version_id=p_version AND b.required AND b.points=0) THEN
  warnings:=warnings||jsonb_build_array('required_block_has_no_xp');
 END IF;
 IF EXISTS(
  SELECT 1 FROM public.academy_lesson_blocks b
  LEFT JOIN academy_private.lesson_block_keys k ON k.block_id=b.id
  WHERE b.version_id=p_version
    AND b.block_type IN ('sequence_sort','matching','image_hotspot','decision_tree','scenario','client_simulation','calculator','quiz')
    AND k.block_id IS NULL
 ) THEN errors:=errors||jsonb_build_array('missing_server_evaluation'); END IF;
 RETURN jsonb_build_object(
  'errors',errors, 'warnings',warnings, 'block_count',n,
  'interactive',kinds && ARRAY['sequence_sort','matching','image_hotspot','decision_tree','scenario','client_simulation','calculator','prompt_builder','practical_response','reflection','checklist','quiz','homework','submission','flip_cards'],
  'has_quiz','quiz'=ANY(kinds),
  'has_assignment',kinds && ARRAY['practical_response','homework','submission']
 );
END $function$;

-- Safe edition replacement for 43 already published lessons. User history and attempts are retained.
-- A failure in any guard aborts the entire migration and leaves the published pointers intact.
DO $release$
DECLARE
 payload jsonb := $curriculum$[{"module_id":"s02-m04","lesson_id":"pv04-01","title":"Светлина от един прозорец","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще направиш повторяем портрет със светлина от прозорец и ще познаеш кога тя вече се променя.","hook":"Прозорецът изглежда безплатен, докато облак не премести контраста по средата на интервюто.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще направиш повторяем портрет със светлина от прозорец и ще познаеш кога тя вече се променя. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Прозорецът изглежда безплатен, докато облак не премести контраста по средата на интервюто."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Гледай къде пада светлината върху лицето и фона, вместо да преследваш един задължителен ъгъл.\n\nГолям видим източник дава по-плавен ръб на сянката. Разстоянието и посоката променят съотношението лице–фон; бял картон връща светлина, черен картон поглъща отражения."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Снимай 10 секунди при реалното време на деня и заключи експозиция и баланс на бялото. Изключи лампата на тавана само ако смесеният цвят пречи; оставена като умишлен фон, тя може да работи. Ако слънцето удря директно, тънък дифузен материал омекотява светлината, но не използвай плат до горещ източник. Запиши как ще реагираш, когато небето се смени.\n\nГраница на решението: Няма универсална позиция на метър от стъклото. Посоката, размерът на прозореца, сезонът и облаците променят резултата."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Избери фон и позиция според светлината на лицето.\n2. Провери отраженията и сложи бял или черен картон според нуждата.\n3. Заключи камерата и заснеми кратък тест при реалното време.\n4. Повтори теста след промяна на облаците и сравни лицето.\n\nСтоп-сигнал: Продължаваш със същите настройки, а после се опитваш да възстановиш изгоряла кожа в монтажа.\nВърни се към пробата: Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Пекарка разказва за работата си до западен прозорец. В първия дубъл облак прави лицето меко; след пет минути слънцето реже половината кадър. Имаш още три въпроса.\n\nРешение: Премести човека извън директния лъч или сложи дифузия; направи нов тест и снимай контролен кадър преди следващия отговор.\n\nДоказателство, че работи: Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Продължаваш със същите настройки, а после се опитваш да възстановиш изгоряла кожа в монтажа."},"after":{"label":"Как го поправяш","text":"Премести човека извън директния лъч или сложи дифузия; направи нов тест и снимай контролен кадър преди следващия отговор. Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Работна задача без качване на файл: заснеми по 10 секунди без отражател, с бял картон и с черен картон. Запиши на кои кадри лицето е четимо и къде фонът губи детайл.\n\nВземи доказателство, което би показал на друг монтажист: Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Продължаваш със същите настройки, а после се опитваш да възстановиш изгоряла кожа в монтажа.\n\nГраницата: Няма универсална позиция на метър от стъклото. Посоката, размерът на прозореца, сезонът и облаците променят резултата."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Светлина от един прозорец“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Продължаваш със същите настройки, а после се опитваш да възстановиш изгоряла кожа в монтажа."},{"id":"b","label":"Пусни автоматичен баланс на бялото и се надявай той да изравни всички дубъли."},{"id":"c","label":"Гледай къде пада светлината върху лицето и фона, вместо да преследваш един задължителен ъгъл."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Гледай къде пада светлината върху лицето и фона, вместо да преследваш един задължителен ъгъл. Голям видим източник дава по-плавен ръб на сянката. Разстоянието и посоката променят съотношението лице–фон; бял картон връща светлина, черен картон поглъща отражения."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Пекарка разказва за работата си до западен прозорец. В първия дубъл облак прави лицето меко; след пет минути слънцето реже половината кадър. Имаш още три въпроса.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Премести човека извън директния лъч или сложи дифузия; направи нов тест и снимай контролен кадър преди следващия отговор."},{"id":"b","label":"Продължаваш със същите настройки, а после се опитваш да възстановиш изгоряла кожа в монтажа."},{"id":"c","label":"Пусни автоматичен баланс на бялото и се надявай той да изравни всички дубъли."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Премести човека извън директния лъч или сложи дифузия; направи нов тест и снимай контролен кадър преди следващия отговор. Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Пусни автоматичен баланс на бялото и се надявай той да изравни всички дубъли."},{"id":"b","label":"Няма универсална позиция на метър от стъклото. Посоката, размерът на прозореца, сезонът и облаците променят резултата."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Няма универсална позиция на метър от стъклото. Посоката, размерът на прозореца, сезонът и облаците променят резултата."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Гледай къде пада светлината върху лицето и фона, вместо да преследваш един задължителен ъгъл.","Премести човека извън директния лъч или сложи дифузия; направи нов тест и снимай контролен кадър преди следващия отговор.","Не пропускай контрола: Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон."],"nextStep":"Работна задача без качване на файл: заснеми по 10 секунди без отражател, с бял картон и с черен картон. Запиши на кои кадри лицето е четимо и къде фонът губи детайл."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Няма универсална позиция на метър от стъклото. Посоката, размерът на прозореца, сезонът и облаците променят резултата.","items":[{"id":"s3","text":"Заключи камерата и заснеми кратък тест при реалното време."},{"id":"s1","text":"Избери фон и позиция според светлината на лицето."},{"id":"s4","text":"Повтори теста след промяна на облаците и сравни лицето."},{"id":"s2","text":"Провери отраженията и сложи бял или черен картон според нуждата."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Избери фон и позиция според светлината на лицето. → Провери отраженията и сложи бял или черен картон според нуждата. → Заключи камерата и заснеми кратък тест при реалното време. → Повтори теста след промяна на облаците и сравни лицето."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Прозорецът е зад говорителя, а стаята е тъмна; местене на целия екип е невъзможно.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Промени посоката на камерата или използвай налично отражение и измери лицето спрямо фона; ако няма достатъчно светлина, смени мястото или времето."},{"id":"b","label":"Продължаваш със същите настройки, а после се опитваш да възстановиш изгоряла кожа в монтажа."},{"id":"c","label":"Пусни автоматичен баланс на бялото и се надявай той да изравни всички дубъли."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Промени посоката на камерата или използвай налично отражение и измери лицето спрямо фона; ако няма достатъчно светлина, смени мястото или времето. Няма универсална позиция на метър от стъклото. Посоката, размерът на прозореца, сезонът и облаците променят резултата."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Следи реалната светлина между дублите. Когато средата се промени, новият тест е част от работата, не признание за грешка.\n\nРаботна карта:\n1. Избери фон и позиция според светлината на лицето.\n2. Провери отраженията и сложи бял или черен картон според нуждата.\n3. Заключи камерата и заснеми кратък тест при реалното време.\n4. Повтори теста след промяна на облаците и сравни лицето.\n\nКритерий за предаване: Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-02","title":"Минимален светлинен комплект, който решава проблем","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще избереш едно осветително тяло и модификатори според сцената, контакта и безопасността.","hook":"Пълна чанта с лампи не помага, ако на място няма място за безопасен статив.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще избереш едно осветително тяло и модификатори според сцената, контакта и безопасността. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Пълна чанта с лампи не помага, ако на място няма място за безопасен статив."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Първо избери позиция на светлината; купувай мощност и модификатори едва след тест на реалната сцена.\n\nЕдна стабилна светлина, мек модификатор, надежден статив, захранване и черен или бял картон решават повече задачи от случаен набор RGB панели. Приеми ограничението на помещението и дистанцията до човека като част от решението."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"На малък снимачен терен окабеляването и товарът на стойката са производствен риск. Провери маркировките и инструкциите на производителя за захранване, монтаж и разстояние до плат или перде. Нискочестотното трептене на осветлението може да даде ленти или пулсации при конкретен затвор; виж го във видео проба при същата кадрова честота, а не само с очи.\n\nГраница на решението: Мощността на етикета не казва колко светлина ще стигне до лицето след модификатор; тествай в това помещение."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Опиши сцена, размер на помещение и нужната площ светлина.\n2. Разположи една лампа и безопасен статив извън пътя на хората.\n3. Запиши проба със същите fps и затвор като проекта.\n4. Провери сенки, отблясъци, трептене и кабели преди снимки.\n\nСтоп-сигнал: Поставяш лампата на пътеката, гониш „кинематографичен“ контур и пропускаш отблясък във витрината.\nВърни се към пробата: В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Малък магазин иска интервю след затваряне. Пространството е тясно, има стъклена витрина и пътека към изхода; разполагаш с една лампа.\n\nРешение: Изнеси стойката извън пътеката, промени ъгъла спрямо стъклото и заснеми проба с реалния затвор.\n\nДоказателство, че работи: В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Поставяш лампата на пътеката, гониш „кинематографичен“ контур и пропускаш отблясък във витрината."},"after":{"label":"Как го поправяш","text":"Изнеси стойката извън пътеката, промени ъгъла спрямо стъклото и заснеми проба с реалния затвор. В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Направи план с една лампа: снимай 10 секунди на мястото, маркирай безопасния маршрут, после същата проба с променен ъгъл. Сравни четимостта, а не цената на екипировката.\n\nВземи доказателство, което би показал на друг монтажист: В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Поставяш лампата на пътеката, гониш „кинематографичен“ контур и пропускаш отблясък във витрината.\n\nГраницата: Мощността на етикета не казва колко светлина ще стигне до лицето след модификатор; тествай в това помещение."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Минимален светлинен комплект, който решава проблем“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Вдигни ISO и поправи отблясъците с цветна корекция."},{"id":"b","label":"Първо избери позиция на светлината; купувай мощност и модификатори едва след тест на реалната сцена."},{"id":"c","label":"Поставяш лампата на пътеката, гониш „кинематографичен“ контур и пропускаш отблясък във витрината."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Първо избери позиция на светлината; купувай мощност и модификатори едва след тест на реалната сцена. Една стабилна светлина, мек модификатор, надежден статив, захранване и черен или бял картон решават повече задачи от случаен набор RGB панели. Приеми ограничението на помещението и дистанцията до човека като част от решението."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Малък магазин иска интервю след затваряне. Пространството е тясно, има стъклена витрина и пътека към изхода; разполагаш с една лампа.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Поставяш лампата на пътеката, гониш „кинематографичен“ контур и пропускаш отблясък във витрината."},{"id":"b","label":"Вдигни ISO и поправи отблясъците с цветна корекция."},{"id":"c","label":"Изнеси стойката извън пътеката, промени ъгъла спрямо стъклото и заснеми проба с реалния затвор."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Изнеси стойката извън пътеката, промени ъгъла спрямо стъклото и заснеми проба с реалния затвор. В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Мощността на етикета не казва колко светлина ще стигне до лицето след модификатор; тествай в това помещение."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Вдигни ISO и поправи отблясъците с цветна корекция."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Мощността на етикета не казва колко светлина ще стигне до лицето след модификатор; тествай в това помещение."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Първо избери позиция на светлината; купувай мощност и модификатори едва след тест на реалната сцена.","Изнеси стойката извън пътеката, промени ъгъла спрямо стъклото и заснеми проба с реалния затвор.","Не пропускай контрола: В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно."],"nextStep":"Направи план с една лампа: снимай 10 секунди на мястото, маркирай безопасния маршрут, после същата проба с променен ъгъл. Сравни четимостта, а не цената на екипировката."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Мощността на етикета не казва колко светлина ще стигне до лицето след модификатор; тествай в това помещение.","items":[{"id":"s3","text":"Запиши проба със същите fps и затвор като проекта."},{"id":"s1","text":"Опиши сцена, размер на помещение и нужната площ светлина."},{"id":"s4","text":"Провери сенки, отблясъци, трептене и кабели преди снимки."},{"id":"s2","text":"Разположи една лампа и безопасен статив извън пътя на хората."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Опиши сцена, размер на помещение и нужната площ светлина. → Разположи една лампа и безопасен статив извън пътя на хората. → Запиши проба със същите fps и затвор като проекта. → Провери сенки, отблясъци, трептене и кабели преди снимки."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Контактът на място е далече и клиентът иска да смениш позицията на масата.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Поставяш лампата на пътеката, гониш „кинематографичен“ контур и пропускаш отблясък във витрината."},{"id":"b","label":"Вдигни ISO и поправи отблясъците с цветна корекция."},{"id":"c","label":"Преизчисли маршрута и захранването; ако кабелът трябва да пресече проход, промени плана и избери безопасна позиция."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Преизчисли маршрута и захранването; ако кабелът трябва да пресече проход, промени плана и избери безопасна позиция. Мощността на етикета не казва колко светлина ще стигне до лицето след модификатор; тествай в това помещение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Задавай въпроса „Какво съществуващо препятствие премахва тази лампа?“. Ако нямаш отговор, не добавяй още една.\n\nРаботна карта:\n1. Опиши сцена, размер на помещение и нужната площ светлина.\n2. Разположи една лампа и безопасен статив извън пътя на хората.\n3. Запиши проба със същите fps и затвор като проекта.\n4. Провери сенки, отблясъци, трептене и кабели преди снимки.\n\nКритерий за предаване: В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-03","title":"Черно знаме: махни отражението, което разваля сянката","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще използваш отрицателно запълване и ще определиш кога то отнема твърде много детайл.","hook":"Бяла стая връща светлина към лицето отвсякъде; още една лампа няма да върне обема.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще използваш отрицателно запълване и ще определиш кога то отнема твърде много детайл. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Бяла стая връща светлина към лицето отвсякъде; още една лампа няма да върне обема."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Черна повърхност от страната на сянката спира част от върнатата светлина и прави формата видима.\n\nПостави матов черен картон извън кадъра; мести го и гледай как се изменя сенчестата страна. Това не е „намаляване на експозицията“ на цялата сцена, а контрол на отражението в определена посока."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Гланцирана или твърде малка повърхност може да не помогне. Отдръпни картона постепенно, докато окото в сянката остане четимо. Провери фона и дрехите: ако те потъват в черно, добави разстояние или промени ъгъла на ключовата светлина, вместо да стискаш контраста в монтажа.\n\nГраница на решението: Отрицателното запълване не спасява липса на светлина; при тъмна сцена може да влоши полезния сигнал."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Заключи експонация, баланс и основен кадър.\n2. Сравни кадъра без черна повърхност и с нея от страната на сянката.\n3. Мести картона, докато лицето запази нужния детайл.\n4. Провери очите и черната дреха на реален екран.\n\nСтоп-сигнал: Слагаш голяма черна плоскост до самото лице и приемаш изгубеното око за „драматичен стил“.\nВърни се към пробата: На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Говорител с тъмно сако стои в бял офис. Лицето е плоско, но сакото лесно се слива със стената, когато добавиш черен картон.\n\nРешение: Отмести плоскостта, запази формата на лицето и върни малко отражение към сенчестото око, ако е нужно.\n\nДоказателство, че работи: На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Слагаш голяма черна плоскост до самото лице и приемаш изгубеното око за „драматичен стил“."},"after":{"label":"Как го поправяш","text":"Отмести плоскостта, запази формата на лицето и върни малко отражение към сенчестото око, ако е нужно. На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Запиши серия A/B при фиксирани настройки. Ако гласът и намерението са спокойни и доверителни, избери умерен контраст; ако сцената е напрегната, контрастът може да служи на историята.\n\nВземи доказателство, което би показал на друг монтажист: На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Слагаш голяма черна плоскост до самото лице и приемаш изгубеното око за „драматичен стил“.\n\nГраницата: Отрицателното запълване не спасява липса на светлина; при тъмна сцена може да влоши полезния сигнал."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Черно знаме: махни отражението, което разваля сянката“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Черна повърхност от страната на сянката спира част от върнатата светлина и прави формата видима."},{"id":"b","label":"Слагаш голяма черна плоскост до самото лице и приемаш изгубеното око за „драматичен стил“."},{"id":"c","label":"Усили черния цвят в цялата картина и ще получиш същия локален ефект."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Черна повърхност от страната на сянката спира част от върнатата светлина и прави формата видима. Постави матов черен картон извън кадъра; мести го и гледай как се изменя сенчестата страна. Това не е „намаляване на експозицията“ на цялата сцена, а контрол на отражението в определена посока."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Говорител с тъмно сако стои в бял офис. Лицето е плоско, но сакото лесно се слива със стената, когато добавиш черен картон.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Усили черния цвят в цялата картина и ще получиш същия локален ефект."},{"id":"b","label":"Отмести плоскостта, запази формата на лицето и върни малко отражение към сенчестото око, ако е нужно."},{"id":"c","label":"Слагаш голяма черна плоскост до самото лице и приемаш изгубеното око за „драматичен стил“."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Отмести плоскостта, запази формата на лицето и върни малко отражение към сенчестото око, ако е нужно. На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Усили черния цвят в цялата картина и ще получиш същия локален ефект."},{"id":"c","label":"Отрицателното запълване не спасява липса на светлина; при тъмна сцена може да влоши полезния сигнал."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Отрицателното запълване не спасява липса на светлина; при тъмна сцена може да влоши полезния сигнал."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Черна повърхност от страната на сянката спира част от върнатата светлина и прави формата видима.","Отмести плоскостта, запази формата на лицето и върни малко отражение към сенчестото око, ако е нужно.","Не пропускай контрола: На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен."],"nextStep":"Запиши серия A/B при фиксирани настройки. Ако гласът и намерението са спокойни и доверителни, избери умерен контраст; ако сцената е напрегната, контрастът може да служи на историята."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Отрицателното запълване не спасява липса на светлина; при тъмна сцена може да влоши полезния сигнал.","items":[{"id":"s3","text":"Мести картона, докато лицето запази нужния детайл."},{"id":"s1","text":"Заключи експонация, баланс и основен кадър."},{"id":"s4","text":"Провери очите и черната дреха на реален екран."},{"id":"s2","text":"Сравни кадъра без черна повърхност и с нея от страната на сянката."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Заключи експонация, баланс и основен кадър. → Сравни кадъра без черна повърхност и с нея от страната на сянката. → Мести картона, докато лицето запази нужния детайл. → Провери очите и черната дреха на реален екран."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: След това преместваш същата установка в малко тъмно помещение.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Усили черния цвят в цялата картина и ще получиш същия локален ефект."},{"id":"b","label":"Първо измери дали има достатъчно светлина върху лицето; използвай отрицателно запълване само ако има излишно отражение."},{"id":"c","label":"Слагаш голяма черна плоскост до самото лице и приемаш изгубеното око за „драматичен стил“."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Първо измери дали има достатъчно светлина върху лицето; използвай отрицателно запълване само ако има излишно отражение. Отрицателното запълване не спасява липса на светлина; при тъмна сцена може да влоши полезния сигнал."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Лицето носи смисъла. Изразителната сянка е успешна само когато зрителят вижда реакцията.\n\nРаботна карта:\n1. Заключи експонация, баланс и основен кадър.\n2. Сравни кадъра без черна повърхност и с нея от страната на сянката.\n3. Мести картона, докато лицето запази нужния детайл.\n4. Провери очите и черната дреха на реален екран.\n\nКритерий за предаване: На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-04","title":"Контурна светлина без изгорели краища","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще отделиш човека от фона с контур и ще спреш светлината, преди да попадне в обектива.","hook":"Контурът може да отдели рамото, но същата лампа може да измие целия кадър.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще отделиш човека от фона с контур и ще спреш светлината, преди да попадне в обектива. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Контурът може да отдели рамото, но същата лампа може да измие целия кадър."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Постави контурната светлина зад и встрани от субекта, като гледаш краищата и отблясъка едновременно.\n\nФлаг, решетка или промяна на ъгъла ограничава разлива към обектива. Не осветявай косата и рамото на максимума само защото има отделяне; търси разлика спрямо фона, която помага на читимостта."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Запиши проба с включен и изключен контур. Провери дали бялата риза не губи текстура, дали светлината не реже носа и дали в очилата няма ярко петно. Ако фонът вече дава достатъчен цвят или тонален контраст, допълнителната лампа може да не е нужна. Контурът не заменя правилно осветено лице.\n\nГраница на решението: При голяма дистанция до фона или светъл фон отделянето може да е достатъчно и без контур."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Настрой основния кадър и лицето без контур.\n2. Добави слаба светлина зад рамото и провери отраженията.\n3. Ограничи лъча или промени ъгъла, ако удари обектива.\n4. Сравни A/B на експортирания файл и остави по-ясния вариант.\n\nСтоп-сигнал: Вдигаш яркостта, докато косата свети в бяло; отблясъкът остава във всяка камера.\nВърни се към пробата: Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Снимаш интервю пред тъмни рафтове. Контурът отделя косата, но на широкия план образът става млечен.\n\nРешение: Измести лампата, сложи флаг или решетка и намали мощността до видимо, но естествено отделяне.\n\nДоказателство, че работи: Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Вдигаш яркостта, докато косата свети в бяло; отблясъкът остава във всяка камера."},"after":{"label":"Как го поправяш","text":"Измести лампата, сложи флаг или решетка и намали мощността до видимо, но естествено отделяне. Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Сними три последователни варианта: без лампа, слаб контур и силен контур. Сравни не само косата, а и общия контраст на изображението.\n\nВземи доказателство, което би показал на друг монтажист: Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Вдигаш яркостта, докато косата свети в бяло; отблясъкът остава във всяка камера.\n\nГраницата: При голяма дистанция до фона или светъл фон отделянето може да е достатъчно и без контур."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Контурна светлина без изгорели краища“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Вдигаш яркостта, докато косата свети в бяло; отблясъкът остава във всяка камера."},{"id":"b","label":"Компенсирай липсващия контур със силно изостряне в монтажа."},{"id":"c","label":"Постави контурната светлина зад и встрани от субекта, като гледаш краищата и отблясъка едновременно."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Постави контурната светлина зад и встрани от субекта, като гледаш краищата и отблясъка едновременно. Флаг, решетка или промяна на ъгъла ограничава разлива към обектива. Не осветявай косата и рамото на максимума само защото има отделяне; търси разлика спрямо фона, която помага на читимостта."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Снимаш интервю пред тъмни рафтове. Контурът отделя косата, но на широкия план образът става млечен.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Измести лампата, сложи флаг или решетка и намали мощността до видимо, но естествено отделяне."},{"id":"b","label":"Вдигаш яркостта, докато косата свети в бяло; отблясъкът остава във всяка камера."},{"id":"c","label":"Компенсирай липсващия контур със силно изостряне в монтажа."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Измести лампата, сложи флаг или решетка и намали мощността до видимо, но естествено отделяне. Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Компенсирай липсващия контур със силно изостряне в монтажа."},{"id":"b","label":"При голяма дистанция до фона или светъл фон отделянето може да е достатъчно и без контур."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"При голяма дистанция до фона или светъл фон отделянето може да е достатъчно и без контур."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Постави контурната светлина зад и встрани от субекта, като гледаш краищата и отблясъка едновременно.","Измести лампата, сложи флаг или решетка и намали мощността до видимо, но естествено отделяне.","Не пропускай контрола: Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно."],"nextStep":"Сними три последователни варианта: без лампа, слаб контур и силен контур. Сравни не само косата, а и общия контраст на изображението."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. При голяма дистанция до фона или светъл фон отделянето може да е достатъчно и без контур.","items":[{"id":"s3","text":"Ограничи лъча или промени ъгъла, ако удари обектива."},{"id":"s1","text":"Настрой основния кадър и лицето без контур."},{"id":"s4","text":"Сравни A/B на експортирания файл и остави по-ясния вариант."},{"id":"s2","text":"Добави слаба светлина зад рамото и провери отраженията."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Настрой основния кадър и лицето без контур. → Добави слаба светлина зад рамото и провери отраженията. → Ограничи лъча или промени ъгъла, ако удари обектива. → Сравни A/B на експортирания файл и остави по-ясния вариант."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Говорителят сменя тъмното сако с лъскава бяла риза.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Намали или премахни контура; провери дали бялата тъкан запазва детайл и дали широкият кадър не губи черното."},{"id":"b","label":"Вдигаш яркостта, докато косата свети в бяло; отблясъкът остава във всяка камера."},{"id":"c","label":"Компенсирай липсващия контур със силно изостряне в монтажа."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Намали или премахни контура; провери дали бялата тъкан запазва детайл и дали широкият кадър не губи черното. При голяма дистанция до фона или светъл фон отделянето може да е достатъчно и без контур."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Бърз тест: изключи контура. Ако никой не може да обясни какво точно се загуби, може да го оставиш изключен.\n\nРаботна карта:\n1. Настрой основния кадър и лицето без контур.\n2. Добави слаба светлина зад рамото и провери отраженията.\n3. Ограничи лъча или промени ъгъла, ако удари обектива.\n4. Сравни A/B на експортирания файл и остави по-ясния вариант.\n\nКритерий за предаване: Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-05","title":"Мотивирана светлина: кадърът да има причина","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще изградиш осветление, което изглежда естествено за мястото и служи на историята.","hook":"Лампа в кадъра обещава топла светлина; ако лицето свети студено от обратната страна, зрителят усеща измамата.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще изградиш осветление, което изглежда естествено за мястото и служи на историята. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Лампа в кадъра обещава топла светлина; ако лицето свети студено от обратната страна, зрителят усеща измамата."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Всяка видима светлина предполага посока. Нека основният източник продължи това, което зрителят вече вижда в сцената.\n\nНощна лампа, прозорец или отворена врата може да е визуално обяснение за светлина извън кадър. Не е задължително практическата лампа сама да осветява лицето; важно е посоката, цветът и яркостта да не си противоречат."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Изключи всички лампи и виж каква светлина идва от мястото. После включвай източник по източник и наблюдавай сенките. Ако фонова лампа изгаря абажура, намали експозицията ѝ или смени крушката, без да потапяш лицето в тъмно. Заключи баланса на бялото и снимай срещуположните планове със същата логика на посоката.\n\nГраница на решението: Мотивирано не значи буквално. Светлината може да е усилена извън кадър, стига сцената да остане убедителна."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Посочи видимия или предполагаем източник в сцената.\n2. Подреди основната светлина така, че сянката да има логична посока.\n3. Настрой отделно лицето и практическата лампа.\n4. Снимай план и обратен план; провери дали светлината пази една история.\n\nСтоп-сигнал: Добавяш още две цветни лампи и прикриваш несъответствието с оранжев филтър.\nВърни се към пробата: И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Готвач разказва пред топла настолна лампа, но голям LED осветява лицето от страната, която лампата не може да достигне.\n\nРешение: Премести основния източник в логичната посока на лампата или направи прозорецът ясно видим като втора причина.\n\nДоказателство, че работи: И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Добавяш още две цветни лампи и прикриваш несъответствието с оранжев филтър."},"after":{"label":"Как го поправяш","text":"Премести основния източник в логичната посока на лампата или направи прозорецът ясно видим като втора причина. И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Начертай със стрелки посоките на видимите източници и на сенките. Прегледай един статичен кадър без звук: зрителят трябва да разбира откъде идва светлината.\n\nВземи доказателство, което би показал на друг монтажист: И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Добавяш още две цветни лампи и прикриваш несъответствието с оранжев филтър.\n\nГраницата: Мотивирано не значи буквално. Светлината може да е усилена извън кадър, стига сцената да остане убедителна."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Мотивирана светлина: кадърът да има причина“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Остави всички източници на максимална яркост, за да няма тъмни участъци."},{"id":"b","label":"Всяка видима светлина предполага посока. Нека основният източник продължи това, което зрителят вече вижда в сцената."},{"id":"c","label":"Добавяш още две цветни лампи и прикриваш несъответствието с оранжев филтър."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Всяка видима светлина предполага посока. Нека основният източник продължи това, което зрителят вече вижда в сцената. Нощна лампа, прозорец или отворена врата може да е визуално обяснение за светлина извън кадър. Не е задължително практическата лампа сама да осветява лицето; важно е посоката, цветът и яркостта да не си противоречат."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Готвач разказва пред топла настолна лампа, но голям LED осветява лицето от страната, която лампата не може да достигне.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Добавяш още две цветни лампи и прикриваш несъответствието с оранжев филтър."},{"id":"b","label":"Остави всички източници на максимална яркост, за да няма тъмни участъци."},{"id":"c","label":"Премести основния източник в логичната посока на лампата или направи прозорецът ясно видим като втора причина."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Премести основния източник в логичната посока на лампата или направи прозорецът ясно видим като втора причина. И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Мотивирано не значи буквално. Светлината може да е усилена извън кадър, стига сцената да остане убедителна."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Остави всички източници на максимална яркост, за да няма тъмни участъци."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Мотивирано не значи буквално. Светлината може да е усилена извън кадър, стига сцената да остане убедителна."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Всяка видима светлина предполага посока. Нека основният източник продължи това, което зрителят вече вижда в сцената.","Премести основния източник в логичната посока на лампата или направи прозорецът ясно видим като втора причина.","Не пропускай контрола: И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл."],"nextStep":"Начертай със стрелки посоките на видимите източници и на сенките. Прегледай един статичен кадър без звук: зрителят трябва да разбира откъде идва светлината."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Мотивирано не значи буквално. Светлината може да е усилена извън кадър, стига сцената да остане убедителна.","items":[{"id":"s3","text":"Настрой отделно лицето и практическата лампа."},{"id":"s1","text":"Посочи видимия или предполагаем източник в сцената."},{"id":"s4","text":"Снимай план и обратен план; провери дали светлината пази една история."},{"id":"s2","text":"Подреди основната светлина така, че сянката да има логична посока."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Посочи видимия или предполагаем източник в сцената. → Подреди основната светлина така, че сянката да има логична посока. → Настрой отделно лицето и практическата лампа. → Снимай план и обратен план; провери дали светлината пази една история."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Екипът премества разговора по-близо до дневен прозорец.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Добавяш още две цветни лампи и прикриваш несъответствието с оранжев филтър."},{"id":"b","label":"Остави всички източници на максимална яркост, за да няма тъмни участъци."},{"id":"c","label":"Избери водещия източник наново; ако прозорецът вземе сцената, остави настолната лампа като фонов акцент."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Избери водещия източник наново; ако прозорецът вземе сцената, остави настолната лампа като фонов акцент. Мотивирано не значи буквално. Светлината може да е усилена извън кадър, стига сцената да остане убедителна."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Осветлението разказва за мястото. Истинската проверка е дали след монтажа плановете още изглеждат от една стая.\n\nРаботна карта:\n1. Посочи видимия или предполагаем източник в сцената.\n2. Подреди основната светлина така, че сянката да има логична посока.\n3. Настрой отделно лицето и практическата лампа.\n4. Снимай план и обратен план; провери дали светлината пази една история.\n\nКритерий за предаване: И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-06","title":"Смесена светлина и постоянен цвят","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще разпознаеш кога два източника дават различен цвят върху едно лице и ще решиш проблема на терен.","hook":"Половината лице е синкава дневна светлина, другата е жълта от тавана; плъзгачът за баланс няма как да поправи и двете наведнъж.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще разпознаеш кога два източника дават различен цвят върху едно лице и ще решиш проблема на терен. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Половината лице е синкава дневна светлина, другата е жълта от тавана; плъзгачът за баланс няма как да поправи и двете наведнъж."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Един баланс на бялото избира една опорна точка. Първо реши кои източници ще осветяват лицето.\n\nМожеш да изключиш, покриеш или преместиш нежелан източник, да групираш лампите с близък цвят или умишлено да оставиш контраст в отделен фон. Цветната температура не описва напълно спектъра на една лампа."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Постави неутрален предмет или референтна карта при светлината върху лицето, а не на произволно място в стаята. Заключи баланса след проба и гледай кожата и цветните предмети. При светодиоди с различен спектър две лампи със сходни Kelvin стойности пак може да дадат различни кожи; сравни записа от самата камера, вместо да разчиташ на числото.\n\nГраница на решението: Различен цвят във фона може да е творчески избор. Проблемът е противоречивият цвят върху една и съща важна повърхност."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Определи водещия източник за лицето.\n2. Ограничи вторичната светлина или я остави само във фона.\n3. Заключи баланса на бялото при реалната светлина.\n4. Снимай и сравни кожа и неутрален предмет в двата плана.\n\nСтоп-сигнал: Коригираш целия кадър към неутрално и оставяш зеленикави петна по едната буза.\nВърни се към пробата: Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Снимаш фризьорски салон: голяма витрина отляво, топли спотове над клиентката и студено огледало отпред.\n\nРешение: Изключи или отслаби проблемния спот върху лицето, избери един водещ източник и настрой ръчен баланс след проба.\n\nДоказателство, че работи: Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Коригираш целия кадър към неутрално и оставяш зеленикави петна по едната буза."},"after":{"label":"Как го поправяш","text":"Изключи или отслаби проблемния спот върху лицето, избери един водещ източник и настрой ръчен баланс след проба. Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Запиши 10 секунди с всички лампи и още 10 с една изключена. Стопни кадъра на кожа и бял предмет и сравни; записът е по-надежден от обяснение на хартия.\n\nВземи доказателство, което би показал на друг монтажист: Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Коригираш целия кадър към неутрално и оставяш зеленикави петна по едната буза.\n\nГраницата: Различен цвят във фона може да е творчески избор. Проблемът е противоречивият цвят върху една и съща важна повърхност."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Смесена светлина и постоянен цвят“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Един баланс на бялото избира една опорна точка. Първо реши кои източници ще осветяват лицето."},{"id":"b","label":"Коригираш целия кадър към неутрално и оставяш зеленикави петна по едната буза."},{"id":"c","label":"Прехвърли всички камери на автоматичен баланс и остави всяка да решава самостоятелно."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Един баланс на бялото избира една опорна точка. Първо реши кои източници ще осветяват лицето. Можеш да изключиш, покриеш или преместиш нежелан източник, да групираш лампите с близък цвят или умишлено да оставиш контраст в отделен фон. Цветната температура не описва напълно спектъра на една лампа."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Снимаш фризьорски салон: голяма витрина отляво, топли спотове над клиентката и студено огледало отпред.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Прехвърли всички камери на автоматичен баланс и остави всяка да решава самостоятелно."},{"id":"b","label":"Изключи или отслаби проблемния спот върху лицето, избери един водещ източник и настрой ръчен баланс след проба."},{"id":"c","label":"Коригираш целия кадър към неутрално и оставяш зеленикави петна по едната буза."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Изключи или отслаби проблемния спот върху лицето, избери един водещ източник и настрой ръчен баланс след проба. Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Прехвърли всички камери на автоматичен баланс и остави всяка да решава самостоятелно."},{"id":"c","label":"Различен цвят във фона може да е творчески избор. Проблемът е противоречивият цвят върху една и съща важна повърхност."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Различен цвят във фона може да е творчески избор. Проблемът е противоречивият цвят върху една и съща важна повърхност."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Един баланс на бялото избира една опорна точка. Първо реши кои източници ще осветяват лицето.","Изключи или отслаби проблемния спот върху лицето, избери един водещ източник и настрой ръчен баланс след проба.","Не пропускай контрола: Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок."],"nextStep":"Запиши 10 секунди с всички лампи и още 10 с една изключена. Стопни кадъра на кожа и бял предмет и сравни; записът е по-надежден от обяснение на хартия."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Различен цвят във фона може да е творчески избор. Проблемът е противоречивият цвят върху една и съща важна повърхност.","items":[{"id":"s3","text":"Заключи баланса на бялото при реалната светлина."},{"id":"s1","text":"Определи водещия източник за лицето."},{"id":"s4","text":"Снимай и сравни кожа и неутрален предмет в двата плана."},{"id":"s2","text":"Ограничи вторичната светлина или я остави само във фона."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Определи водещия източник за лицето. → Ограничи вторичната светлина или я остави само във фона. → Заключи баланса на бялото при реалната светлина. → Снимай и сравни кожа и неутрален предмет в двата плана."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Настъпва залез и дневната светлина отслабва по време на интервюто.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Прехвърли всички камери на автоматичен баланс и остави всяка да решава самостоятелно."},{"id":"b","label":"Преоцени водещия източник, направи нов ръчен баланс и остави контролен кадър за цветно съвпадение."},{"id":"c","label":"Коригираш целия кадър към неутрално и оставяш зеленикави петна по едната буза."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Преоцени водещия източник, направи нов ръчен баланс и остави контролен кадър за цветно съвпадение. Различен цвят във фона може да е творчески избор. Проблемът е противоречивият цвят върху една и съща важна повърхност."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"„Същите Kelvin“ на етикета са начало за проба, а не гаранция за еднакъв резултат.\n\nРаботна карта:\n1. Определи водещия източник за лицето.\n2. Ограничи вторичната светлина или я остави само във фона.\n3. Заключи баланса на бялото при реалната светлина.\n4. Снимай и сравни кожа и неутрален предмет в двата плана.\n\nКритерий за предаване: Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-07","title":"CRI е показател, не присъда за кожата","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще сравниш две лампи в камерата и ще знаеш какво CRI не ти казва.","hook":"Купуваш осветление с високо CRI, а червеният продукт пак изглежда мъртъв.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще сравниш две лампи в камерата и ще знаеш какво CRI не ти казва. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Купуваш осветление с високо CRI, а червеният продукт пак изглежда мъртъв."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Оцени лампата по реален запис на кожа и фирмени цветове; числото на кутията само насочва кои да тестваш.\n\nCRI описва определен тест спрямо референтен източник, но не гарантира как всеки цвят или всяка камера ще реагира. При различни диоди и режими спектърът, зеленото отклонение и цветните наситени повърхности може да се различават."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Заключи експонация и баланс на бялото, снимай една и съща сцена с една лампа, после смени само лампата. Гледай кожа, червен и син предмет, бял лист и сиви сенки. Ако производителят публикува и други метрики, разгледай ги, но не превръщай нито една в обещание за крайна снимка. Смесването на две различни лампи се проверява отделно.\n\nГраница на решението: Няма универсално минимално CRI, което да гарантира правилна кожа при всички камери и спектри."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Избери една и съща сцена и цветни предмети.\n2. Заключи камерата и позицията на лампата.\n3. Запиши A/B с двата източника при сравнима яркост.\n4. Провери кожа, наситени цветове и сенки на еднакъв екран.\n\nСтоп-сигнал: Обявяваш двата панела за еднакви по спецификация и поправяш всеки кадър с различен LUT.\nВърни се към пробата: Двата файла са със същите настройки; цветът на опаковката и кожата се различават видимо и изборът е повторяем."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Снимаш червена опаковка на бонбони за каталог. Два панела пишат CRI 95; при единия продуктът губи разликата между червено и оранжево.\n\nРешение: Направи контролна проба с продукта и избери лампата, която възпроизвежда нужните цветове последователно.\n\nДоказателство, че работи: Двата файла са със същите настройки; цветът на опаковката и кожата се различават видимо и изборът е повторяем."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Обявяваш двата панела за еднакви по спецификация и поправяш всеки кадър с различен LUT."},"after":{"label":"Как го поправяш","text":"Направи контролна проба с продукта и избери лампата, която възпроизвежда нужните цветове последователно. Двата файла са със същите настройки; цветът на опаковката и кожата се различават видимо и изборът е повторяем."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Снимай едно лице и два продуктови цвята с лампата на различни мощности; сравни и приглушения режим, защото спектърът и пулсациите може да се променят.\n\nВземи доказателство, което би показал на друг монтажист: Двата файла са със същите настройки; цветът на опаковката и кожата се различават видимо и изборът е повторяем.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Обявяваш двата панела за еднакви по спецификация и поправяш всеки кадър с различен LUT.\n\nГраницата: Няма универсално минимално CRI, което да гарантира правилна кожа при всички камери и спектри."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „CRI е показател, не присъда за кожата“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Обявяваш двата панела за еднакви по спецификация и поправяш всеки кадър с различен LUT."},{"id":"b","label":"Вдигни сатурацията, докато опаковката изглежда „по-цветна“ на камерата."},{"id":"c","label":"Оцени лампата по реален запис на кожа и фирмени цветове; числото на кутията само насочва кои да тестваш."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Оцени лампата по реален запис на кожа и фирмени цветове; числото на кутията само насочва кои да тестваш. CRI описва определен тест спрямо референтен източник, но не гарантира как всеки цвят или всяка камера ще реагира. При различни диоди и режими спектърът, зеленото отклонение и цветните наситени повърхности може да се различават."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Снимаш червена опаковка на бонбони за каталог. Два панела пишат CRI 95; при единия продуктът губи разликата между червено и оранжево.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Направи контролна проба с продукта и избери лампата, която възпроизвежда нужните цветове последователно."},{"id":"b","label":"Обявяваш двата панела за еднакви по спецификация и поправяш всеки кадър с различен LUT."},{"id":"c","label":"Вдигни сатурацията, докато опаковката изглежда „по-цветна“ на камерата."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Направи контролна проба с продукта и избери лампата, която възпроизвежда нужните цветове последователно. Двата файла са със същите настройки; цветът на опаковката и кожата се различават видимо и изборът е повторяем."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Вдигни сатурацията, докато опаковката изглежда „по-цветна“ на камерата."},{"id":"b","label":"Няма универсално минимално CRI, което да гарантира правилна кожа при всички камери и спектри."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Няма универсално минимално CRI, което да гарантира правилна кожа при всички камери и спектри."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Оцени лампата по реален запис на кожа и фирмени цветове; числото на кутията само насочва кои да тестваш.","Направи контролна проба с продукта и избери лампата, която възпроизвежда нужните цветове последователно.","Не пропускай контрола: Двата файла са със същите настройки; цветът на опаковката и кожата се различават видимо и изборът е повторяем."],"nextStep":"Снимай едно лице и два продуктови цвята с лампата на различни мощности; сравни и приглушения режим, защото спектърът и пулсациите може да се променят."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Няма универсално минимално CRI, което да гарантира правилна кожа при всички камери и спектри.","items":[{"id":"s3","text":"Запиши A/B с двата източника при сравнима яркост."},{"id":"s1","text":"Избери една и съща сцена и цветни предмети."},{"id":"s4","text":"Провери кожа, наситени цветове и сенки на еднакъв екран."},{"id":"s2","text":"Заключи камерата и позицията на лампата."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Избери една и съща сцена и цветни предмети. → Заключи камерата и позицията на лампата. → Запиши A/B с двата източника при сравнима яркост. → Провери кожа, наситени цветове и сенки на еднакъв екран."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът добавя в кадър ярко лилава опаковка.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Направи нова проба именно с лилавата повърхност и финалната комбинация лампа–камера."},{"id":"b","label":"Обявяваш двата панела за еднакви по спецификация и поправяш всеки кадър с различен LUT."},{"id":"c","label":"Вдигни сатурацията, докато опаковката изглежда „по-цветна“ на камерата."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Направи нова проба именно с лилавата повърхност и финалната комбинация лампа–камера. Няма универсално минимално CRI, което да гарантира правилна кожа при всички камери и спектри."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Спецификацията помага за подбор. Решението се взема по контролирана проба от сцената, която клиентът реално ще получи.\n\nРаботна карта:\n1. Избери една и съща сцена и цветни предмети.\n2. Заключи камерата и позицията на лампата.\n3. Запиши A/B с двата източника при сравнима яркост.\n4. Провери кожа, наситени цветове и сенки на еднакъв екран.\n\nКритерий за предаване: Двата файла са със същите настройки; цветът на опаковката и кожата се различават видимо и изборът е повторяем."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-08","title":"Три сцени, три решения за светлина","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще пренаредиш една лампа за интервю, продукт и влог, без да прилагаш една схема навсякъде.","hook":"Светлина, която ласкае лице, често скрива релефа на опаковка или блести в чашата.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще пренаредиш една лампа за интервю, продукт и влог, без да прилагаш една схема навсякъде. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Светлина, която ласкае лице, често скрива релефа на опаковка или блести в чашата."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Сменяй посока, размер и дистанция според това какво зрителят трябва да види.\n\nЗа интервю провери очите и фона; при продукт провери текстура, отблясъци и надпис; при влог провери как лицето остава четимо при движение. Една лампа може да остане същата, но задачата ѝ се сменя."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Големият мек източник разширява отражението върху лъскав предмет; тесен източник може да покаже текстура по-рязко. При самозаснемане маркирай допустимата зона на движение на пода и направи проба в двата края. Не подреждай оборудването по любима диаграма, ако резултатът не служи на обекта.\n\nГраница на решението: Няма универсална схема с един ъгъл: материалът, повърхността и движението определят позицията."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Запиши една цел: лице, надпис или движение.\n2. Разположи лампата и фона според тази цел.\n3. Сними проба и провери ръбове, отблясък и сенки.\n4. Промени едно условие и повтори теста за следващата сцена.\n\nСтоп-сигнал: Оставяш осветлението на едно място и приемаш отражение, което заличава името на буркана.\nВърни се към пробата: Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Екип снима собственик на кафене, после лъскав буркан и накрая кратък влог, докато той върви между масите.\n\nРешение: За продукта премести източника така, че отражението да очертава форма, но да освободи етикета; за влога ограничи движението или промени мястото.\n\nДоказателство, че работи: Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Оставяш осветлението на едно място и приемаш отражение, което заличава името на буркана."},"after":{"label":"Как го поправяш","text":"За продукта премести източника така, че отражението да очертава форма, но да освободи етикета; за влога ограничи движението или промени мястото. Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"С една лампа сними три 10-секундни клипа. За всеки назови една грешка и една промяна; приеми само вариант, който изпълнява предварително избрания критерий.\n\nВземи доказателство, което би показал на друг монтажист: Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Оставяш осветлението на едно място и приемаш отражение, което заличава името на буркана.\n\nГраницата: Няма универсална схема с един ъгъл: материалът, повърхността и движението определят позицията."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Три сцени, три решения за светлина“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Добави още лампи преди да провериш отблясъка."},{"id":"b","label":"Сменяй посока, размер и дистанция според това какво зрителят трябва да види."},{"id":"c","label":"Оставяш осветлението на едно място и приемаш отражение, което заличава името на буркана."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Сменяй посока, размер и дистанция според това какво зрителят трябва да види. За интервю провери очите и фона; при продукт провери текстура, отблясъци и надпис; при влог провери как лицето остава четимо при движение. Една лампа може да остане същата, но задачата ѝ се сменя."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Екип снима собственик на кафене, после лъскав буркан и накрая кратък влог, докато той върви между масите.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Оставяш осветлението на едно място и приемаш отражение, което заличава името на буркана."},{"id":"b","label":"Добави още лампи преди да провериш отблясъка."},{"id":"c","label":"За продукта премести източника така, че отражението да очертава форма, но да освободи етикета; за влога ограничи движението или промени мястото."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"За продукта премести източника така, че отражението да очертава форма, но да освободи етикета; за влога ограничи движението или промени мястото. Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Няма универсална схема с един ъгъл: материалът, повърхността и движението определят позицията."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Добави още лампи преди да провериш отблясъка."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Няма универсална схема с един ъгъл: материалът, повърхността и движението определят позицията."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Сменяй посока, размер и дистанция според това какво зрителят трябва да види.","За продукта премести източника така, че отражението да очертава форма, но да освободи етикета; за влога ограничи движението или промени мястото.","Не пропускай контрола: Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение."],"nextStep":"С една лампа сними три 10-секундни клипа. За всеки назови една грешка и една промяна; приеми само вариант, който изпълнява предварително избрания критерий."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Няма универсална схема с един ъгъл: материалът, повърхността и движението определят позицията.","items":[{"id":"s3","text":"Сними проба и провери ръбове, отблясък и сенки."},{"id":"s1","text":"Запиши една цел: лице, надпис или движение."},{"id":"s4","text":"Промени едно условие и повтори теста за следващата сцена."},{"id":"s2","text":"Разположи лампата и фона според тази цел."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Запиши една цел: лице, надпис или движение. → Разположи лампата и фона според тази цел. → Сними проба и провери ръбове, отблясък и сенки. → Промени едно условие и повтори теста за следващата сцена."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Бурканът се заменя с матова кутия с релефен печат.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Оставяш осветлението на едно място и приемаш отражение, което заличава името на буркана."},{"id":"b","label":"Добави още лампи преди да провериш отблясъка."},{"id":"c","label":"Тествай по-странична светлина за релефа и запази четимостта на печата; не пренасяй ъгъла от лъскавия буркан механично."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Тествай по-странична светлина за релефа и запази четимостта на печата; не пренасяй ъгъла от лъскавия буркан механично. Няма универсална схема с един ъгъл: материалът, повърхността и движението определят позицията."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Няколко различни задачи могат да се снимат с един комплект, ако променяш позицията, а не очакванията на клиента.\n\nРаботна карта:\n1. Запиши една цел: лице, надпис или движение.\n2. Разположи лампата и фона според тази цел.\n3. Сними проба и провери ръбове, отблясък и сенки.\n4. Промени едно условие и повтори теста за следващата сцена.\n\nКритерий за предаване: Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-09","title":"Цветова корекция преди визия","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще поправиш експонация и баланс преди да правиш стилистичен цвят.","hook":"Красив LUT върху неправилен баланс прави грешката по-красива и по-трудна за откриване.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще поправиш експонация и баланс преди да правиш стилистичен цвят. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Красив LUT върху неправилен баланс прави грешката по-красива и по-трудна за откриване."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Раздели нормализиране на материала, изравняване на плановете и стилистичната визия.\n\nПърво избери правилен вход и изход за материала. После настрой експонация, контраст и баланс по образа и измервателните инструменти. Едва след това добави творческата промяна."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Използвай референтен кадър от същата сцена, но не изтривай умишлена нощна атмосфера с автоматично „избелване“. Ако екранът не е надежден, гледай waveform и RGB parade за крайности и сравнявай на още едно устройство. Запази версия преди визията, за да можеш да отделиш технически проблем от стил.\n\nГраница на решението: Не всяка сцена има неутрално бяло. Следвай намерението и контролния кадър, не автоматична стойност."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Провери входния цветови профил и целевия изход.\n2. Изправи експонация и баланс без творчески филтър.\n3. Изравни съседните планове с референтен кадър.\n4. Добави визия и провери на целевия екран.\n\nСтоп-сигнал: Слагаш един и същ LUT на двата клипа и оставяш кожата да сменя цвят при срез.\nВърни се към пробата: При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Кафене получава два кадъра от една сцена: едната камера е студена, другата топла. Иска се мек филмов тон.\n\nРешение: Нормализирай входа на всяка камера, изравни кожа и експонация, после приложи обща визия с проверка при срез.\n\nДоказателство, че работи: При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Слагаш един и същ LUT на двата клипа и оставяш кожата да сменя цвят при срез."},"after":{"label":"Как го поправяш","text":"Нормализирай входа на всяка камера, изравни кожа и експонация, после приложи обща визия с проверка при срез. При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Направи два експорта: чист коригиран и стилизиран. Ако грешката се появява и в чистия, върни се към техническата корекция.\n\nВземи доказателство, което би показал на друг монтажист: При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Слагаш един и същ LUT на двата клипа и оставяш кожата да сменя цвят при срез.\n\nГраницата: Не всяка сцена има неутрално бяло. Следвай намерението и контролния кадър, не автоматична стойност."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Цветова корекция преди визия“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Раздели нормализиране на материала, изравняване на плановете и стилистичната визия."},{"id":"b","label":"Слагаш един и същ LUT на двата клипа и оставяш кожата да сменя цвят при срез."},{"id":"c","label":"Добави наситеност към всички цветове, докато продуктът се доближи до каталога."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Раздели нормализиране на материала, изравняване на плановете и стилистичната визия. Първо избери правилен вход и изход за материала. После настрой експонация, контраст и баланс по образа и измервателните инструменти. Едва след това добави творческата промяна."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Кафене получава два кадъра от една сцена: едната камера е студена, другата топла. Иска се мек филмов тон.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Добави наситеност към всички цветове, докато продуктът се доближи до каталога."},{"id":"b","label":"Нормализирай входа на всяка камера, изравни кожа и експонация, после приложи обща визия с проверка при срез."},{"id":"c","label":"Слагаш един и същ LUT на двата клипа и оставяш кожата да сменя цвят при срез."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Нормализирай входа на всяка камера, изравни кожа и експонация, после приложи обща визия с проверка при срез. При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Добави наситеност към всички цветове, докато продуктът се доближи до каталога."},{"id":"c","label":"Не всяка сцена има неутрално бяло. Следвай намерението и контролния кадър, не автоматична стойност."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Не всяка сцена има неутрално бяло. Следвай намерението и контролния кадър, не автоматична стойност."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Раздели нормализиране на материала, изравняване на плановете и стилистичната визия.","Нормализирай входа на всяка камера, изравни кожа и експонация, после приложи обща визия с проверка при срез.","Не пропускай контрола: При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони."],"nextStep":"Направи два експорта: чист коригиран и стилизиран. Ако грешката се появява и в чистия, върни се към техническата корекция."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Не всяка сцена има неутрално бяло. Следвай намерението и контролния кадър, не автоматична стойност.","items":[{"id":"s3","text":"Изравни съседните планове с референтен кадър."},{"id":"s1","text":"Провери входния цветови профил и целевия изход."},{"id":"s4","text":"Добави визия и провери на целевия екран."},{"id":"s2","text":"Изправи експонация и баланс без творчески филтър."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Провери входния цветови профил и целевия изход. → Изправи експонация и баланс без творчески филтър. → Изравни съседните планове с референтен кадър. → Добави визия и провери на целевия екран."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът одобрява стила, но иска продукта по-близо до реалния му цвят.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Добави наситеност към всички цветове, докато продуктът се доближи до каталога."},{"id":"b","label":"Запази одобрената обща визия и поправи локално продукта с проверка срещу референтен кадър."},{"id":"c","label":"Слагаш един и същ LUT на двата клипа и оставяш кожата да сменя цвят при срез."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Запази одобрената обща визия и поправи локално продукта с проверка срещу референтен кадър. Не всяка сцена има неутрално бяло. Следвай намерението и контролния кадър, не автоматична стойност."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"„Технически правилно“ е основа за последователност, а стилът е решение за конкретен разказ.\n\nРаботна карта:\n1. Провери входния цветови профил и целевия изход.\n2. Изправи експонация и баланс без творчески филтър.\n3. Изравни съседните планове с референтен кадър.\n4. Добави визия и провери на целевия екран.\n\nКритерий за предаване: При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-10","title":"Топъл и студен цвят: решение за историята","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще тестваш настроение с цвят, без да подменяш бранд или естествени предмети.","hook":"Оранжевият кадър може да е уютен, но също може да направи синята опаковка кафява.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще тестваш настроение с цвят, без да подменяш бранд или естествени предмети. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Оранжевият кадър може да е уютен, но също може да направи синята опаковка кафява."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Настроението идва от сцената, светлината и монтажа заедно; температурата сама не обещава определена емоция.\n\nИзбери какво трябва да усеща зрителят, какво трябва да разпознае и кои цветове са неприкосновени. Направи два варианта от един и същ неутрален кадър, вместо да сравняваш различни кадри."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Гледай кожата, фирмения цвят и неутрален предмет при двата варианта. Покажи ги в контекста на съседните кадри и звука. Ако разказът е за свежест, топлият вариант може да му противоречи; ако клиентът продава физически продукт, значимите цветове не бива да се измислят.\n\nГраница на решението: Една асоциация с цвят не е универсална за всяка аудитория или марка; провери реакцията в реалния контекст."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Определи посланието и предметите, чиито цветове трябва да останат честни.\n2. Изготви неутрален референтен кадър.\n3. Направи два умерени варианта само от него.\n4. Прегледай ги в последователността на видеото с клиента.\n\nСтоп-сигнал: Усилваш топлината до максимум, защото „топло продава“.\nВърни се към пробата: Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Пекарна иска „топло, домашно“ видео. Първата версия прави хляба оранжев, но маслото и бялата опаковка изглеждат неверни.\n\nРешение: Задръж уютното усещане чрез фон и светлина, но върни опаковката и храната към убедителни цветове.\n\nДоказателство, че работи: Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Усилваш топлината до максимум, защото „топло продава“."},"after":{"label":"Как го поправяш","text":"Задръж уютното усещане чрез фон и светлина, но върни опаковката и храната към убедителни цветове. Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Покажи A/B на двама души без да им подсказваш „топло“ и „студено“. Попитай какво различават в продукта и доверието към кадъра, а не кой филтър харесват.\n\nВземи доказателство, което би показал на друг монтажист: Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Усилваш топлината до максимум, защото „топло продава“.\n\nГраницата: Една асоциация с цвят не е универсална за всяка аудитория или марка; провери реакцията в реалния контекст."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Топъл и студен цвят: решение за историята“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Усилваш топлината до максимум, защото „топло продава“."},{"id":"b","label":"Промени температурата на всички кадри на една и съща стойност без сравнение."},{"id":"c","label":"Настроението идва от сцената, светлината и монтажа заедно; температурата сама не обещава определена емоция."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Настроението идва от сцената, светлината и монтажа заедно; температурата сама не обещава определена емоция. Избери какво трябва да усеща зрителят, какво трябва да разпознае и кои цветове са неприкосновени. Направи два варианта от един и същ неутрален кадър, вместо да сравняваш различни кадри."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Пекарна иска „топло, домашно“ видео. Първата версия прави хляба оранжев, но маслото и бялата опаковка изглеждат неверни.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Задръж уютното усещане чрез фон и светлина, но върни опаковката и храната към убедителни цветове."},{"id":"b","label":"Усилваш топлината до максимум, защото „топло продава“."},{"id":"c","label":"Промени температурата на всички кадри на една и съща стойност без сравнение."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Задръж уютното усещане чрез фон и светлина, но върни опаковката и храната към убедителни цветове. Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Промени температурата на всички кадри на една и съща стойност без сравнение."},{"id":"b","label":"Една асоциация с цвят не е универсална за всяка аудитория или марка; провери реакцията в реалния контекст."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Една асоциация с цвят не е универсална за всяка аудитория или марка; провери реакцията в реалния контекст."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Настроението идва от сцената, светлината и монтажа заедно; температурата сама не обещава определена емоция.","Задръж уютното усещане чрез фон и светлина, но върни опаковката и храната към убедителни цветове.","Не пропускай контрола: Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми."],"nextStep":"Покажи A/B на двама души без да им подсказваш „топло“ и „студено“. Попитай какво различават в продукта и доверието към кадъра, а не кой филтър харесват."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Една асоциация с цвят не е универсална за всяка аудитория или марка; провери реакцията в реалния контекст.","items":[{"id":"s3","text":"Направи два умерени варианта само от него."},{"id":"s1","text":"Определи посланието и предметите, чиито цветове трябва да останат честни."},{"id":"s4","text":"Прегледай ги в последователността на видеото с клиента."},{"id":"s2","text":"Изготви неутрален референтен кадър."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Определи посланието и предметите, чиито цветове трябва да останат честни. → Изготви неутрален референтен кадър. → Направи два умерени варианта само от него. → Прегледай ги в последователността на видеото с клиента."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Същото видео ще се използва и за техническа инструкция.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Остави по-неутрална, ясна версия за инструкцията; провери дали материалите и предупрежденията не се губят."},{"id":"b","label":"Усилваш топлината до максимум, защото „топло продава“."},{"id":"c","label":"Промени температурата на всички кадри на една и съща стойност без сравнение."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Остави по-неутрална, ясна версия за инструкцията; провери дали материалите и предупрежденията не се губят. Една асоциация с цвят не е универсална за всяка аудитория или марка; провери реакцията в реалния контекст."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Стилът не трябва да се бори с задачата на видеото.\n\nРаботна карта:\n1. Определи посланието и предметите, чиито цветове трябва да останат честни.\n2. Изготви неутрален референтен кадър.\n3. Направи два умерени варианта само от него.\n4. Прегледай ги в последователността на видеото с клиента.\n\nКритерий за предаване: Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-11","title":"Кожата като ориентир, не като шаблон","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще проверяваш кожен тон с контекст и ще избягваш универсална стойност за всички хора.","hook":"Плъзгачът казва „правилно“, а лицето изглежда сиво или прекалено оранжево.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще проверяваш кожен тон с контекст и ще избягваш универсална стойност за всички хора. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Плъзгачът казва „правилно“, а лицето изглежда сиво или прекалено оранжево."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Оцени кожата във връзка със светлината, човека и съседните кадри; не настройвай всички лица към един цвят.\n\nVectorscope може да подскаже нежелан цветен уклон, но линията за кожа не определя светлота или желания вид за всеки човек. Маска върху малка зона може да помогне да прочетеш посоката, без да променяш целия кадър."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Започни с правилен входен профил и баланс на бялото. Сравни лице, бял/сив предмет под същата светлина и референтен кадър от снимачния ден. Ако светлината е умишлено цветна, не изравнявай всяка буза към неутрално; поправи неволен зелен или магента оттенък само когато нарушава достоверността.\n\nГраница на решението: Различните тонове кожа и умишленото цветно осветление не се побират в един универсален target на vectorscope."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Нормализирай материала и намери референтен кадър.\n2. Провери кожата и неутралния предмет под една и съща светлина.\n3. Коригирай нежелания уклон умерено; пази текстура.\n4. Прехвърли между плановете и провери на друг екран.\n\nСтоп-сигнал: Издърпваш глобално всички лица към една оранжева стойност.\nВърни се към пробата: Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Двама служители са снимани в една стая, но единият стои под зеленикав LED. След обща корекция неговото лице още изглежда болно.\n\nРешение: Коригирай конкретния кадър и източника на зеления уклон; сравни със същия човек в друг план.\n\nДоказателство, че работи: Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Издърпваш глобално всички лица към една оранжева стойност."},"after":{"label":"Как го поправяш","text":"Коригирай конкретния кадър и източника на зеления уклон; сравни със същия човек в друг план. Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Сравни същото лице в два съседни плана, а не две различни лица като „един еталон“. Документирай коя лампа е светила всеки план.\n\nВземи доказателство, което би показал на друг монтажист: Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Издърпваш глобално всички лица към една оранжева стойност.\n\nГраницата: Различните тонове кожа и умишленото цветно осветление не се побират в един универсален target на vectorscope."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Кожата като ориентир, не като шаблон“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Кликни автоматично „skin tone“ и копирай стойностите на всички говорители."},{"id":"b","label":"Оцени кожата във връзка със светлината, човека и съседните кадри; не настройвай всички лица към един цвят."},{"id":"c","label":"Издърпваш глобално всички лица към една оранжева стойност."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Оцени кожата във връзка със светлината, човека и съседните кадри; не настройвай всички лица към един цвят. Vectorscope може да подскаже нежелан цветен уклон, но линията за кожа не определя светлота или желания вид за всеки човек. Маска върху малка зона може да помогне да прочетеш посоката, без да променяш целия кадър."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Двама служители са снимани в една стая, но единият стои под зеленикав LED. След обща корекция неговото лице още изглежда болно.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Издърпваш глобално всички лица към една оранжева стойност."},{"id":"b","label":"Кликни автоматично „skin tone“ и копирай стойностите на всички говорители."},{"id":"c","label":"Коригирай конкретния кадър и източника на зеления уклон; сравни със същия човек в друг план."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Коригирай конкретния кадър и източника на зеления уклон; сравни със същия човек в друг план. Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Различните тонове кожа и умишленото цветно осветление не се побират в един универсален target на vectorscope."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Кликни автоматично „skin tone“ и копирай стойностите на всички говорители."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Различните тонове кожа и умишленото цветно осветление не се побират в един универсален target на vectorscope."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Оцени кожата във връзка със светлината, човека и съседните кадри; не настройвай всички лица към един цвят.","Коригирай конкретния кадър и източника на зеления уклон; сравни със същия човек в друг план.","Не пропускай контрола: Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез."],"nextStep":"Сравни същото лице в два съседни плана, а не две различни лица като „един еталон“. Документирай коя лампа е светила всеки план."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Различните тонове кожа и умишленото цветно осветление не се побират в един универсален target на vectorscope.","items":[{"id":"s3","text":"Коригирай нежелания уклон умерено; пази текстура."},{"id":"s1","text":"Нормализирай материала и намери референтен кадър."},{"id":"s4","text":"Прехвърли между плановете и провери на друг екран."},{"id":"s2","text":"Провери кожата и неутралния предмет под една и съща светлина."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Нормализирай материала и намери референтен кадър. → Провери кожата и неутралния предмет под една и съща светлина. → Коригирай нежелания уклон умерено; пази текстура. → Прехвърли между плановете и провери на друг екран."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Оказва се, че финалният кадър е заснет под цветна сценична светлина.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Издърпваш глобално всички лица към една оранжева стойност."},{"id":"b","label":"Кликни автоматично „skin tone“ и копирай стойностите на всички говорители."},{"id":"c","label":"Запази умишления цвят на сцената и търси само неволни зелени/магента смени спрямо съседните кадри."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Запази умишления цвят на сцената и търси само неволни зелени/магента смени спрямо съседните кадри. Различните тонове кожа и умишленото цветно осветление не се побират в един универсален target на vectorscope."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Кожата е ориентир за непрекъснатост, не инструмент за уеднаквяване на хората.\n\nРаботна карта:\n1. Нормализирай материала и намери референтен кадър.\n2. Провери кожата и неутралния предмет под една и съща светлина.\n3. Коригирай нежелания уклон умерено; пази текстура.\n4. Прехвърли между плановете и провери на друг екран.\n\nКритерий за предаване: Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-12","title":"Waveform и vectorscope: виж проблема, не гадай","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще откриваш изгубен детайл и цветен уклон чрез измервателните инструменти.","hook":"Мониторът изглежда добре, но експортът губи белия текст на опаковката.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще откриваш изгубен детайл и цветен уклон чрез измервателните инструменти. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Мониторът изглежда добре, но експортът губи белия текст на опаковката."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Waveform показва разпределението на яркостта по изображението, vectorscope показва посока и сила на цвета.\n\nЧети scopes заедно с кадъра. Плоска линия в горния край на waveform може да е клипинг; силно изнесена точка на vectorscope може да е наситен предмет, не „грешка“. RGB parade помага да видиш разминаване между канали в неутрални области."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Увери се, че гледаш правилното място във веригата на color management: лог сигнал преди трансформация изглежда различно от финалния изход. Провери отделно оригинал, коригирана версия и експорт. Никоя графика не заменя решение за съдържанието; тя показва какво се случва със сигнала.\n\nГраница на решението: Стойностите на scopes зависят от цветното пространство, трансформацията и настройките на проекта."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Определи дали измерваш входа или финалния изход.\n2. Намери конкретно място в кадъра, което изглежда проблемно.\n3. Сравни waveform, vectorscope и изображението след една промяна.\n4. Изнеси тестов файл и повтори проверката върху него.\n\nСтоп-сигнал: Вярваш само на яркостта на лаптопа и добавяш още контраст.\nВърни се към пробата: Чинията пази форма, логото остава четимо, а scopes и експортираният файл не си противоречат."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Видео на шоколадов десерт има бяла чиния и червено лого. На лаптопа изглежда красиво, но на телефона чинията е без текстура.\n\nРешение: Провери waveform за затисната светла област, намали прекомерната корекция и отвори експорта на целевия екран.\n\nДоказателство, че работи: Чинията пази форма, логото остава четимо, а scopes и експортираният файл не си противоречат."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Вярваш само на яркостта на лаптопа и добавяш още контраст."},"after":{"label":"Как го поправяш","text":"Провери waveform за затисната светла област, намали прекомерната корекция и отвори експорта на целевия екран. Чинията пази форма, логото остава четимо, а scopes и експортираният файл не си противоречат."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Пусни сравнителен кадър от финалния файл. Запиши кое е клипнато, къде е маскирано и кое е умишлено ярко.\n\nВземи доказателство, което би показал на друг монтажист: Чинията пази форма, логото остава четимо, а scopes и експортираният файл не си противоречат.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Вярваш само на яркостта на лаптопа и добавяш още контраст.\n\nГраницата: Стойностите на scopes зависят от цветното пространство, трансформацията и настройките на проекта."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Waveform и vectorscope: виж проблема, не гадай“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Waveform показва разпределението на яркостта по изображението, vectorscope показва посока и сила на цвета."},{"id":"b","label":"Вярваш само на яркостта на лаптопа и добавяш още контраст."},{"id":"c","label":"Премести всички нива така, че графиката да докосва и двата края."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Waveform показва разпределението на яркостта по изображението, vectorscope показва посока и сила на цвета. Чети scopes заедно с кадъра. Плоска линия в горния край на waveform може да е клипинг; силно изнесена точка на vectorscope може да е наситен предмет, не „грешка“. RGB parade помага да видиш разминаване между канали в неутрални области."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Видео на шоколадов десерт има бяла чиния и червено лого. На лаптопа изглежда красиво, но на телефона чинията е без текстура.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Премести всички нива така, че графиката да докосва и двата края."},{"id":"b","label":"Провери waveform за затисната светла област, намали прекомерната корекция и отвори експорта на целевия екран."},{"id":"c","label":"Вярваш само на яркостта на лаптопа и добавяш още контраст."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Провери waveform за затисната светла област, намали прекомерната корекция и отвори експорта на целевия екран. Чинията пази форма, логото остава четимо, а scopes и експортираният файл не си противоречат."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Премести всички нива така, че графиката да докосва и двата края."},{"id":"c","label":"Стойностите на scopes зависят от цветното пространство, трансформацията и настройките на проекта."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Стойностите на scopes зависят от цветното пространство, трансформацията и настройките на проекта."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Waveform показва разпределението на яркостта по изображението, vectorscope показва посока и сила на цвета.","Провери waveform за затисната светла област, намали прекомерната корекция и отвори експорта на целевия екран.","Не пропускай контрола: Чинията пази форма, логото остава четимо, а scopes и експортираният файл не си противоречат."],"nextStep":"Пусни сравнителен кадър от финалния файл. Запиши кое е клипнато, къде е маскирано и кое е умишлено ярко."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Стойностите на scopes зависят от цветното пространство, трансформацията и настройките на проекта.","items":[{"id":"s3","text":"Сравни waveform, vectorscope и изображението след една промяна."},{"id":"s1","text":"Определи дали измерваш входа или финалния изход."},{"id":"s4","text":"Изнеси тестов файл и повтори проверката върху него."},{"id":"s2","text":"Намери конкретно място в кадъра, което изглежда проблемно."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Определи дали измерваш входа или финалния изход. → Намери конкретно място в кадъра, което изглежда проблемно. → Сравни waveform, vectorscope и изображението след една промяна. → Изнеси тестов файл и повтори проверката върху него."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Получаваш Log материал от втора камера и waveform изглежда сплескан.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Премести всички нива така, че графиката да докосва и двата края."},{"id":"b","label":"Провери входната трансформация и оцени scopes на правилния етап преди да „поправяш“ сигнал, който е нормален за Log."},{"id":"c","label":"Вярваш само на яркостта на лаптопа и добавяш още контраст."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Провери входната трансформация и оцени scopes на правилния етап преди да „поправяш“ сигнал, който е нормален за Log. Стойностите на scopes зависят от цветното пространство, трансформацията и настройките на проекта."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Гледай измерванията като доказателства за конкретен въпрос, не като рецепта за еднакви графики.\n\nРаботна карта:\n1. Определи дали измерваш входа или финалния изход.\n2. Намери конкретно място в кадъра, което изглежда проблемно.\n3. Сравни waveform, vectorscope и изображението след една промяна.\n4. Изнеси тестов файл и повтори проверката върху него.\n\nКритерий за предаване: Чинията пази форма, логото остава четимо, а scopes и експортираният файл не си противоречат."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-13","title":"Rec.709 и Log: една чиста цветна верига","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще организираш вход, обработка и изход без двойна трансформация и изгубен контраст.","hook":"Материалът изглежда сив; слагаш LUT, после още един и лицето става пластмасово.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще организираш вход, обработка и изход без двойна трансформация и изгубен контраст. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Материалът изглежда сив; слагаш LUT, после още един и лицето става пластмасово."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Запиши какъв е реалният профил на всеки файл, в кое пространство работиш и към какъв екран изнасяш.\n\nLog е начин за кодиране на картината, а не готов финален вид. Превръщането към Rec.709 може да стане с подходящо color management или с правилна трансформация; ако приложиш и двете като еднакви стъпки, често удвояваш контраста и цвета."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Провери точния профил в настройките на камерата или файловите метаданни; „Log“ не е една универсална крива. Използвай официалната трансформация за конкретната камера и поддържай последователен изходен target. Сравнявай референтна снимка от терена и финиширай на реален екран, защото превюто на монтажната програма може да следва друга дисплейна настройка.\n\nГраница на решението: Някои LUT файлове са творчески, други технически; името „cinematic“ не е описание на вход и изход."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Идентифицирай профила и gamut за всеки източник.\n2. Избери една работна схема: color management или ръчно управлявани трансформации.\n3. Коригирай експонация и баланс на нормализиран образ.\n4. Изнеси Rec.709 тест и провери кожа, светли и тъмни области.\n\nСтоп-сигнал: Слагаш същия технически LUT и на двата файла, за да са „еднакви“.\nВърни се към пробата: В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Един клип е заснет в Log, вторият е готов стандартен профил. Монтажът автоматично управлява цвета, а върху първия вече има технически LUT.\n\nРешение: Провери входния профил на двата клипа; премахни дублираната трансформация и нормализирай всеки само веднъж.\n\nДоказателство, че работи: В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Слагаш същия технически LUT и на двата файла, за да са „еднакви“."},"after":{"label":"Как го поправяш","text":"Провери входния профил на двата клипа; премахни дублираната трансформация и нормализирай всеки само веднъж. В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Направи контролен експорт на проблемния кадър с и без допълнителния LUT. Ако картината става прекалено контрастна, проследи веригата от входа до изхода.\n\nВземи доказателство, което би показал на друг монтажист: В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Слагаш същия технически LUT и на двата файла, за да са „еднакви“.\n\nГраницата: Някои LUT файлове са творчески, други технически; името „cinematic“ не е описание на вход и изход."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Rec.709 и Log: една чиста цветна верига“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Слагаш същия технически LUT и на двата файла, за да са „еднакви“."},{"id":"b","label":"Вдигни контраст ръчно, докато сивият клип изглежда цветен."},{"id":"c","label":"Запиши какъв е реалният профил на всеки файл, в кое пространство работиш и към какъв екран изнасяш."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Запиши какъв е реалният профил на всеки файл, в кое пространство работиш и към какъв екран изнасяш. Log е начин за кодиране на картината, а не готов финален вид. Превръщането към Rec.709 може да стане с подходящо color management или с правилна трансформация; ако приложиш и двете като еднакви стъпки, често удвояваш контраста и цвета."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Един клип е заснет в Log, вторият е готов стандартен профил. Монтажът автоматично управлява цвета, а върху първия вече има технически LUT.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Провери входния профил на двата клипа; премахни дублираната трансформация и нормализирай всеки само веднъж."},{"id":"b","label":"Слагаш същия технически LUT и на двата файла, за да са „еднакви“."},{"id":"c","label":"Вдигни контраст ръчно, докато сивият клип изглежда цветен."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Провери входния профил на двата клипа; премахни дублираната трансформация и нормализирай всеки само веднъж. В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Вдигни контраст ръчно, докато сивият клип изглежда цветен."},{"id":"b","label":"Някои LUT файлове са творчески, други технически; името „cinematic“ не е описание на вход и изход."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Някои LUT файлове са творчески, други технически; името „cinematic“ не е описание на вход и изход."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Запиши какъв е реалният профил на всеки файл, в кое пространство работиш и към какъв екран изнасяш.","Провери входния профил на двата клипа; премахни дублираната трансформация и нормализирай всеки само веднъж.","Не пропускай контрола: В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация."],"nextStep":"Направи контролен експорт на проблемния кадър с и без допълнителния LUT. Ако картината става прекалено контрастна, проследи веригата от входа до изхода."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Някои LUT файлове са творчески, други технически; името „cinematic“ не е описание на вход и изход.","items":[{"id":"s3","text":"Коригирай експонация и баланс на нормализиран образ."},{"id":"s1","text":"Идентифицирай профила и gamut за всеки източник."},{"id":"s4","text":"Изнеси Rec.709 тест и провери кожа, светли и тъмни области."},{"id":"s2","text":"Избери една работна схема: color management или ръчно управлявани трансформации."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Идентифицирай профила и gamut за всеки източник. → Избери една работна схема: color management или ръчно управлявани трансформации. → Коригирай експонация и баланс на нормализиран образ. → Изнеси Rec.709 тест и провери кожа, светли и тъмни области."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Получаваш клип без достоверни метаданни от трета камера.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Поискай или провери настройката от снимачния ден и направи тест с референтен кадър; не приписвай профил по външен вид."},{"id":"b","label":"Слагаш същия технически LUT и на двата файла, за да са „еднакви“."},{"id":"c","label":"Вдигни контраст ръчно, докато сивият клип изглежда цветен."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Поискай или провери настройката от снимачния ден и направи тест с референтен кадър; не приписвай профил по външен вид. Някои LUT файлове са творчески, други технически; името „cinematic“ не е описание на вход и изход."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Документирай веригата до конкретен вход и конкретен изход, за да може друг човек да отвори проекта без гадания.\n\nРаботна карта:\n1. Идентифицирай профила и gamut за всеки източник.\n2. Избери една работна схема: color management или ръчно управлявани трансформации.\n3. Коригирай експонация и баланс на нормализиран образ.\n4. Изнеси Rec.709 тест и провери кожа, светли и тъмни области.\n\nКритерий за предаване: В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-14","title":"Съвпадение между кадри, преди да личи срезът","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще сравниш два плана по експонация, баланс и важни цветове, без да ги правиш изкуствено еднакви.","hook":"Снимките са красиви поотделно, но при монтаж чашата и лицето сменят цвят през секунда.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще сравниш два плана по експонация, баланс и важни цветове, без да ги правиш изкуствено еднакви. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Снимките са красиви поотделно, но при монтаж чашата и лицето сменят цвят през секунда."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Избери контролен кадър и сравнявай планове в един и същ контекст, преди да копираш настройки.\n\nГледай общите предмети, лице, фон и посока на светлината. Първо изравни най-видимото разминаване в експонацията, после баланса и цвета. Прескачай между кадрите с кратък интервал, за да усетиш внезапния скок."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Ако камерата се е обърнала към прозорец, двата плана имат естествено различна светлина. Целта не е числено съвпадение на всяка пикселна стойност, а зрителят да не се обърка от неволна смяна. Корекцията на кожа не трябва да унищожава истинския цвят на продукта. Запази неподправен референтен still преди силна визия.\n\nГраница на решението: Две камери с различен спектър или светлина няма да съвпаднат чрез copy/paste на плъзгачи."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Избери референтен кадър от същата сцена.\n2. Сравни експонация и неутрални предмети.\n3. Промени цветния уклон само в проблемния план.\n4. Прегледай среза на цял екран и в експорт.\n\nСтоп-сигнал: Копираш стойностите на първата камера върху втората без да погледнеш оригиналния ѝ профил.\nВърни се към пробата: Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"На интервю основната камера показва топло лице, близкият план е зеленикав. В кадъра и на двете има бяла чаша.\n\nРешение: Нормализирай входа на близкия план, ползвай чашата за ориентир и провери лицето при реалния срез.\n\nДоказателство, че работи: Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Копираш стойностите на първата камера върху втората без да погледнеш оригиналния ѝ профил."},"after":{"label":"Как го поправяш","text":"Нормализирай входа на близкия план, ползвай чашата за ориентир и провери лицето при реалния срез. Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Монтирай пет бързи редувания между двата кадъра. Ако някой забелязва неволен цветен пулс преди думите, върни се към изходните трансформации.\n\nВземи доказателство, което би показал на друг монтажист: Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Копираш стойностите на първата камера върху втората без да погледнеш оригиналния ѝ профил.\n\nГраницата: Две камери с различен спектър или светлина няма да съвпаднат чрез copy/paste на плъзгачи."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Съвпадение между кадри, преди да личи срезът“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Уеднакви всички кадри по обща стойност на Kelvin."},{"id":"b","label":"Избери контролен кадър и сравнявай планове в един и същ контекст, преди да копираш настройки."},{"id":"c","label":"Копираш стойностите на първата камера върху втората без да погледнеш оригиналния ѝ профил."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Избери контролен кадър и сравнявай планове в един и същ контекст, преди да копираш настройки. Гледай общите предмети, лице, фон и посока на светлината. Първо изравни най-видимото разминаване в експонацията, после баланса и цвета. Прескачай между кадрите с кратък интервал, за да усетиш внезапния скок."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"На интервю основната камера показва топло лице, близкият план е зеленикав. В кадъра и на двете има бяла чаша.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Копираш стойностите на първата камера върху втората без да погледнеш оригиналния ѝ профил."},{"id":"b","label":"Уеднакви всички кадри по обща стойност на Kelvin."},{"id":"c","label":"Нормализирай входа на близкия план, ползвай чашата за ориентир и провери лицето при реалния срез."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Нормализирай входа на близкия план, ползвай чашата за ориентир и провери лицето при реалния срез. Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Две камери с различен спектър или светлина няма да съвпаднат чрез copy/paste на плъзгачи."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Уеднакви всички кадри по обща стойност на Kelvin."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Две камери с различен спектър или светлина няма да съвпаднат чрез copy/paste на плъзгачи."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Избери контролен кадър и сравнявай планове в един и същ контекст, преди да копираш настройки.","Нормализирай входа на близкия план, ползвай чашата за ориентир и провери лицето при реалния срез.","Не пропускай контрола: Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината."],"nextStep":"Монтирай пет бързи редувания между двата кадъра. Ако някой забелязва неволен цветен пулс преди думите, върни се към изходните трансформации."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Две камери с различен спектър или светлина няма да съвпаднат чрез copy/paste на плъзгачи.","items":[{"id":"s3","text":"Промени цветния уклон само в проблемния план."},{"id":"s1","text":"Избери референтен кадър от същата сцена."},{"id":"s4","text":"Прегледай среза на цял екран и в експорт."},{"id":"s2","text":"Сравни експонация и неутрални предмети."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Избери референтен кадър от същата сцена. → Сравни експонация и неутрални предмети. → Промени цветния уклон само в проблемния план. → Прегледай среза на цял екран и в експорт."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: При снимането облак е затъмнил втория план, а човекът е преместен до лампа.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Копираш стойностите на първата камера върху втората без да погледнеш оригиналния ѝ профил."},{"id":"b","label":"Уеднакви всички кадри по обща стойност на Kelvin."},{"id":"c","label":"Провери кой проблем е експонация и кой е нова посока на светлина; компенсирай четимостта, без да симулираш невъзможен идентичен модел."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Провери кой проблем е експонация и кой е нова посока на светлина; компенсирай четимостта, без да симулираш невъзможен идентичен модел. Две камери с различен спектър или светлина няма да съвпаднат чрез copy/paste на плъзгачи."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Съвпадението е непрекъснатост на разказа, не упражнение по еднакви числа.\n\nРаботна карта:\n1. Избери референтен кадър от същата сцена.\n2. Сравни експонация и неутрални предмети.\n3. Промени цветния уклон само в проблемния план.\n4. Прегледай среза на цял екран и в експорт.\n\nКритерий за предаване: Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-15","title":"Изгради визия, която преживява целия монтаж","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще създадеш умерен стил и ще го провериш върху най-трудния кадър, не само върху най-хубавия.","hook":"Твоят любим кадър изглежда отлично; следващият със светла риза и тъмна кожа се разпада.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще създадеш умерен стил и ще го провериш върху най-трудния кадър, не само върху най-хубавия. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Твоят любим кадър изглежда отлично; следващият със светла риза и тъмна кожа се разпада."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Добрата визия трябва да издържи различни лица, материали и планове в една история.\n\nОстави отделни етапи за техническа корекция и творческа визия. Избери два или три контролни кадъра: лице, продукт и крайно осветление. Настрой визията върху тях, вместо да копираш силна настройка по цялата времева линия."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Насищането на сенките и цветовете във високите светлини често изглеждат впечатляващи в един стоп кадър, но губят информация в движение. Следи за клипинг, шум и ленти при силни градиенти. Сравни преди/след на финален размер и в кратка последователност, защото усещането за стил се променя при монтаж.\n\nГраница на решението: Еднакъв LUT не гарантира еднакъв стил върху кадри с различен вход и светлина."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Коригирай технически три различни контролни кадъра.\n2. Избери каква промяна подкрепя посланието.\n3. Приложи умерена визия и коригирай отделните кадри.\n4. Изнеси кратка последователност и провери най-трудния кадър.\n\nСтоп-сигнал: Показваш само слънчевия вход и обявяваш визията за завършена.\nВърни се към пробата: Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Филм за работилница включва слънчев вход, тъмно интервю и близък план на меден продукт. Силният стил прави продукта червен и убива сенките.\n\nРешение: Намали крайностите, тествай и трите сцени и настрой отделно кадъра с продукта преди одобрение.\n\nДоказателство, че работи: Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Показваш само слънчевия вход и обявяваш визията за завършена."},"after":{"label":"Как го поправяш","text":"Намали крайностите, тествай и трите сцени и настрой отделно кадъра с продукта преди одобрение. Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Направи 20-секунден монтаж от трите най-трудни плана и гледай на целевия телефон. Запиши коя визия издържа всички, не коя печели един кадър.\n\nВземи доказателство, което би показал на друг монтажист: Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Показваш само слънчевия вход и обявяваш визията за завършена.\n\nГраницата: Еднакъв LUT не гарантира еднакъв стил върху кадри с различен вход и светлина."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Изгради визия, която преживява целия монтаж“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Добрата визия трябва да издържи различни лица, материали и планове в една история."},{"id":"b","label":"Показваш само слънчевия вход и обявяваш визията за завършена."},{"id":"c","label":"Копирай една силна настройка върху всичко и прегледай само първия кадър."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Добрата визия трябва да издържи различни лица, материали и планове в една история. Остави отделни етапи за техническа корекция и творческа визия. Избери два или три контролни кадъра: лице, продукт и крайно осветление. Настрой визията върху тях, вместо да копираш силна настройка по цялата времева линия."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Филм за работилница включва слънчев вход, тъмно интервю и близък план на меден продукт. Силният стил прави продукта червен и убива сенките.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Копирай една силна настройка върху всичко и прегледай само първия кадър."},{"id":"b","label":"Намали крайностите, тествай и трите сцени и настрой отделно кадъра с продукта преди одобрение."},{"id":"c","label":"Показваш само слънчевия вход и обявяваш визията за завършена."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Намали крайностите, тествай и трите сцени и настрой отделно кадъра с продукта преди одобрение. Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Копирай една силна настройка върху всичко и прегледай само първия кадър."},{"id":"c","label":"Еднакъв LUT не гарантира еднакъв стил върху кадри с различен вход и светлина."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Еднакъв LUT не гарантира еднакъв стил върху кадри с различен вход и светлина."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Добрата визия трябва да издържи различни лица, материали и планове в една история.","Намали крайностите, тествай и трите сцени и настрой отделно кадъра с продукта преди одобрение.","Не пропускай контрола: Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени."],"nextStep":"Направи 20-секунден монтаж от трите най-трудни плана и гледай на целевия телефон. Запиши коя визия издържа всички, не коя печели един кадър."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Еднакъв LUT не гарантира еднакъв стил върху кадри с различен вход и светлина.","items":[{"id":"s3","text":"Приложи умерена визия и коригирай отделните кадри."},{"id":"s1","text":"Коригирай технически три различни контролни кадъра."},{"id":"s4","text":"Изнеси кратка последователност и провери най-трудния кадър."},{"id":"s2","text":"Избери каква промяна подкрепя посланието."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Коригирай технически три различни контролни кадъра. → Избери каква промяна подкрепя посланието. → Приложи умерена визия и коригирай отделните кадри. → Изнеси кратка последователност и провери най-трудния кадър."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Появява се архивен клип от друг фотоапарат.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Копирай една силна настройка върху всичко и прегледай само първия кадър."},{"id":"b","label":"Нормализирай го към работната схема и провери дали стилът не разкрива шум или клипинг; ако трябва, използвай по-лек вариант."},{"id":"c","label":"Показваш само слънчевия вход и обявяваш визията за завършена."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Нормализирай го към работната схема и провери дали стилът не разкрива шум или клипинг; ако трябва, използвай по-лек вариант. Еднакъв LUT не гарантира еднакъв стил върху кадри с различен вход и светлина."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Визията принадлежи на целия филм. Най-красивият кадър е лош тест за устойчивост.\n\nРаботна карта:\n1. Коригирай технически три различни контролни кадъра.\n2. Избери каква промяна подкрепя посланието.\n3. Приложи умерена визия и коригирай отделните кадри.\n4. Изнеси кратка последователност и провери най-трудния кадър.\n\nКритерий за предаване: Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-16","title":"Teal и оранжево без пластмасова кожа","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще направиш разделяне на топло и студено, като запазиш кожа, продукт и естествена светлина.","hook":"Популярна визия може да превърне всяко лице в един и същ оранжев тон.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще направиш разделяне на топло и студено, като запазиш кожа, продукт и естествена светлина. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Популярна визия може да превърне всяко лице в един и същ оранжев тон."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Топъл субект и по-студен фон може да дадат отделяне, ако сцената и марката позволяват това.\n\nЗапочни с чиста корекция и избери ограничени области, вместо да завъртиш глобално всички сенки към синьо. Пази белите предмети и корпоративните цветове; не всяка сянка е синя и не всяка кожа трябва да е оранжева."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Избери кадър с лице, кадър с продукт и кадър със смесена светлина. Изгради лек вариант, после силен само за сравнение. При близък план следи порите, текстурата на косата и естествената разлика между хората. Ако корекцията работи само когато увеличиш сатурацията до край, тя вероятно не решава историята.\n\nГраница на решението: Teal и оранжево е творческа възможност, а не стандарт за всеки жанр, бранд или тон кожа."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Нормализирай входа и избери референтна сцена.\n2. Отдели фон и субект с умерени промени.\n3. Провери кожа, бели предмети и фирмени цветове.\n4. Прегледай срезовете на целевия екран и запази по-честния вариант.\n\nСтоп-сигнал: Защитаваш стила с аргумента, че така изглеждат „професионалните видеа“.\nВърни се към пробата: Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Видео за лекарски кабинет получава синкави сенки и силно оранжеви лица. Клиентът казва, че изглежда като екшън, а не като доверен разговор.\n\nРешение: Върни умерена неутралност в кожата и фона; ако студеният акцент остава, остави го само там, където подкрепя посланието.\n\nДоказателство, че работи: Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Защитаваш стила с аргумента, че така изглеждат „професионалните видеа“."},"after":{"label":"Как го поправяш","text":"Върни умерена неутралност в кожата и фона; ако студеният акцент остава, остави го само там, където подкрепя посланието. Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Покажи клиентски A/B с неутрална и стилизирана версия без етикетите „аматьорско“ и „професионално“. Попитай кое по-добре носи доверието на видеото.\n\nВземи доказателство, което би показал на друг монтажист: Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Защитаваш стила с аргумента, че така изглеждат „професионалните видеа“.\n\nГраницата: Teal и оранжево е творческа възможност, а не стандарт за всеки жанр, бранд или тон кожа."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Teal и оранжево без пластмасова кожа“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Защитаваш стила с аргумента, че така изглеждат „професионалните видеа“."},{"id":"b","label":"Оцвети всички тъмни пиксели в синьо и всички средни в оранжево."},{"id":"c","label":"Топъл субект и по-студен фон може да дадат отделяне, ако сцената и марката позволяват това."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Топъл субект и по-студен фон може да дадат отделяне, ако сцената и марката позволяват това. Започни с чиста корекция и избери ограничени области, вместо да завъртиш глобално всички сенки към синьо. Пази белите предмети и корпоративните цветове; не всяка сянка е синя и не всяка кожа трябва да е оранжева."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Видео за лекарски кабинет получава синкави сенки и силно оранжеви лица. Клиентът казва, че изглежда като екшън, а не като доверен разговор.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Върни умерена неутралност в кожата и фона; ако студеният акцент остава, остави го само там, където подкрепя посланието."},{"id":"b","label":"Защитаваш стила с аргумента, че така изглеждат „професионалните видеа“."},{"id":"c","label":"Оцвети всички тъмни пиксели в синьо и всички средни в оранжево."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Върни умерена неутралност в кожата и фона; ако студеният акцент остава, остави го само там, където подкрепя посланието. Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Оцвети всички тъмни пиксели в синьо и всички средни в оранжево."},{"id":"b","label":"Teal и оранжево е творческа възможност, а не стандарт за всеки жанр, бранд или тон кожа."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Teal и оранжево е творческа възможност, а не стандарт за всеки жанр, бранд или тон кожа."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Топъл субект и по-студен фон може да дадат отделяне, ако сцената и марката позволяват това.","Върни умерена неутралност в кожата и фона; ако студеният акцент остава, остави го само там, където подкрепя посланието.","Не пропускай контрола: Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо."],"nextStep":"Покажи клиентски A/B с неутрална и стилизирана версия без етикетите „аматьорско“ и „професионално“. Попитай кое по-добре носи доверието на видеото."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Teal и оранжево е творческа възможност, а не стандарт за всеки жанр, бранд или тон кожа.","items":[{"id":"s3","text":"Провери кожа, бели предмети и фирмени цветове."},{"id":"s1","text":"Нормализирай входа и избери референтна сцена."},{"id":"s4","text":"Прегледай срезовете на целевия екран и запази по-честния вариант."},{"id":"s2","text":"Отдели фон и субект с умерени промени."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Нормализирай входа и избери референтна сцена. → Отдели фон и субект с умерени промени. → Провери кожа, бели предмети и фирмени цветове. → Прегледай срезовете на целевия екран и запази по-честния вариант."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Същият материал ще се ползва в продуктова реклама с синя опаковка.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Пази разпознаваемия син цвят на продукта и оцени дали този стил изобщо е подходящ за продуктова версия."},{"id":"b","label":"Защитаваш стила с аргумента, че така изглеждат „професионалните видеа“."},{"id":"c","label":"Оцвети всички тъмни пиксели в синьо и всички средни в оранжево."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Пази разпознаваемия син цвят на продукта и оцени дали този стил изобщо е подходящ за продуктова версия. Teal и оранжево е творческа възможност, а не стандарт за всеки жанр, бранд или тон кожа."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Изборът на визия зависи от работа, която видеото трябва да свърши.\n\nРаботна карта:\n1. Нормализирай входа и избери референтна сцена.\n2. Отдели фон и субект с умерени промени.\n3. Провери кожа, бели предмети и фирмени цветове.\n4. Прегледай срезовете на целевия екран и запази по-честния вариант.\n\nКритерий за предаване: Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо."},"points":1,"required":false}]},{"module_id":"s02-m04","lesson_id":"pv04-17","title":"Финален проект: една сцена, три честни версии","subtitle":"Светлина и цвят — от сцена до надежден финален файл","objective":"Ще заснемеш една сцена и ще предадеш три сравними версии с доказуем избор на светлина и цвят.","hook":"Три филтъра върху различни кадри не доказват, че можеш да контролираш светлината.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще заснемеш една сцена и ще предадеш три сравними версии с доказуем избор на светлина и цвят. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Три филтъра върху различни кадри не доказват, че можеш да контролираш светлината."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Използвай един и същ кратък разговор и запази ясна връзка между светлината на терен, техническата корекция и стила.\n\nВерсия А показва чистата сцена; Б променя светлината или отраженията; В добавя умерена цветна визия след нормализиране. Постави един и същ важен предмет и лице във всички сравнения."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Запиши експонация, баланс, позиция на източника и какво си променил между вариантите. Не подменяй речта и кадрирането толкова, че сравнението да стане нечестно. Проверявай клипинг, кожа, отблясък и бранд цвят върху експортирани файлове. При провал избери варианта, който изпълнява задачата, дори да е по-скромен.\n\nГраница на решението: Няма универсално най-добър вариант; целта и ограниченията на конкретния клиент решават."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Заснеми базов кратък кадър и контролен still.\n2. Промени един светлинен фактор и запиши втори вариант.\n3. Коригирай технически, после направи отделна стилова версия.\n4. Изнеси A/B/C и сравни по предварително записани критерии.\n\nСтоп-сигнал: Избираш В, защото най-силно привлича окото, без да погледнеш истинския продукт.\nВърни се към пробата: Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Малка сладкарница иска 20 секунди за нов продукт. Версия А е четима, Б добавя контраст със черен картон, В прави продукта неестествено червен.\n\nРешение: Върни фирмения цвят и остави контраста от Б; изнеси трите файла и покажи защо избираш финалния.\n\nДоказателство, че работи: Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Избираш В, защото най-силно привлича окото, без да погледнеш истинския продукт."},"after":{"label":"Как го поправяш","text":"Върни фирмения цвят и остави контраста от Б; изнеси трите файла и покажи защо избираш финалния. Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Изпълни проекта с телефон или камера и един прозорец/лампа. Сравнявай финалните файлове, не екранни снимки от различни приложения.\n\nВземи доказателство, което би показал на друг монтажист: Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Избираш В, защото най-силно привлича окото, без да погледнеш истинския продукт.\n\nГраницата: Няма универсално най-добър вариант; целта и ограниченията на конкретния клиент решават."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Финален проект: една сцена, три честни версии“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Предай само най-ефектния файл без контролно сравнение."},{"id":"b","label":"Използвай един и същ кратък разговор и запази ясна връзка между светлината на терен, техническата корекция и стила."},{"id":"c","label":"Избираш В, защото най-силно привлича окото, без да погледнеш истинския продукт."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Използвай един и същ кратък разговор и запази ясна връзка между светлината на терен, техническата корекция и стила. Версия А показва чистата сцена; Б променя светлината или отраженията; В добавя умерена цветна визия след нормализиране. Постави един и същ важен предмет и лице във всички сравнения."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Малка сладкарница иска 20 секунди за нов продукт. Версия А е четима, Б добавя контраст със черен картон, В прави продукта неестествено червен.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Избираш В, защото най-силно привлича окото, без да погледнеш истинския продукт."},{"id":"b","label":"Предай само най-ефектния файл без контролно сравнение."},{"id":"c","label":"Върни фирмения цвят и остави контраста от Б; изнеси трите файла и покажи защо избираш финалния."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Върни фирмения цвят и остави контраста от Б; изнеси трите файла и покажи защо избираш финалния. Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Няма универсално най-добър вариант; целта и ограниченията на конкретния клиент решават."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Предай само най-ефектния файл без контролно сравнение."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Няма универсално най-добър вариант; целта и ограниченията на конкретния клиент решават."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Използвай един и същ кратък разговор и запази ясна връзка между светлината на терен, техническата корекция и стила.","Върни фирмения цвят и остави контраста от Б; изнеси трите файла и покажи защо избираш финалния.","Не пропускай контрола: Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат."],"nextStep":"Изпълни проекта с телефон или камера и един прозорец/лампа. Сравнявай финалните файлове, не екранни снимки от различни приложения."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Няма универсално най-добър вариант; целта и ограниченията на конкретния клиент решават.","items":[{"id":"s3","text":"Коригирай технически, после направи отделна стилова версия."},{"id":"s1","text":"Заснеми базов кратък кадър и контролен still."},{"id":"s4","text":"Изнеси A/B/C и сравни по предварително записани критерии."},{"id":"s2","text":"Промени един светлинен фактор и запиши втори вариант."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Заснеми базов кратък кадър и контролен still. → Промени един светлинен фактор и запиши втори вариант. → Коригирай технически, после направи отделна стилова версия. → Изнеси A/B/C и сравни по предварително записани критерии."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът сменя целта: видеото трябва да служи и като продуктова инструкция.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Избираш В, защото най-силно привлича окото, без да погледнеш истинския продукт."},{"id":"b","label":"Предай само най-ефектния файл без контролно сравнение."},{"id":"c","label":"Прегледай трите версии за точност на продукта и четимост на демонстрацията; избери или адаптирай най-ясната."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Прегледай трите версии за точност на продукта и четимост на демонстрацията; избери или адаптирай най-ясната. Няма универсално най-добър вариант; целта и ограниченията на конкретния клиент решават."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Проектът е завършен, когато можеш да покажеш както творческия избор, така и границите му.\n\nРаботна карта:\n1. Заснеми базов кратък кадър и контролен still.\n2. Промени един светлинен фактор и запиши втори вариант.\n3. Коригирай технически, после направи отделна стилова версия.\n4. Изнеси A/B/C и сравни по предварително записани критерии.\n\nКритерий за предаване: Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат."},"points":1,"required":false}]},{"module_id":"s02-m05","lesson_id":"pv05-01","title":"Слушай преди да включиш камерата","subtitle":"Звук — запис, чистене и права","objective":"Ще откриеш шум, реверберация и повреден запис с кратка слушателска проба.","hook":"Изображението е остро, но хладилникът заглушава цялото интервю.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще откриеш шум, реверберация и повреден запис с кратка слушателска проба. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Изображението е остро, но хладилникът заглушава цялото интервю."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Затвори очи и слушай мястото за глас, тишина и внезапни звуци, преди да фиксираш кадъра.\n\nСлушай с надеждни слушалки директно от записващото устройство, не само от монитора на камерата без аудио. Отдели постоянен шум, отражения на стаята и случайни събития като врата или телефон."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Запиши 20 секунди нормална реч и поне 10 секунди тишина на същото място. Сравни какво се чува при паузите и под думите. Реверберацията не се решава със същия бутон като постоянен шум; най-евтината поправка често е да доближиш микрофона и да смениш позицията. Ако екипът трябва да остане на мястото, отбележи рисковите звуци в снимачния план.\n\nГраница на решението: Кратката проба не гарантира, че шумът няма да се появи по-късно; слушай и по време на снимките."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Слушай помещението в тишина и назови три конкретни звука.\n2. Запиши кратка реч и тишина с избрания микрофон.\n3. Пусни пробата през слушалки от устройството.\n4. Промени място или позиция и повтори при същия глас.\n\nСтоп-сигнал: Пропускаш пробата, защото шумът ще се „махне с AI“.\nВърни се към пробата: В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Собственик на фурна говори ясно, но по време на пробата фурната включва вентилатор на всеки няколко минути.\n\nРешение: Уговори паузи за шумния цикъл или премести разговора; дръж микрофона по-близо и запиши нова проба.\n\nДоказателство, че работи: В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Пропускаш пробата, защото шумът ще се „махне с AI“."},"after":{"label":"Как го поправяш","text":"Уговори паузи за шумния цикъл или премести разговора; дръж микрофона по-близо и запиши нова проба. В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Направи две проби на същия глас: в центъра на стаята и близо до меки повърхности. Изравни силата при сравнение, за да оценяваш акустиката, не по-силния файл.\n\nВземи доказателство, което би показал на друг монтажист: В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Пропускаш пробата, защото шумът ще се „махне с AI“.\n\nГраницата: Кратката проба не гарантира, че шумът няма да се появи по-късно; слушай и по време на снимките."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Слушай преди да включиш камерата“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Затвори очи и слушай мястото за глас, тишина и внезапни звуци, преди да фиксираш кадъра."},{"id":"b","label":"Пропускаш пробата, защото шумът ще се „махне с AI“."},{"id":"c","label":"Усили гласовия канал до максимум, за да скриеш реверберацията."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Затвори очи и слушай мястото за глас, тишина и внезапни звуци, преди да фиксираш кадъра. Слушай с надеждни слушалки директно от записващото устройство, не само от монитора на камерата без аудио. Отдели постоянен шум, отражения на стаята и случайни събития като врата или телефон."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Собственик на фурна говори ясно, но по време на пробата фурната включва вентилатор на всеки няколко минути.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Усили гласовия канал до максимум, за да скриеш реверберацията."},{"id":"b","label":"Уговори паузи за шумния цикъл или премести разговора; дръж микрофона по-близо и запиши нова проба."},{"id":"c","label":"Пропускаш пробата, защото шумът ще се „махне с AI“."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Уговори паузи за шумния цикъл или премести разговора; дръж микрофона по-близо и запиши нова проба. В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Усили гласовия канал до максимум, за да скриеш реверберацията."},{"id":"c","label":"Кратката проба не гарантира, че шумът няма да се появи по-късно; слушай и по време на снимките."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Кратката проба не гарантира, че шумът няма да се появи по-късно; слушай и по време на снимките."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Затвори очи и слушай мястото за глас, тишина и внезапни звуци, преди да фиксираш кадъра.","Уговори паузи за шумния цикъл или премести разговора; дръж микрофона по-близо и запиши нова проба.","Не пропускай контрола: В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите."],"nextStep":"Направи две проби на същия глас: в центъра на стаята и близо до меки повърхности. Изравни силата при сравнение, за да оценяваш акустиката, не по-силния файл."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Кратката проба не гарантира, че шумът няма да се появи по-късно; слушай и по време на снимките.","items":[{"id":"s3","text":"Пусни пробата през слушалки от устройството."},{"id":"s1","text":"Слушай помещението в тишина и назови три конкретни звука."},{"id":"s4","text":"Промени място или позиция и повтори при същия глас."},{"id":"s2","text":"Запиши кратка реч и тишина с избрания микрофон."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Слушай помещението в тишина и назови три конкретни звука. → Запиши кратка реч и тишина с избрания микрофон. → Пусни пробата през слушалки от устройството. → Промени място или позиция и повтори при същия глас."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Вратата към улицата трябва да остане отворена за работата на обекта.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Усили гласовия канал до максимум, за да скриеш реверберацията."},{"id":"b","label":"Промени ориентацията на микрофона и времето на запис; ако шумът заглушава думите, уговори друго място."},{"id":"c","label":"Пропускаш пробата, защото шумът ще се „махне с AI“."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Промени ориентацията на микрофона и времето на запис; ако шумът заглушава думите, уговори друго място. Кратката проба не гарантира, че шумът няма да се появи по-късно; слушай и по време на снимките."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Тишината между репликите е част от материала. Ако тя е различна при всеки дубъл, монтажът ще разкрие срезовете.\n\nРаботна карта:\n1. Слушай помещението в тишина и назови три конкретни звука.\n2. Запиши кратка реч и тишина с избрания микрофон.\n3. Пусни пробата през слушалки от устройството.\n4. Промени място или позиция и повтори при същия глас.\n\nКритерий за предаване: В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите."},"points":1,"required":false}]},{"module_id":"s02-m05","lesson_id":"pv05-02","title":"Петличка, насочен или вграден микрофон?","subtitle":"Звук — запис, чистене и права","objective":"Ще подбереш микрофон според разстояние, движение, дрехи и среда.","hook":"Скъп насочен микрофон от три метра записва по-ясно стаята, отколкото гласа.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще подбереш микрофон според разстояние, движение, дрехи и среда. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Скъп насочен микрофон от три метра записва по-ясно стаята, отколкото гласа."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Положението на микрофона и прякото звучене на гласа често имат по-голям ефект от името на модела.\n\nПетличката следва движещ се говорител, но може да търка дреха. Бумът стои извън кадър и дава естествен глас, ако може да се държи близо. Вграденият микрофон е резервен или синхронизиращ източник, когато камерата е далеч."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"При петличка направи тест при истинските движения и дрехи; проверявай триене, бижута и проводник. При бум провери дали микрофонът остава насочен към устата, а не към отразяваща стена. Ако снимачният план се променя, резервен канал или втори запис може да спаси интервюто само ако е бил проверен преди снимките.\n\nГраница на решението: Насоченият микрофон не премахва ехо, когато е твърде далеч; полярният модел има граници."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Опиши движение, кадриране и облекло.\n2. Постави наличния микрофон възможно най-близо без да влиза в кадър.\n3. Запиши реч при реалните движения и слушай за триене.\n4. Избери основен и проверен резервен източник.\n\nСтоп-сигнал: Оставяш микрофона на камерата като „професионален shotgun“ и приемаш кухия звук.\nВърни се към пробата: В цялото навеждане речта остава разбираема и няма силно търкане на плат."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Говорител в работилница се навежда над маса. Петличката е скрита под яке, а насоченият микрофон е закрепен върху камерата на два метра.\n\nРешение: Премести насочения микрофон близо над кадъра или закрепи петличката без триене; прослушай реалното движение.\n\nДоказателство, че работи: В цялото навеждане речта остава разбираема и няма силно търкане на плат."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Оставяш микрофона на камерата като „професионален shotgun“ и приемаш кухия звук."},"after":{"label":"Как го поправяш","text":"Премести насочения микрофон близо над кадъра или закрепи петличката без триене; прослушай реалното движение. В цялото навеждане речта остава разбираема и няма силно търкане на плат."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Запиши една и съща фраза с вграден, петличка и бум при реалната дистанция. Изравни сила в прослушването и избери по разбираемост.\n\nВземи доказателство, което би показал на друг монтажист: В цялото навеждане речта остава разбираема и няма силно търкане на плат.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Оставяш микрофона на камерата като „професионален shotgun“ и приемаш кухия звук.\n\nГраницата: Насоченият микрофон не премахва ехо, когато е твърде далеч; полярният модел има граници."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Петличка, насочен или вграден микрофон?“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Оставяш микрофона на камерата като „професионален shotgun“ и приемаш кухия звук."},{"id":"b","label":"Повиши чувствителността на камерата, за да компенсираш далечния микрофон."},{"id":"c","label":"Положението на микрофона и прякото звучене на гласа често имат по-голям ефект от името на модела."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Положението на микрофона и прякото звучене на гласа често имат по-голям ефект от името на модела. Петличката следва движещ се говорител, но може да търка дреха. Бумът стои извън кадър и дава естествен глас, ако може да се държи близо. Вграденият микрофон е резервен или синхронизиращ източник, когато камерата е далеч."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Говорител в работилница се навежда над маса. Петличката е скрита под яке, а насоченият микрофон е закрепен върху камерата на два метра.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Премести насочения микрофон близо над кадъра или закрепи петличката без триене; прослушай реалното движение."},{"id":"b","label":"Оставяш микрофона на камерата като „професионален shotgun“ и приемаш кухия звук."},{"id":"c","label":"Повиши чувствителността на камерата, за да компенсираш далечния микрофон."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Премести насочения микрофон близо над кадъра или закрепи петличката без триене; прослушай реалното движение. В цялото навеждане речта остава разбираема и няма силно търкане на плат."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Повиши чувствителността на камерата, за да компенсираш далечния микрофон."},{"id":"b","label":"Насоченият микрофон не премахва ехо, когато е твърде далеч; полярният модел има граници."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Насоченият микрофон не премахва ехо, когато е твърде далеч; полярният модел има граници."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Положението на микрофона и прякото звучене на гласа често имат по-голям ефект от името на модела.","Премести насочения микрофон близо над кадъра или закрепи петличката без триене; прослушай реалното движение.","Не пропускай контрола: В цялото навеждане речта остава разбираема и няма силно търкане на плат."],"nextStep":"Запиши една и съща фраза с вграден, петличка и бум при реалната дистанция. Изравни сила в прослушването и избери по разбираемост."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Насоченият микрофон не премахва ехо, когато е твърде далеч; полярният модел има граници.","items":[{"id":"s3","text":"Запиши реч при реалните движения и слушай за триене."},{"id":"s1","text":"Опиши движение, кадриране и облекло."},{"id":"s4","text":"Избери основен и проверен резервен източник."},{"id":"s2","text":"Постави наличния микрофон възможно най-близо без да влиза в кадър."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Опиши движение, кадриране и облекло. → Постави наличния микрофон възможно най-близо без да влиза в кадър. → Запиши реч при реалните движения и слушай за триене. → Избери основен и проверен резервен източник."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Говорителят сменя якето с риза, която шумоли при допир.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Тествай ново място за петличката или използвай близък бум и избери след реален запис."},{"id":"b","label":"Оставяш микрофона на камерата като „професионален shotgun“ и приемаш кухия звук."},{"id":"c","label":"Повиши чувствителността на камерата, за да компенсираш далечния микрофон."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Тествай ново място за петличката или използвай близък бум и избери след реален запис. Насоченият микрофон не премахва ехо, когато е твърде далеч; полярният модел има граници."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Микрофонът е част от сцената и гардероба. Мониторингът продължава след смяна на дрехите.\n\nРаботна карта:\n1. Опиши движение, кадриране и облекло.\n2. Постави наличния микрофон възможно най-близо без да влиза в кадър.\n3. Запиши реч при реалните движения и слушай за триене.\n4. Избери основен и проверен резервен източник.\n\nКритерий за предаване: В цялото навеждане речта остава разбираема и няма силно търкане на плат."},"points":1,"required":false}]},{"module_id":"s02-m05","lesson_id":"pv05-03","title":"Резерв за гласа без клипинг","subtitle":"Звук — запис, чистене и права","objective":"Ще настроиш входно ниво, ще слушаш пиковете и ще знаеш какво 32-bit float може и не може да спаси.","hook":"Една силна дума удря тавана на записа; шумоподтискането няма как да върне отрязаната сричка.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще настроиш входно ниво, ще слушаш пиковете и ще знаеш какво 32-bit float може и не може да спаси. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Една силна дума удря тавана на записа; шумоподтискането няма как да върне отрязаната сричка."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Дай запас за най-силната очаквана реплика и прослушай пробата от началото до края.\n\nВходният gain определя колко силен сигнал стига до записващата верига; ако аналогова част или безжичен предавател претовари, по-късен файлов формат не връща изгубеното. 32-bit float записващи устройства могат да дадат допълнителна гъвкавост при обработка, но работят в границите на целия хардуерен път."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Помоли говорителя да произнесе реална силна реплика, не тихото „едно, две“. Прослушай и гледай пиковете, включително когато се смее или вика. Ако включиш safety track или втори канал на по-ниско ниво, увери се, че той записва отделно и наистина може да се използва. Не наричай тази система „Log аудио“: при звук важният въпрос е къде се получава клипинг.\n\nГраница на решението: 32-bit float не оправя микрофонен капсул или предавател, който се претоварва преди файла."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Провери захранване, вход и място на микрофона.\n2. Настрой запаса по най-силната реална реплика.\n3. Запиши и прослушай силен и тих пасаж.\n4. Провери резервния канал и запази настройката преди интервю.\n\nСтоп-сигнал: Намаляваш плъзгача в монтажа и обявяваш отрязаната фраза за поправена.\nВърни се към пробата: Силната дума е без плосък отрязан пик и без чуваемо пращене; тихият пасаж остава използваем."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Човек говори тихо в началото, после разказва развълнувано. Първите проби са добри, но при силната фраза звукът пука.\n\nРешение: Върни входното ниво на записващото устройство или на предавателя, направи нов силен тест и провери резервен канал.\n\nДоказателство, че работи: Силната дума е без плосък отрязан пик и без чуваемо пращене; тихият пасаж остава използваем."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Намаляваш плъзгача в монтажа и обявяваш отрязаната фраза за поправена."},"after":{"label":"Как го поправяш","text":"Върни входното ниво на записващото устройство или на предавателя, направи нов силен тест и провери резервен канал. Силната дума е без плосък отрязан пик и без чуваемо пращене; тихият пасаж остава използваем."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Запиши проба с тих говор, силна дума и смях. Върни се към оригиналния файл, не към обработен превю клип, и прослушай с паузи.\n\nВземи доказателство, което би показал на друг монтажист: Силната дума е без плосък отрязан пик и без чуваемо пращене; тихият пасаж остава използваем.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Намаляваш плъзгача в монтажа и обявяваш отрязаната фраза за поправена.\n\nГраницата: 32-bit float не оправя микрофонен капсул или предавател, който се претоварва преди файла."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Резерв за гласа без клипинг“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Пиши „Log аудио“ в инструкциите и разчитай файловият формат да възстанови клипинг."},{"id":"b","label":"Дай запас за най-силната очаквана реплика и прослушай пробата от началото до края."},{"id":"c","label":"Намаляваш плъзгача в монтажа и обявяваш отрязаната фраза за поправена."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Дай запас за най-силната очаквана реплика и прослушай пробата от началото до края. Входният gain определя колко силен сигнал стига до записващата верига; ако аналогова част или безжичен предавател претовари, по-късен файлов формат не връща изгубеното. 32-bit float записващи устройства могат да дадат допълнителна гъвкавост при обработка, но работят в границите на целия хардуерен път."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Човек говори тихо в началото, после разказва развълнувано. Първите проби са добри, но при силната фраза звукът пука.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Намаляваш плъзгача в монтажа и обявяваш отрязаната фраза за поправена."},{"id":"b","label":"Пиши „Log аудио“ в инструкциите и разчитай файловият формат да възстанови клипинг."},{"id":"c","label":"Върни входното ниво на записващото устройство или на предавателя, направи нов силен тест и провери резервен канал."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Върни входното ниво на записващото устройство или на предавателя, направи нов силен тест и провери резервен канал. Силната дума е без плосък отрязан пик и без чуваемо пращене; тихият пасаж остава използваем."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"32-bit float не оправя микрофонен капсул или предавател, който се претоварва преди файла."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Пиши „Log аудио“ в инструкциите и разчитай файловият формат да възстанови клипинг."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"32-bit float не оправя микрофонен капсул или предавател, който се претоварва преди файла."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Дай запас за най-силната очаквана реплика и прослушай пробата от началото до края.","Върни входното ниво на записващото устройство или на предавателя, направи нов силен тест и провери резервен канал.","Не пропускай контрола: Силната дума е без плосък отрязан пик и без чуваемо пращене; тихият пасаж остава използваем."],"nextStep":"Запиши проба с тих говор, силна дума и смях. Върни се към оригиналния файл, не към обработен превю клип, и прослушай с паузи."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. 32-bit float не оправя микрофонен капсул или предавател, който се претоварва преди файла.","items":[{"id":"s3","text":"Запиши и прослушай силен и тих пасаж."},{"id":"s1","text":"Провери захранване, вход и място на микрофона."},{"id":"s4","text":"Провери резервния канал и запази настройката преди интервю."},{"id":"s2","text":"Настрой запаса по най-силната реална реплика."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Провери захранване, вход и място на микрофона. → Настрой запаса по най-силната реална реплика. → Запиши и прослушай силен и тих пасаж. → Провери резервния канал и запази настройката преди интервю."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Интервюто се мести до шумна машина и човекът започва да говори по-силно.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Намаляваш плъзгача в монтажа и обявяваш отрязаната фраза за поправена."},{"id":"b","label":"Пиши „Log аудио“ в инструкциите и разчитай файловият формат да възстанови клипинг."},{"id":"c","label":"Настрой входа и позицията наново по новата силна реплика, прослушай през слушалки и провери резервния запис."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Настрой входа и позицията наново по новата силна реплика, прослушай през слушалки и провери резервния запис. 32-bit float не оправя микрофонен капсул или предавател, който се претоварва преди файла."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Предвиждай най-силния момент. Оставеният запас е евтин, изгубената сричка е скъпа.\n\nРаботна карта:\n1. Провери захранване, вход и място на микрофона.\n2. Настрой запаса по най-силната реална реплика.\n3. Запиши и прослушай силен и тих пасаж.\n4. Провери резервния канал и запази настройката преди интервю.\n\nКритерий за предаване: Силната дума е без плосък отрязан пик и без чуваемо пращене; тихият пасаж остава използваем."},"points":1,"required":false}]},{"module_id":"s02-m05","lesson_id":"pv05-04","title":"Тихо място не значи добра акустика","subtitle":"Звук — запис, чистене и права","objective":"Ще оцениш шум и отражения и ще подбереш място за разбираем глас.","hook":"Празна тиха зала звучи като тунел, докато малък шумен офис може да даде по-четима реч.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще оцениш шум и отражения и ще подбереш място за разбираем глас. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Празна тиха зала звучи като тунел, докато малък шумен офис може да даде по-четима реч."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Гледай едновременно съотношението на гласа към шума и колко дълго отекват думите.\n\nГолемите голи повърхности връщат речта към микрофона. Мека мебел, завеси и близък микрофон често подобряват разбираемостта. Изключването на климатик може да помогне само ако е позволено и безопасно за мястото."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Направи проба със същия човек и микрофон в две възможни позиции. Пази разстоянието до устата сравнимо и не оценявай по сила на плейъра. Отбележи периодични звуци като каса, превозно средство или хладилник. Ако шумът не може да се спре, търси място, където близкият глас преобладава и където имаш контрол върху паузите.\n\nГраница на решението: Не покривай пожарно оборудване и не прекъсвай вентилация без разрешение и оценка на място."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Слушай постоянното и периодичното в две локации.\n2. Запиши една и съща фраза от еднаква дистанция.\n3. Прослушай думите и паузите при изравнена сила.\n4. Избери място и уговори контрол над непредвидимия шум.\n\nСтоп-сигнал: Избираш коридора само по измереното ниво на фонов шум.\nВърни се към пробата: Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Снимаш лекар в коридор и в кабинет. Коридорът е по-тих на слух, но гласът се връща от стените.\n\nРешение: Сравни пробите за разбираемост; избери кабинета или намери по-близка позиция и меки повърхности.\n\nДоказателство, че работи: Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Избираш коридора само по измереното ниво на фонов шум."},"after":{"label":"Как го поправяш","text":"Сравни пробите за разбираемост; избери кабинета или намери по-близка позиция и меки повърхности. Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Запиши тест „една фраза + пет секунди пауза“ в две стаи. Провери отражението в края на думите и фоновите цикли.\n\nВземи доказателство, което би показал на друг монтажист: Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Избираш коридора само по измереното ниво на фонов шум.\n\nГраницата: Не покривай пожарно оборудване и не прекъсвай вентилация без разрешение и оценка на място."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Тихо място не значи добра акустика“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Гледай едновременно съотношението на гласа към шума и колко дълго отекват думите."},{"id":"b","label":"Избираш коридора само по измереното ниво на фонов шум."},{"id":"c","label":"Добави дебел килим извън мястото на отражение и приеми, че всяко ехо е решено."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Гледай едновременно съотношението на гласа към шума и колко дълго отекват думите. Големите голи повърхности връщат речта към микрофона. Мека мебел, завеси и близък микрофон често подобряват разбираемостта. Изключването на климатик може да помогне само ако е позволено и безопасно за мястото."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Снимаш лекар в коридор и в кабинет. Коридорът е по-тих на слух, но гласът се връща от стените.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Добави дебел килим извън мястото на отражение и приеми, че всяко ехо е решено."},{"id":"b","label":"Сравни пробите за разбираемост; избери кабинета или намери по-близка позиция и меки повърхности."},{"id":"c","label":"Избираш коридора само по измереното ниво на фонов шум."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Сравни пробите за разбираемост; избери кабинета или намери по-близка позиция и меки повърхности. Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Добави дебел килим извън мястото на отражение и приеми, че всяко ехо е решено."},{"id":"c","label":"Не покривай пожарно оборудване и не прекъсвай вентилация без разрешение и оценка на място."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Не покривай пожарно оборудване и не прекъсвай вентилация без разрешение и оценка на място."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Гледай едновременно съотношението на гласа към шума и колко дълго отекват думите.","Сравни пробите за разбираемост; избери кабинета или намери по-близка позиция и меки повърхности.","Не пропускай контрола: Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая."],"nextStep":"Запиши тест „една фраза + пет секунди пауза“ в две стаи. Провери отражението в края на думите и фоновите цикли."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Не покривай пожарно оборудване и не прекъсвай вентилация без разрешение и оценка на място.","items":[{"id":"s3","text":"Прослушай думите и паузите при изравнена сила."},{"id":"s1","text":"Слушай постоянното и периодичното в две локации."},{"id":"s4","text":"Избери място и уговори контрол над непредвидимия шум."},{"id":"s2","text":"Запиши една и съща фраза от еднаква дистанция."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Слушай постоянното и периодичното в две локации. → Запиши една и съща фраза от еднаква дистанция. → Прослушай думите и паузите при изравнена сила. → Избери място и уговори контрол над непредвидимия шум."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Планираното помещение не е достъпно и остава само кух коридор.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Добави дебел килим извън мястото на отражение и приеми, че всяко ехо е решено."},{"id":"b","label":"Доближи микрофона, промени ориентацията и ограничи кадъра до по-акустично защитено място; повтори теста."},{"id":"c","label":"Избираш коридора само по измереното ниво на фонов шум."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Доближи микрофона, промени ориентацията и ограничи кадъра до по-акустично защитено място; повтори теста. Не покривай пожарно оборудване и не прекъсвай вентилация без разрешение и оценка на място."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Гласът трябва да работи и на телефонен говорител, не само на студийни слушалки.\n\nРаботна карта:\n1. Слушай постоянното и периодичното в две локации.\n2. Запиши една и съща фраза от еднаква дистанция.\n3. Прослушай думите и паузите при изравнена сила.\n4. Избери място и уговори контрол над непредвидимия шум.\n\nКритерий за предаване: Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая."},"points":1,"required":false}]},{"module_id":"s02-m05","lesson_id":"pv05-05","title":"Voiceover: запис и обработка без пластмасов глас","subtitle":"Звук — запис, чистене и права","objective":"Ще запишеш чист глас зад кадър и ще обработиш шума, без да изтриеш сричките.","hook":"Гласът е записан в килер без шум, но дишането и дрехите звучат по-силно от текста.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще запишеш чист глас зад кадър и ще обработиш шума, без да изтриеш сричките. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Гласът е записан в килер без шум, но дишането и дрехите звучат по-силно от текста."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Качественият voiceover започва от текст, тиха сцена, постоянна дистанция и няколко контролни дубъла.\n\nПостави микрофона леко извън директната струя въздух и използвай поп филтър при нужда. Маркирай позицията на човека и говори със същата енергия. Запиши проба и тишина на място."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"В монтажа първо избери най-ясния дубъл и сглоби естествени паузи. Ползвай шумоподтискане умерено; силна обработка може да изяде съгласните и да остави метален оттенък. Компресията изравнява големите разлики, но не замества позицията на микрофона. Слушай на слушалки и на обикновен телефон, като сравняваш еднаква крайна сила.\n\nГраница на решението: Формули за еднакъв EQ или LUFS не са универсална настройка за всеки говорител и всяка платформа."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Прочети текста на глас и махни неудобните думи.\n2. Маркирай позиция, направи проба с нормална интонация.\n3. Избери дубъл и почисти очевидните шумове.\n4. Експортирай и провери паузите и разбираемостта на телефон.\n\nСтоп-сигнал: Пускаш агресивен denoise върху целия дубъл 2 и изтъняваш всички съгласни.\nВърни се към пробата: В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"За реклама на сладкарница имаш 30 секунди глас. Дубъл 1 е чист, но бърз; дубъл 2 е по-естествен, но има една шумна глътка.\n\nРешение: Избери естествения дубъл, почисти локално глътката или презапиши изречението при същата позиция.\n\nДоказателство, че работи: В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Пускаш агресивен denoise върху целия дубъл 2 и изтъняваш всички съгласни."},"after":{"label":"Как го поправяш","text":"Избери естествения дубъл, почисти локално глътката или презапиши изречението при същата позиция. В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Направи две кратки версии: без обработка и с умерена обработка. Изравни силата при слушане, за да не бъркаш „по-силно“ с „по-добре“.\n\nВземи доказателство, което би показал на друг монтажист: В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Пускаш агресивен denoise върху целия дубъл 2 и изтъняваш всички съгласни.\n\nГраницата: Формули за еднакъв EQ или LUFS не са универсална настройка за всеки говорител и всяка платформа."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Voiceover: запис и обработка без пластмасов глас“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Пускаш агресивен denoise върху целия дубъл 2 и изтъняваш всички съгласни."},{"id":"b","label":"Повиши компресията, за да направиш тихите грешки еднакво силни с правилните думи."},{"id":"c","label":"Качественият voiceover започва от текст, тиха сцена, постоянна дистанция и няколко контролни дубъла."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Качественият voiceover започва от текст, тиха сцена, постоянна дистанция и няколко контролни дубъла. Постави микрофона леко извън директната струя въздух и използвай поп филтър при нужда. Маркирай позицията на човека и говори със същата енергия. Запиши проба и тишина на място."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"За реклама на сладкарница имаш 30 секунди глас. Дубъл 1 е чист, но бърз; дубъл 2 е по-естествен, но има една шумна глътка.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Избери естествения дубъл, почисти локално глътката или презапиши изречението при същата позиция."},{"id":"b","label":"Пускаш агресивен denoise върху целия дубъл 2 и изтъняваш всички съгласни."},{"id":"c","label":"Повиши компресията, за да направиш тихите грешки еднакво силни с правилните думи."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Избери естествения дубъл, почисти локално глътката или презапиши изречението при същата позиция. В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Повиши компресията, за да направиш тихите грешки еднакво силни с правилните думи."},{"id":"b","label":"Формули за еднакъв EQ или LUFS не са универсална настройка за всеки говорител и всяка платформа."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Формули за еднакъв EQ или LUFS не са универсална настройка за всеки говорител и всяка платформа."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Качественият voiceover започва от текст, тиха сцена, постоянна дистанция и няколко контролни дубъла.","Избери естествения дубъл, почисти локално глътката или презапиши изречението при същата позиция.","Не пропускай контрола: В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа."],"nextStep":"Направи две кратки версии: без обработка и с умерена обработка. Изравни силата при слушане, за да не бъркаш „по-силно“ с „по-добре“."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Формули за еднакъв EQ или LUFS не са универсална настройка за всеки говорител и всяка платформа.","items":[{"id":"s3","text":"Избери дубъл и почисти очевидните шумове."},{"id":"s1","text":"Прочети текста на глас и махни неудобните думи."},{"id":"s4","text":"Експортирай и провери паузите и разбираемостта на телефон."},{"id":"s2","text":"Маркирай позиция, направи проба с нормална интонация."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Прочети текста на глас и махни неудобните думи. → Маркирай позиция, направи проба с нормална интонация. → Избери дубъл и почисти очевидните шумове. → Експортирай и провери паузите и разбираемостта на телефон."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът променя последното изречение след като цялата озвучка е записана.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Презапиши изречението с еднаква позиция, помещение и тон; сравни с двете съседни реплики."},{"id":"b","label":"Пускаш агресивен denoise върху целия дубъл 2 и изтъняваш всички съгласни."},{"id":"c","label":"Повиши компресията, за да направиш тихите грешки еднакво силни с правилните думи."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Презапиши изречението с еднаква позиция, помещение и тон; сравни с двете съседни реплики. Формули за еднакъв EQ или LUFS не са универсална настройка за всеки говорител и всяка платформа."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Пази няколко секунди истинска тишина от помещението за естествени монтажни преходи.\n\nРаботна карта:\n1. Прочети текста на глас и махни неудобните думи.\n2. Маркирай позиция, направи проба с нормална интонация.\n3. Избери дубъл и почисти очевидните шумове.\n4. Експортирай и провери паузите и разбираемостта на телефон.\n\nКритерий за предаване: В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа."},"points":1,"required":false}]},{"module_id":"s02-m05","lesson_id":"pv05-06","title":"Синхрон между отделен звук и картина","subtitle":"Звук — запис, чистене и права","objective":"Ще съчетаеш външен запис и видео, ще откриеш отместване и ще провериш дълъг дубъл.","hook":"Началото е синхронно, а след половин час устните вече изпреварват гласа.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще съчетаеш външен запис и видео, ще откриеш отместване и ще провериш дълъг дубъл. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Началото е синхронно, а след половин час устните вече изпреварват гласа."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Създай ясен общ маркер за записите и провери синхрона и в началото, и в края.\n\nПляскане в кадър оставя видим и звуков пик; scratch audio от камерата също помага при синхронизиране. Поддържай отделните файлове организирани по дубъл, устройство и време."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"При дълги записи може да има дрейф заради различни часовници, променлива кадрова честота или грешно интерпретирани настройки. Не го поправяй само с преместване на целия аудио клип, ако началото е наред, а краят не е. Проверявай говорни съгласни на поне две далечни места във времевата линия и при нужда подготви коректен работен формат/настройка.\n\nГраница на решението: Пляскането фиксира начална точка, не гарантира липса на дрейф по цялата дължина."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Пусни външен рекордер и камера, после направи видим маркер.\n2. Кръсти и архивирай файловете по дубъл.\n3. Синхронизирай началото по маркера или камерата.\n4. Провери говор в началото и края на дългия клип.\n\nСтоп-сигнал: Местиш целия звук с две рамки и разваляш началото.\nВърни се към пробата: Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"40-минутен разговор от телефон и външен рекордер започва точно, но след 35 минути устните не съвпадат.\n\nРешение: Провери дали телефонът е записал с променлива кадрова честота и дали проектът интерпретира файловете правилно; направи контролирано съвместимо копие при нужда.\n\nДоказателство, че работи: Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Местиш целия звук с две рамки и разваляш началото."},"after":{"label":"Как го поправяш","text":"Провери дали телефонът е записал с променлива кадрова честота и дали проектът интерпретира файловете правилно; направи контролирано съвместимо копие при нужда. Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"На копие от интервюто постави маркери при първата, средната и последната ясна съгласна. Сравни устните на реален експорт.\n\nВземи доказателство, което би показал на друг монтажист: Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Местиш целия звук с две рамки и разваляш началото.\n\nГраницата: Пляскането фиксира начална точка, не гарантира липса на дрейф по цялата дължина."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Синхрон между отделен звук и картина“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Изрежи всяка неудобна реплика и скрий липсата на синхрон с музика."},{"id":"b","label":"Създай ясен общ маркер за записите и провери синхрона и в началото, и в края."},{"id":"c","label":"Местиш целия звук с две рамки и разваляш началото."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Създай ясен общ маркер за записите и провери синхрона и в началото, и в края. Пляскане в кадър оставя видим и звуков пик; scratch audio от камерата също помага при синхронизиране. Поддържай отделните файлове организирани по дубъл, устройство и време."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"40-минутен разговор от телефон и външен рекордер започва точно, но след 35 минути устните не съвпадат.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Местиш целия звук с две рамки и разваляш началото."},{"id":"b","label":"Изрежи всяка неудобна реплика и скрий липсата на синхрон с музика."},{"id":"c","label":"Провери дали телефонът е записал с променлива кадрова честота и дали проектът интерпретира файловете правилно; направи контролирано съвместимо копие при нужда."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Провери дали телефонът е записал с променлива кадрова честота и дали проектът интерпретира файловете правилно; направи контролирано съвместимо копие при нужда. Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Пляскането фиксира начална точка, не гарантира липса на дрейф по цялата дължина."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Изрежи всяка неудобна реплика и скрий липсата на синхрон с музика."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Пляскането фиксира начална точка, не гарантира липса на дрейф по цялата дължина."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Създай ясен общ маркер за записите и провери синхрона и в началото, и в края.","Провери дали телефонът е записал с променлива кадрова честота и дали проектът интерпретира файловете правилно; направи контролирано съвместимо копие при нужда.","Не пропускай контрола: Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати."],"nextStep":"На копие от интервюто постави маркери при първата, средната и последната ясна съгласна. Сравни устните на реален експорт."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Пляскането фиксира начална точка, не гарантира липса на дрейф по цялата дължина.","items":[{"id":"s3","text":"Синхронизирай началото по маркера или камерата."},{"id":"s1","text":"Пусни външен рекордер и камера, после направи видим маркер."},{"id":"s4","text":"Провери говор в началото и края на дългия клип."},{"id":"s2","text":"Кръсти и архивирай файловете по дубъл."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Пусни външен рекордер и камера, после направи видим маркер. → Кръсти и архивирай файловете по дубъл. → Синхронизирай началото по маркера или камерата. → Провери говор в началото и края на дългия клип."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Оказва се, че камерата няма използваем scratch audio.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Местиш целия звук с две рамки и разваляш началото."},{"id":"b","label":"Изрежи всяка неудобна реплика и скрий липсата на синхрон с музика."},{"id":"c","label":"Използвай видимия маркер или времеви бележки и провери няколко говорни момента; не разчитай на автоматичен waveform match."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Използвай видимия маркер или времеви бележки и провери няколко говорни момента; не разчитай на автоматичен waveform match. Пляскането фиксира начална точка, не гарантира липса на дрейф по цялата дължина."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Подреди файловете преди да режеш. Ако ги преименуваш след монтажа без връзка към оригинала, създаваш нов проблем.\n\nРаботна карта:\n1. Пусни външен рекордер и камера, после направи видим маркер.\n2. Кръсти и архивирай файловете по дубъл.\n3. Синхронизирай началото по маркера или камерата.\n4. Провери говор в началото и края на дългия клип.\n\nКритерий за предаване: Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати."},"points":1,"required":false}]},{"module_id":"s02-m05","lesson_id":"pv05-07","title":"Музика с проверени права за точния проект","subtitle":"Звук — запис, чистене и права","objective":"Ще провериш лиценз, платформи и условия преди да сложиш музика под клиентско видео.","hook":"„Без copyright“ в заглавието на чужд клип не е договор за рекламата на клиента.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще провериш лиценз, платформи и условия преди да сложиш музика под клиентско видео. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"„Без copyright“ в заглавието на чужд клип не е договор за рекламата на клиента."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Свободно за слушане, безплатно за изтегляне и разрешено за търговска употреба са различни неща.\n\nЗапиши кой държи правата, кой лиценз е купен или предоставен, за коя платформа, срок, територия и употреба важи. Пази фактура или текст на условията към конкретната версия на видеото."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Музика от библиотеката на една платформа може да има правила само за тази платформа; прехвърлянето на клипа във Facebook или реклама може да изисква отделно разрешение. При Creative Commons провери точния вариант и изискваното посочване на авторство; договорът на платена библиотека също може да изключва реклами или препродажба. Когато правата са неясни, използвай проследим лиценз или собствена музика, не се осланяй на тестово публикуване.\n\nГраница на решението: Условията на платформите и библиотеките се променят. Проверявай действащите условия при всеки нов канал или употреба."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Опиши къде и как клиентът ще използва видеото.\n2. Провери конкретния лиценз и страната, която го дава.\n3. Запази условията и документа към проекта.\n4. Прегледай финалната музика и употреба преди предаване.\n\nСтоп-сигнал: Казваш, че щом YouTube не е свалил видеото, музиката е свободна за всички канали.\nВърни се към пробата: В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Видео за сладкарница тръгва в YouTube и след седмица клиентът иска платена реклама в Instagram със същия файл.\n\nРешение: Провери дали лицензът покрива платена реклама и другата платформа; ако не, смени музиката или придобий нужните права.\n\nДоказателство, че работи: В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Казваш, че щом YouTube не е свалил видеото, музиката е свободна за всички канали."},"after":{"label":"Как го поправяш","text":"Провери дали лицензът покрива платена реклама и другата платформа; ако не, смени музиката или придобий нужните права. В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Подготви таблица само за себе си: композиция, източник, дата, лиценз, клиент, платформи, платена употреба и доказателство. Не изпращай файл с неясен статус.\n\nВземи доказателство, което би показал на друг монтажист: В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Казваш, че щом YouTube не е свалил видеото, музиката е свободна за всички канали.\n\nГраницата: Условията на платформите и библиотеките се променят. Проверявай действащите условия при всеки нов канал или употреба."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Музика с проверени права за точния проект“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Свободно за слушане, безплатно за изтегляне и разрешено за търговска употреба са различни неща."},{"id":"b","label":"Казваш, че щом YouTube не е свалил видеото, музиката е свободна за всички канали."},{"id":"c","label":"Напиши „music by ...“ в описанието и смятай, че така автоматично получаваш лиценз."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Свободно за слушане, безплатно за изтегляне и разрешено за търговска употреба са различни неща. Запиши кой държи правата, кой лиценз е купен или предоставен, за коя платформа, срок, територия и употреба важи. Пази фактура или текст на условията към конкретната версия на видеото."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Видео за сладкарница тръгва в YouTube и след седмица клиентът иска платена реклама в Instagram със същия файл.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Напиши „music by ...“ в описанието и смятай, че така автоматично получаваш лиценз."},{"id":"b","label":"Провери дали лицензът покрива платена реклама и другата платформа; ако не, смени музиката или придобий нужните права."},{"id":"c","label":"Казваш, че щом YouTube не е свалил видеото, музиката е свободна за всички канали."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Провери дали лицензът покрива платена реклама и другата платформа; ако не, смени музиката или придобий нужните права. В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Напиши „music by ...“ в описанието и смятай, че така автоматично получаваш лиценз."},{"id":"c","label":"Условията на платформите и библиотеките се променят. Проверявай действащите условия при всеки нов канал или употреба."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Условията на платформите и библиотеките се променят. Проверявай действащите условия при всеки нов канал или употреба."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Свободно за слушане, безплатно за изтегляне и разрешено за търговска употреба са различни неща.","Провери дали лицензът покрива платена реклама и другата платформа; ако не, смени музиката или придобий нужните права.","Не пропускай контрола: В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали."],"nextStep":"Подготви таблица само за себе си: композиция, източник, дата, лиценз, клиент, платформи, платена употреба и доказателство. Не изпращай файл с неясен статус."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Условията на платформите и библиотеките се променят. Проверявай действащите условия при всеки нов канал или употреба.","items":[{"id":"s3","text":"Запази условията и документа към проекта."},{"id":"s1","text":"Опиши къде и как клиентът ще използва видеото."},{"id":"s4","text":"Прегледай финалната музика и употреба преди предаване."},{"id":"s2","text":"Провери конкретния лиценз и страната, която го дава."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Опиши къде и как клиентът ще използва видеото. → Провери конкретния лиценз и страната, която го дава. → Запази условията и документа към проекта. → Прегледай финалната музика и употреба преди предаване."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът иска да прожектира видеото на събитие, извън първоначално посочените канали.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Напиши „music by ...“ в описанието и смятай, че така автоматично получаваш лиценз."},{"id":"b","label":"Провери договора за тази употреба преди прожекция; при липса на покритие осигури друг лицензиран вариант."},{"id":"c","label":"Казваш, че щом YouTube не е свалил видеото, музиката е свободна за всички канали."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Провери договора за тази употреба преди прожекция; при липса на покритие осигури друг лицензиран вариант. Условията на платформите и библиотеките се променят. Проверявай действащите условия при всеки нов канал или употреба."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"YouTube Audio Library има собствени условия и някои тракове изискват атрибуция; Creator Music има ограничения на приложимостта. Провери официалните условия: https://support.google.com/youtube/answer/3376882\n\nРаботна карта:\n1. Опиши къде и как клиентът ще използва видеото.\n2. Провери конкретния лиценз и страната, която го дава.\n3. Запази условията и документа към проекта.\n4. Прегледай финалната музика и употреба преди предаване.\n\nКритерий за предаване: В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали."},"points":1,"required":false}]},{"module_id":"s02-m05","lesson_id":"pv05-08","title":"Финален проект: минута, която се разбира без субтитри","subtitle":"Звук — запис, чистене и права","objective":"Ще запишеш и предадеш 60 секунди реч със стабилен звук, проверен синхрон и проследима музика.","hook":"Красивият финал не спасява видео, в което едно ключово изречение е неразбираемо.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще запишеш и предадеш 60 секунди реч със стабилен звук, проверен синхрон и проследима музика. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Красивият финал не спасява видео, в което едно ключово изречение е неразбираемо."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Крайният тест е зрителят да разбере думите при нормално слушане; оценявай оригинала, монтажа и експорта отделно.\n\nЗапиши разговор с реални шумове от мястото, близък микрофон и проверен входен запас. Избери най-разбираемите дубъли, запази естествени паузи и добави музика само ако не конкурира речта и имаш подходящи права."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Провери началото, средата и края на файла на слушалки и на обикновен телефон при нормална сила. Не приемай числова loudness цел като универсално правило за всички платформи: виж изискването за конкретната доставка и провери, че няма клипинг. Ако субтитрите са нужни за достъпност, те допълват гласа, а не заместват липсващи думи в звука.\n\nГраница на решението: Шумоподтискането не може да възстанови информация, напълно покрита от удар или клипинг."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Запиши целта, канала и правата за музика.\n2. Направи аудио проба и 60-секунден запис със запас.\n3. Монтирай за разбираемост и провери синхрон.\n4. Изнеси и прослушай финала на телефон и слушалки.\n\nСтоп-сигнал: Оставяш дефекта, защото надписът на екрана казва същото.\nВърни се към пробата: Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Минутно интервю за местен бизнес има правилно лице и две камери, но на 38-ата секунда врата покрива името на услугата.\n\nРешение: Избери чист дубъл, презапиши ключовото изречение при същата среда или използвай честен монтаж, който не подменя смисъла.\n\nДоказателство, че работи: Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Оставяш дефекта, защото надписът на екрана казва същото."},"after":{"label":"Как го поправяш","text":"Избери чист дубъл, презапиши ключовото изречение при същата среда или използвай честен монтаж, който не подменя смисъла. Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Пусни финала на човек, който не познава темата, без да му показваш кадъра. Нека повтори ключовото послание; ако не може, поправи проблема в аудиото.\n\nВземи доказателство, което би показал на друг монтажист: Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Оставяш дефекта, защото надписът на екрана казва същото.\n\nГраницата: Шумоподтискането не може да възстанови информация, напълно покрита от удар или клипинг."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Финален проект: минута, която се разбира без субтитри“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Оставяш дефекта, защото надписът на екрана казва същото."},{"id":"b","label":"Нормализирай всичко до максимума и приеми, че по-силно значи по-ясно."},{"id":"c","label":"Крайният тест е зрителят да разбере думите при нормално слушане; оценявай оригинала, монтажа и експорта отделно."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Крайният тест е зрителят да разбере думите при нормално слушане; оценявай оригинала, монтажа и експорта отделно. Запиши разговор с реални шумове от мястото, близък микрофон и проверен входен запас. Избери най-разбираемите дубъли, запази естествени паузи и добави музика само ако не конкурира речта и имаш подходящи права."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Минутно интервю за местен бизнес има правилно лице и две камери, но на 38-ата секунда врата покрива името на услугата.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Избери чист дубъл, презапиши ключовото изречение при същата среда или използвай честен монтаж, който не подменя смисъла."},{"id":"b","label":"Оставяш дефекта, защото надписът на екрана казва същото."},{"id":"c","label":"Нормализирай всичко до максимума и приеми, че по-силно значи по-ясно."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Избери чист дубъл, презапиши ключовото изречение при същата среда или използвай честен монтаж, който не подменя смисъла. Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Нормализирай всичко до максимума и приеми, че по-силно значи по-ясно."},{"id":"b","label":"Шумоподтискането не може да възстанови информация, напълно покрита от удар или клипинг."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Шумоподтискането не може да възстанови информация, напълно покрита от удар или клипинг."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Крайният тест е зрителят да разбере думите при нормално слушане; оценявай оригинала, монтажа и експорта отделно.","Избери чист дубъл, презапиши ключовото изречение при същата среда или използвай честен монтаж, който не подменя смисъла.","Не пропускай контрола: Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз."],"nextStep":"Пусни финала на човек, който не познава темата, без да му показваш кадъра. Нека повтори ключовото послание; ако не може, поправи проблема в аудиото."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Шумоподтискането не може да възстанови информация, напълно покрита от удар или клипинг.","items":[{"id":"s3","text":"Монтирай за разбираемост и провери синхрон."},{"id":"s1","text":"Запиши целта, канала и правата за музика."},{"id":"s4","text":"Изнеси и прослушай финала на телефон и слушалки."},{"id":"s2","text":"Направи аудио проба и 60-секунден запис със запас."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Запиши целта, канала и правата за музика. → Направи аудио проба и 60-секунден запис със запас. → Монтирай за разбираемост и провери синхрон. → Изнеси и прослушай финала на телефон и слушалки."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът премахва музиката за вторична версия на видео реклама.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Изнеси вариант без музика и провери паузите, речта и фоновия шум отначало; не приемай, че смесването остава същото."},{"id":"b","label":"Оставяш дефекта, защото надписът на екрана казва същото."},{"id":"c","label":"Нормализирай всичко до максимума и приеми, че по-силно значи по-ясно."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Изнеси вариант без музика и провери паузите, речта и фоновия шум отначало; не приемай, че смесването остава същото. Шумоподтискането не може да възстанови информация, напълно покрита от удар или клипинг."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Пази отделни оригинални файлове, проект и финален експорт. Така след месец можеш да промениш музика или реплика без да разрушиш звука.\n\nРаботна карта:\n1. Запиши целта, канала и правата за музика.\n2. Направи аудио проба и 60-секунден запис със запас.\n3. Монтирай за разбираемост и провери синхрон.\n4. Изнеси и прослушай финала на телефон и слушалки.\n\nКритерий за предаване: Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-01","title":"Предпродукция: какво трябва да е решено преди терен","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще направиш кратък план с цел, хора, място, права и проверим резултат.","hook":"Снимачният ден се проваля не заради камерата, а защото никой не знае кой отключва обекта.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще направиш кратък план с цел, хора, място, права и проверим резултат. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Снимачният ден се проваля не заради камерата, а защото никой не знае кой отключва обекта."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Напиши минимален работен документ: за кого е видеото, къде ще се ползва, кой взема решения и какъв резултат трябва да се види.\n\nЕдна страница стига, ако съдържа контакти, адрес, времеви прозорец, разрешения, резервно място и списък с нужни кадри и звуци. Раздели „потвърдено“ от „чака отговор“."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Не започвай с изреждане на техника. Изясни кои твърдения трябва да бъдат проверени от клиента, дали участниците знаят къде ще се публикува видеото и кой разрешава достъп. Запиши какво е забранено за показване: лични данни, лица, продукти, търговска тайна. Когато има неизвестно, сложи собственик и срок за решение преди началото на снимките.\n\nГраница на решението: Една страница не замества договори и изискванията на организацията; тя показва какво още трябва да бъде потвърдено."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Определи цел, употреба и критерий за приемане.\n2. Потвърди участници, достъп, условия и права.\n3. Опиши задължителните кадри, звук и резервен вариант.\n4. Позвъни предния ден и затвори всички критични неизвестни.\n\nСтоп-сигнал: Пристигаш с готова shot list и започваш да снимаш без разрешения и без работещ процес.\nВърни се към пробата: В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Местна работилница иска кратко видео за процеса. Майсторът идва след 10 ч., машината работи само в 9 ч., а никой не е изяснил дали може да се снима клиентски продукт.\n\nРешение: Потвърди отделно достъп, времето на машината и разрешението за конкретния продукт; промени графика преди тръгване.\n\nДоказателство, че работи: В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Пристигаш с готова shot list и започваш да снимаш без разрешения и без работещ процес."},"after":{"label":"Как го поправяш","text":"Потвърди отделно достъп, времето на машината и разрешението за конкретния продукт; промени графика преди тръгване. В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Създай истински план за близък обект с три колони: потвърдено, неизвестно, кой да реши. Не изтривай неизвестните с предположение.\n\nВземи доказателство, което би показал на друг монтажист: В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Пристигаш с готова shot list и започваш да снимаш без разрешения и без работещ процес.\n\nГраницата: Една страница не замества договори и изискванията на организацията; тя показва какво още трябва да бъде потвърдено."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Предпродукция: какво трябва да е решено преди терен“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Остави правата и достъпа за след снимките, за да не забавяш екипа."},{"id":"b","label":"Напиши минимален работен документ: за кого е видеото, къде ще се ползва, кой взема решения и какъв резултат трябва да се види."},{"id":"c","label":"Пристигаш с готова shot list и започваш да снимаш без разрешения и без работещ процес."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Напиши минимален работен документ: за кого е видеото, къде ще се ползва, кой взема решения и какъв резултат трябва да се види. Една страница стига, ако съдържа контакти, адрес, времеви прозорец, разрешения, резервно място и списък с нужни кадри и звуци. Раздели „потвърдено“ от „чака отговор“."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Местна работилница иска кратко видео за процеса. Майсторът идва след 10 ч., машината работи само в 9 ч., а никой не е изяснил дали може да се снима клиентски продукт.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Пристигаш с готова shot list и започваш да снимаш без разрешения и без работещ процес."},{"id":"b","label":"Остави правата и достъпа за след снимките, за да не забавяш екипа."},{"id":"c","label":"Потвърди отделно достъп, времето на машината и разрешението за конкретния продукт; промени графика преди тръгване."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Потвърди отделно достъп, времето на машината и разрешението за конкретния продукт; промени графика преди тръгване. В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Една страница не замества договори и изискванията на организацията; тя показва какво още трябва да бъде потвърдено."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Остави правата и достъпа за след снимките, за да не забавяш екипа."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Една страница не замества договори и изискванията на организацията; тя показва какво още трябва да бъде потвърдено."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Напиши минимален работен документ: за кого е видеото, къде ще се ползва, кой взема решения и какъв резултат трябва да се види.","Потвърди отделно достъп, времето на машината и разрешението за конкретния продукт; промени графика преди тръгване.","Не пропускай контрола: В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат."],"nextStep":"Създай истински план за близък обект с три колони: потвърдено, неизвестно, кой да реши. Не изтривай неизвестните с предположение."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Една страница не замества договори и изискванията на организацията; тя показва какво още трябва да бъде потвърдено.","items":[{"id":"s3","text":"Опиши задължителните кадри, звук и резервен вариант."},{"id":"s1","text":"Определи цел, употреба и критерий за приемане."},{"id":"s4","text":"Позвъни предния ден и затвори всички критични неизвестни."},{"id":"s2","text":"Потвърди участници, достъп, условия и права."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Определи цел, употреба и критерий за приемане. → Потвърди участници, достъп, условия и права. → Опиши задължителните кадри, звук и резервен вариант. → Позвъни предния ден и затвори всички критични неизвестни."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Вечерта преди снимките човекът за контакт не потвърждава достъпа.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Пристигаш с готова shot list и започваш да снимаш без разрешения и без работещ процес."},{"id":"b","label":"Остави правата и достъпа за след снимките, за да не забавяш екипа."},{"id":"c","label":"Използвай резервното място или промени часа след писмено потвърждение; не пристигай с надежда, че някой ще отключи."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Използвай резервното място или промени часа след писмено потвърждение; не пристигай с надежда, че някой ще отключи. Една страница не замества договори и изискванията на организацията; тя показва какво още трябва да бъде потвърдено."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Добрата подготовка е скучна само когато е свършена. На терен тя купува време за истинските реакции.\n\nРаботна карта:\n1. Определи цел, употреба и критерий за приемане.\n2. Потвърди участници, достъп, условия и права.\n3. Опиши задължителните кадри, звук и резервен вариант.\n4. Позвъни предния ден и затвори всички критични неизвестни.\n\nКритерий за предаване: В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-02","title":"Сценарий или свободен разговор?","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще избереш начин на говорене според точността на фактите и характера на човека.","hook":"Човекът чете без да диша; ако го оставиш да импровизира, забравя най-важното условие.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще избереш начин на говорене според точността на фактите и характера на човека. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Човекът чете без да диша; ако го оставиш да импровизира, забравя най-важното условие."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Раздели задължителните факти от начина, по който говорителят ги произнася.\n\nНапиши опорни точки за естествен разговор и отделен списък с точни числа, условия, имена и юридически одобрени фрази. Телепромптерът помага за точен текст, но изисква репетиция и темпо."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Провери как говорителят разказва темата на приятел без камера. Ако историята е силна, вземи разговорния вариант и допълни необходимите факти с кадри или графика след проверка. Ако обещанието е строго формулирано, заснеми точното изречение отделно. Не принуждавай човек да казва твърдение, което не е потвърдено от отговорния в организацията.\n\nГраница на решението: Импровизация не дава право да измисляш факти, а точният сценарий не гарантира естествена игра."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Отбележи точните факти и отговорния за тях.\n2. Запиши свободен пробен отговор.\n3. Избери опорни точки или точен текст според грешките.\n4. Сними и провери съдържанието преди финалния монтаж.\n\nСтоп-сигнал: Оставяш силната реплика, защото звучи убедително, без да провериш обещанието.\nВърни се към пробата: Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Собственичка на салон говори увлекателно за услугата, но казва „винаги безболезнено“, което клиентът не може да гарантира.\n\nРешение: Запази естествения тон, но попитай какво може да се твърди точно и презаснеми частта с провереното условие.\n\nДоказателство, че работи: Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Оставяш силната реплика, защото звучи убедително, без да провериш обещанието."},"after":{"label":"Как го поправяш","text":"Запази естествения тон, но попитай какво може да се твърди точно и презаснеми частта с провереното условие. Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Заснеми два 15-секундни варианта на една мисъл: дословен и по опорни точки. Провери едновременно точност и разбираемост.\n\nВземи доказателство, което би показал на друг монтажист: Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Оставяш силната реплика, защото звучи убедително, без да провериш обещанието.\n\nГраницата: Импровизация не дава право да измисляш факти, а точният сценарий не гарантира естествена игра."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Сценарий или свободен разговор?“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Раздели задължителните факти от начина, по който говорителят ги произнася."},{"id":"b","label":"Оставяш силната реплика, защото звучи убедително, без да провериш обещанието."},{"id":"c","label":"Помоли говорителя да научи още две страници наизуст и ускорете четенето."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Раздели задължителните факти от начина, по който говорителят ги произнася. Напиши опорни точки за естествен разговор и отделен списък с точни числа, условия, имена и юридически одобрени фрази. Телепромптерът помага за точен текст, но изисква репетиция и темпо."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Собственичка на салон говори увлекателно за услугата, но казва „винаги безболезнено“, което клиентът не може да гарантира.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Помоли говорителя да научи още две страници наизуст и ускорете четенето."},{"id":"b","label":"Запази естествения тон, но попитай какво може да се твърди точно и презаснеми частта с провереното условие."},{"id":"c","label":"Оставяш силната реплика, защото звучи убедително, без да провериш обещанието."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Запази естествения тон, но попитай какво може да се твърди точно и презаснеми частта с провереното условие. Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Помоли говорителя да научи още две страници наизуст и ускорете четенето."},{"id":"c","label":"Импровизация не дава право да измисляш факти, а точният сценарий не гарантира естествена игра."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Импровизация не дава право да измисляш факти, а точният сценарий не гарантира естествена игра."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Раздели задължителните факти от начина, по който говорителят ги произнася.","Запази естествения тон, но попитай какво може да се твърди точно и презаснеми частта с провереното условие.","Не пропускай контрола: Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания."],"nextStep":"Заснеми два 15-секундни варианта на една мисъл: дословен и по опорни точки. Провери едновременно точност и разбираемост."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Импровизация не дава право да измисляш факти, а точният сценарий не гарантира естествена игра.","items":[{"id":"s3","text":"Избери опорни точки или точен текст според грешките."},{"id":"s1","text":"Отбележи точните факти и отговорния за тях."},{"id":"s4","text":"Сними и провери съдържанието преди финалния монтаж."},{"id":"s2","text":"Запиши свободен пробен отговор."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Отбележи точните факти и отговорния за тях. → Запиши свободен пробен отговор. → Избери опорни точки или точен текст според грешките. → Сними и провери съдържанието преди финалния монтаж."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът добавя законово изисквана фраза накрая.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Помоли говорителя да научи още две страници наизуст и ускорете четенето."},{"id":"b","label":"Запиши я отделно точно и с разбираемо темпо, после провери с отговорния човек как стои в целия монтаж."},{"id":"c","label":"Оставяш силната реплика, защото звучи убедително, без да провериш обещанието."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Запиши я отделно точно и с разбираемо темпо, после провери с отговорния човек как стои в целия монтаж. Импровизация не дава право да измисляш факти, а точният сценарий не гарантира естествена игра."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Говорителят не трябва да носи цялото съдържание на гръб: видими действия и проверена графика могат да обяснят част от него.\n\nРаботна карта:\n1. Отбележи точните факти и отговорния за тях.\n2. Запиши свободен пробен отговор.\n3. Избери опорни точки или точен текст според грешките.\n4. Сними и провери съдържанието преди финалния монтаж.\n\nКритерий за предаване: Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-03","title":"Оглед на мястото: светлина, звук, фон, достъп","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще огледаш локация с кратка проба и ще предотвратиш скрити пречки.","hook":"Снимка на помещението изглежда чудесно, докато не чуеш компресора до стената.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще огледаш локация с кратка проба и ще предотвратиш скрити пречки. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Снимка на помещението изглежда чудесно, докато не чуеш компресора до стената."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Огледът е снимана и прослушана проверка при часа на бъдещата работа.\n\nТествай къде ще застане човекът, откъде идва светлината, как звучи гласът, какво се вижда на заден план и къде минават хората. Забележи контакти, ограничения за статив и достъп до тоалетна или почивка."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Променяй един фактор в пробите: позиция, фон, микрофон. Кратко видео с реч разкрива повече от галерия със снимки. Провери дали фирмени знаци, документи на стена, клиентски адреси или чужди лица ще попаднат в кадър. Планирай кога мястото се освобождава и как ще оставиш оборудването без да блокираш работа.\n\nГраница на решението: Един оглед не предвижда всяка промяна: планът включва резервна позиция и контакт на място."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Уговори оглед в сравним час и получи достъп.\n2. Запиши кадър с реч на планираното място.\n3. Провери фон, шум, светлина и маршрут на кабелите.\n4. Потвърди с домакина какво може да се мести или показва.\n\nСтоп-сигнал: Избираш ъгъла само по снимката и оставяш проверката за след първия въпрос.\nВърни се към пробата: Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Кафене разрешава снимки сутрин. Красивият ъгъл от снимките е до хладилна витрина, която се включва внезапно.\n\nРешение: Направи говорна проба при работеща витрина, намери алтернативен ъгъл или уговори контролирана пауза.\n\nДоказателство, че работи: Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Избираш ъгъла само по снимката и оставяш проверката за след първия въпрос."},"after":{"label":"Как го поправяш","text":"Направи говорна проба при работеща витрина, намери алтернативен ъгъл или уговори контролирана пауза. Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Запиши три проби по 10 секунди на възможни места и сравни тихия глас, лицето и фона. Остави отбелязана резервна позиция.\n\nВземи доказателство, което би показал на друг монтажист: Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Избираш ъгъла само по снимката и оставяш проверката за след първия въпрос.\n\nГраницата: Един оглед не предвижда всяка промяна: планът включва резервна позиция и контакт на място."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Оглед на мястото: светлина, звук, фон, достъп“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Избираш ъгъла само по снимката и оставяш проверката за след първия въпрос."},{"id":"b","label":"Използвай повече шумоподтискане след монтажа вместо проба."},{"id":"c","label":"Огледът е снимана и прослушана проверка при часа на бъдещата работа."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Огледът е снимана и прослушана проверка при часа на бъдещата работа. Тествай къде ще застане човекът, откъде идва светлината, как звучи гласът, какво се вижда на заден план и къде минават хората. Забележи контакти, ограничения за статив и достъп до тоалетна или почивка."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Кафене разрешава снимки сутрин. Красивият ъгъл от снимките е до хладилна витрина, която се включва внезапно.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Направи говорна проба при работеща витрина, намери алтернативен ъгъл или уговори контролирана пауза."},{"id":"b","label":"Избираш ъгъла само по снимката и оставяш проверката за след първия въпрос."},{"id":"c","label":"Използвай повече шумоподтискане след монтажа вместо проба."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Направи говорна проба при работеща витрина, намери алтернативен ъгъл или уговори контролирана пауза. Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Използвай повече шумоподтискане след монтажа вместо проба."},{"id":"b","label":"Един оглед не предвижда всяка промяна: планът включва резервна позиция и контакт на място."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Един оглед не предвижда всяка промяна: планът включва резервна позиция и контакт на място."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Огледът е снимана и прослушана проверка при часа на бъдещата работа.","Направи говорна проба при работеща витрина, намери алтернативен ъгъл или уговори контролирана пауза.","Не пропускай контрола: Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени."],"nextStep":"Запиши три проби по 10 секунди на възможни места и сравни тихия глас, лицето и фона. Остави отбелязана резервна позиция."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Един оглед не предвижда всяка промяна: планът включва резервна позиция и контакт на място.","items":[{"id":"s3","text":"Провери фон, шум, светлина и маршрут на кабелите."},{"id":"s1","text":"Уговори оглед в сравним час и получи достъп."},{"id":"s4","text":"Потвърди с домакина какво може да се мести или показва."},{"id":"s2","text":"Запиши кадър с реч на планираното място."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Уговори оглед в сравним час и получи достъп. → Запиши кадър с реч на планираното място. → Провери фон, шум, светлина и маршрут на кабелите. → Потвърди с домакина какво може да се мести или показва."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: В деня на снимките предвидената маса е заета от клиент.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Премини към потвърдения резервен ъгъл, направи нова аудио проба и не мести клиент без съгласие."},{"id":"b","label":"Избираш ъгъла само по снимката и оставяш проверката за след първия въпрос."},{"id":"c","label":"Използвай повече шумоподтискане след монтажа вместо проба."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Премини към потвърдения резервен ъгъл, направи нова аудио проба и не мести клиент без съгласие. Един оглед не предвижда всяка промяна: планът включва резервна позиция и контакт на място."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Най-скъпият избор на локация е този, който не е бил слушан.\n\nРаботна карта:\n1. Уговори оглед в сравним час и получи достъп.\n2. Запиши кадър с реч на планираното място.\n3. Провери фон, шум, светлина и маршрут на кабелите.\n4. Потвърди с домакина какво може да се мести или показва.\n\nКритерий за предаване: Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-04","title":"Снимачната чанта: комплект срещу отказ","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще подготвиш минимален комплект, който има захранване, запис и проверен резерв.","hook":"Резервният обектив е в чантата, но резервна карта и батерия липсват.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще подготвиш минимален комплект, който има захранване, запис и проверен резерв. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Резервният обектив е в чантата, но резервна карта и батерия липсват."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Подреждай багажа около видовете провал: няма захранване, няма запис, няма звук, няма безопасен монтаж.\n\nСписъкът за конкретния проект включва заредени батерии, празни проверени карти, микрофон и слушалки, надежден монтаж, кабели и маркировки. Провери съвместимостта и състоянието, а не броя предмети."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Направи пробен път от камерата до компютъра: запис, възпроизвеждане, копие. Маркирай коя карта е използвана и не форматирай заснет материал, преди да имаш проверени копия. Постави дребните резервни части там, където можеш да ги намериш по време на интервюто; списъкът работи само ако се използва преди излизане и при прибиране.\n\nГраница на решението: Двойният слот не замества проверено копие извън устройството, а резервните части трябва да са съвместими."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Преброй критичните режими на отказ за този проект.\n2. Провери батерии, медии, микрофон и закрепване с кратък запис.\n3. Подреди основно и резервно средство за всяка критична функция.\n4. Отметни комплекта преди тръгване и след края на деня.\n\nСтоп-сигнал: Изтриваш по-старите добри кадри, защото имаш втори обектив, но не и проверено копие.\nВърни се към пробата: Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"На снимки извън града без магазин наблизо картата на камерата се запълва след първия час.\n\nРешение: Спри, осигури нова проверена медия или копирай и провери на поне две места по плана; не изтривай единствения оригинал.\n\nДоказателство, че работи: Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Изтриваш по-старите добри кадри, защото имаш втори обектив, но не и проверено копие."},"after":{"label":"Как го поправяш","text":"Спри, осигури нова проверена медия или копирай и провери на поне две места по плана; не изтривай единствения оригинал. Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Опаковай чантата за реално интервю, после симулирай една липса: батерия, кабел или карта. Измери дали можеш да продължиш без риск за материала.\n\nВземи доказателство, което би показал на друг монтажист: Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Изтриваш по-старите добри кадри, защото имаш втори обектив, но не и проверено копие.\n\nГраницата: Двойният слот не замества проверено копие извън устройството, а резервните части трябва да са съвместими."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Снимачната чанта: комплект срещу отказ“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Купи още обективи вместо да провериш записващата верига."},{"id":"b","label":"Подреждай багажа около видовете провал: няма захранване, няма запис, няма звук, няма безопасен монтаж."},{"id":"c","label":"Изтриваш по-старите добри кадри, защото имаш втори обектив, но не и проверено копие."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Подреждай багажа около видовете провал: няма захранване, няма запис, няма звук, няма безопасен монтаж. Списъкът за конкретния проект включва заредени батерии, празни проверени карти, микрофон и слушалки, надежден монтаж, кабели и маркировки. Провери съвместимостта и състоянието, а не броя предмети."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"На снимки извън града без магазин наблизо картата на камерата се запълва след първия час.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Изтриваш по-старите добри кадри, защото имаш втори обектив, но не и проверено копие."},{"id":"b","label":"Купи още обективи вместо да провериш записващата верига."},{"id":"c","label":"Спри, осигури нова проверена медия или копирай и провери на поне две места по плана; не изтривай единствения оригинал."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Спри, осигури нова проверена медия или копирай и провери на поне две места по плана; не изтривай единствения оригинал. Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Двойният слот не замества проверено копие извън устройството, а резервните части трябва да са съвместими."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Купи още обективи вместо да провериш записващата верига."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Двойният слот не замества проверено копие извън устройството, а резервните части трябва да са съвместими."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Подреждай багажа около видовете провал: няма захранване, няма запис, няма звук, няма безопасен монтаж.","Спри, осигури нова проверена медия или копирай и провери на поне две места по плана; не изтривай единствения оригинал.","Не пропускай контрола: Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал."],"nextStep":"Опаковай чантата за реално интервю, после симулирай една липса: батерия, кабел или карта. Измери дали можеш да продължиш без риск за материала."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Двойният слот не замества проверено копие извън устройството, а резервните части трябва да са съвместими.","items":[{"id":"s3","text":"Подреди основно и резервно средство за всяка критична функция."},{"id":"s1","text":"Преброй критичните режими на отказ за този проект."},{"id":"s4","text":"Отметни комплекта преди тръгване и след края на деня."},{"id":"s2","text":"Провери батерии, медии, микрофон и закрепване с кратък запис."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Преброй критичните режими на отказ за този проект. → Провери батерии, медии, микрофон и закрепване с кратък запис. → Подреди основно и резервно средство за всяка критична функция. → Отметни комплекта преди тръгване и след края на деня."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Излиза, че резервният рекордер използва друг тип захранване.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Изтриваш по-старите добри кадри, защото имаш втори обектив, но не и проверено копие."},{"id":"b","label":"Купи още обективи вместо да провериш записващата верига."},{"id":"c","label":"Провери реалните батерии и кабели за него преди тръгване; ако липсват, планирай друг проверен резерв."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Провери реалните батерии и кабели за него преди тръгване; ако липсват, планирай друг проверен резерв. Двойният слот не замества проверено копие извън устройството, а резервните части трябва да са съвместими."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Надеждната чанта е карта на решенията при провал, не списък на притежаваното оборудване.\n\nРаботна карта:\n1. Преброй критичните режими на отказ за този проект.\n2. Провери батерии, медии, микрофон и закрепване с кратък запис.\n3. Подреди основно и резервно средство за всяка критична функция.\n4. Отметни комплекта преди тръгване и след края на деня.\n\nКритерий за предаване: Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-05","title":"Какво да не купуваш още","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще решиш дали нова техника решава измерен проблем или само прикрива слаб процес.","hook":"Новата камера пристига, но клиентът пак не разбира гласа в рекламата.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще решиш дали нова техника решава измерен проблем или само прикрива слаб процес. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Новата камера пристига, но клиентът пак не разбира гласа в рекламата."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Назови дефекта от предишен проект и покажи как покупката ще го намали при същите условия.\n\nАко проблемът е говор отдалеч, близък микрофон и тиха стая могат да помогнат повече от нова камера. Ако видеото губи кадри при презапис, по-добра организация на медията е по-належаща от светлина за фон."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Направи малка проба: снимай една сцена с настоящия комплект, промени само начина на работа и виж дали провалът изчезва. Наем или заем на техника за едно снимане може да покаже разликата преди покупка. Сметни и допълнителните разходи: батерии, носители, стойки, транспорт, време за обучение. Не купувай спецификация, която няма място в този работен процес.\n\nГраница на решението: Някои задачи наистина изискват нова техника; отказът от покупка не е правило, а решение след проба."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Опиши повторящ се дефект с конкретен файл.\n2. Пробвай поправка чрез позиция, светлина, звук или процес.\n3. Ако не стига, тествай наета/заемана техника при същите условия.\n4. Реши покупка според измеримата промяна и общия разход.\n\nСтоп-сигнал: Поръчва нова камера, без да е сравнил по-близък микрофон и друго място.\nВърни се към пробата: В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Фрийлансър снима интервюта в малки офиси. Купува по-скъп обектив, но отговорите още звучат кухо.\n\nРешение: Направи A/B звук на същото интервю с близък микрофон; инвестирай само в решението, което премахва реалния дефект.\n\nДоказателство, че работи: В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Поръчва нова камера, без да е сравнил по-близък микрофон и друго място."},"after":{"label":"Как го поправяш","text":"Направи A/B звук на същото интервю с близък микрофон; инвестирай само в решението, което премахва реалния дефект. В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Извади три най-лоши кадъра от минали работи и запиши конкретен корен на проблема за всеки. Вложи бюджета първо там, където причината е доказана.\n\nВземи доказателство, което би показал на друг монтажист: В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Поръчва нова камера, без да е сравнил по-близък микрофон и друго място.\n\nГраницата: Някои задачи наистина изискват нова техника; отказът от покупка не е правило, а решение след проба."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Какво да не купуваш още“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Назови дефекта от предишен проект и покажи как покупката ще го намали при същите условия."},{"id":"b","label":"Поръчва нова камера, без да е сравнил по-близък микрофон и друго място."},{"id":"c","label":"Избери техника по най-високата рекламирана резолюция."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Назови дефекта от предишен проект и покажи как покупката ще го намали при същите условия. Ако проблемът е говор отдалеч, близък микрофон и тиха стая могат да помогнат повече от нова камера. Ако видеото губи кадри при презапис, по-добра организация на медията е по-належаща от светлина за фон."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Фрийлансър снима интервюта в малки офиси. Купува по-скъп обектив, но отговорите още звучат кухо.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Избери техника по най-високата рекламирана резолюция."},{"id":"b","label":"Направи A/B звук на същото интервю с близък микрофон; инвестирай само в решението, което премахва реалния дефект."},{"id":"c","label":"Поръчва нова камера, без да е сравнил по-близък микрофон и друго място."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Направи A/B звук на същото интервю с близък микрофон; инвестирай само в решението, което премахва реалния дефект. В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Избери техника по най-високата рекламирана резолюция."},{"id":"c","label":"Някои задачи наистина изискват нова техника; отказът от покупка не е правило, а решение след проба."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Някои задачи наистина изискват нова техника; отказът от покупка не е правило, а решение след проба."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Назови дефекта от предишен проект и покажи как покупката ще го намали при същите условия.","Направи A/B звук на същото интервю с близък микрофон; инвестирай само в решението, което премахва реалния дефект.","Не пропускай контрола: В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината."],"nextStep":"Извади три най-лоши кадъра от минали работи и запиши конкретен корен на проблема за всеки. Вложи бюджета първо там, където причината е доказана."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Някои задачи наистина изискват нова техника; отказът от покупка не е правило, а решение след проба.","items":[{"id":"s3","text":"Ако не стига, тествай наета/заемана техника при същите условия."},{"id":"s1","text":"Опиши повторящ се дефект с конкретен файл."},{"id":"s4","text":"Реши покупка според измеримата промяна и общия разход."},{"id":"s2","text":"Пробвай поправка чрез позиция, светлина, звук или процес."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Опиши повторящ се дефект с конкретен файл. → Пробвай поправка чрез позиция, светлина, звук или процес. → Ако не стига, тествай наета/заемана техника при същите условия. → Реши покупка според измеримата промяна и общия разход."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Нов клиент иска заснемане при светлина, която настоящият комплект не може да поддържа.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Избери техника по най-високата рекламирана резолюция."},{"id":"b","label":"Тествай нает подходящ източник на място, сметни повторяемостта на задачата и едва тогава избери покупка."},{"id":"c","label":"Поръчва нова камера, без да е сравнил по-близък микрофон и друго място."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Тествай нает подходящ източник на място, сметни повторяемостта на задачата и едва тогава избери покупка. Някои задачи наистина изискват нова техника; отказът от покупка не е правило, а решение след проба."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Разходът за техника е оправдан, когато знаеш как ще провери клиентът разликата във финалния файл.\n\nРаботна карта:\n1. Опиши повторящ се дефект с конкретен файл.\n2. Пробвай поправка чрез позиция, светлина, звук или процес.\n3. Ако не стига, тествай наета/заемана техника при същите условия.\n4. Реши покупка според измеримата промяна и общия разход.\n\nКритерий за предаване: В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-06","title":"График на снимачния ден със запас","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще направиш график, който отчита смени, почивки, проби и риск от закъснение.","hook":"На хартия има 12 кадъра за час. На терен всеки пренос на лампа взема десет минути.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще направиш график, който отчита смени, почивки, проби и риск от закъснение. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"На хартия има 12 кадъра за час. На терен всеки пренос на лампа взема десет минути."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Групирай кадрите по място и подготовка, а не само по реда във финалното видео.\n\nОтдели време за пристигане, настройка и проба, действителните дубли, промени на осветление и звук, почивки, копиране и прибиране. Посочи кога ключов човек или локация не са налични."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Постави задължителните кадри преди допълнителните и определи момент за решение „свиваме обхвата“. При разминаване не съкращавай проверката на звук и безопасното прибиране; махни или комбинирай най-малко важен план. Изпрати часовете на участниците като реални прозорци, не като гаранция за минута по минута.\n\nГраница на решението: Буферът не е оправдание да обещаеш повече кадри, отколкото мястото и хората позволяват."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Запиши фиксираните часове на хора, място и светлина.\n2. Групирай кадри по еднаква установка.\n3. Добави проби, почивки, копиране и буфер.\n4. Определи кои кадри отпадат първи при закъснение.\n\nСтоп-сигнал: Следваш монтажния ред на сцените и изпускаш единственото време за печене.\nВърни се към пробата: Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"В сладкарница фурната е достъпна сутрин, собственичката — по обед, а клиентите влизат следобед. Графикът от сценария започва с интервю.\n\nРешение: Премести процеса при фурната в ранния прозорец, подготви звук за интервюто преди обед и остави буфер за клиенти.\n\nДоказателство, че работи: Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Следваш монтажния ред на сцените и изпускаш единственото време за печене."},"after":{"label":"Как го поправяш","text":"Премести процеса при фурната в ранния прозорец, подготви звук за интервюто преди обед и остави буфер за клиенти. Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Направи план по часове за реален бизнес. Постави един неочакван проблем от 20 минути и покажи кой незадължителен кадър отпада.\n\nВземи доказателство, което би показал на друг монтажист: Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Следваш монтажния ред на сцените и изпускаш единственото време за печене.\n\nГраницата: Буферът не е оправдание да обещаеш повече кадри, отколкото мястото и хората позволяват."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „График на снимачния ден със запас“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Следваш монтажния ред на сцените и изпускаш единственото време за печене."},{"id":"b","label":"Прехвърли всички забавени задачи в края и обещай, че ще се заснемат без нова смяна."},{"id":"c","label":"Групирай кадрите по място и подготовка, а не само по реда във финалното видео."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Групирай кадрите по място и подготовка, а не само по реда във финалното видео. Отдели време за пристигане, настройка и проба, действителните дубли, промени на осветление и звук, почивки, копиране и прибиране. Посочи кога ключов човек или локация не са налични."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"В сладкарница фурната е достъпна сутрин, собственичката — по обед, а клиентите влизат следобед. Графикът от сценария започва с интервю.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Премести процеса при фурната в ранния прозорец, подготви звук за интервюто преди обед и остави буфер за клиенти."},{"id":"b","label":"Следваш монтажния ред на сцените и изпускаш единственото време за печене."},{"id":"c","label":"Прехвърли всички забавени задачи в края и обещай, че ще се заснемат без нова смяна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Премести процеса при фурната в ранния прозорец, подготви звук за интервюто преди обед и остави буфер за клиенти. Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Прехвърли всички забавени задачи в края и обещай, че ще се заснемат без нова смяна."},{"id":"b","label":"Буферът не е оправдание да обещаеш повече кадри, отколкото мястото и хората позволяват."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Буферът не е оправдание да обещаеш повече кадри, отколкото мястото и хората позволяват."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Групирай кадрите по място и подготовка, а не само по реда във финалното видео.","Премести процеса при фурната в ранния прозорец, подготви звук за интервюто преди обед и остави буфер за клиенти.","Не пропускай контрола: Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране."],"nextStep":"Направи план по часове за реален бизнес. Постави един неочакван проблем от 20 минути и покажи кой незадължителен кадър отпада."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Буферът не е оправдание да обещаеш повече кадри, отколкото мястото и хората позволяват.","items":[{"id":"s3","text":"Добави проби, почивки, копиране и буфер."},{"id":"s1","text":"Запиши фиксираните часове на хора, място и светлина."},{"id":"s4","text":"Определи кои кадри отпадат първи при закъснение."},{"id":"s2","text":"Групирай кадри по еднаква установка."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Запиши фиксираните часове на хора, място и светлина. → Групирай кадри по еднаква установка. → Добави проби, почивки, копиране и буфер. → Определи кои кадри отпадат първи при закъснение."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Ключовият човек закъснява с половин час.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Използвай времето за предметни кадри и звук от мястото, после актуализирай графика с нов прозорец за човека."},{"id":"b","label":"Следваш монтажния ред на сцените и изпускаш единственото време за печене."},{"id":"c","label":"Прехвърли всички забавени задачи в края и обещай, че ще се заснемат без нова смяна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Използвай времето за предметни кадри и звук от мястото, после актуализирай графика с нов прозорец за човека. Буферът не е оправдание да обещаеш повече кадри, отколкото мястото и хората позволяват."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Графикът дава решения, когато реалността се намеси; без приоритети е само красива таблица.\n\nРаботна карта:\n1. Запиши фиксираните часове на хора, място и светлина.\n2. Групирай кадри по еднаква установка.\n3. Добави проби, почивки, копиране и буфер.\n4. Определи кои кадри отпадат първи при закъснение.\n\nКритерий за предаване: Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-07","title":"B-roll, който покрива конкретен монтаж","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще направиш списък с кадри, които обясняват действие и дават честни монтажни преходи.","hook":"Имаш десет красиви детайла на инструменти, но нито един кадър на самата работа.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще направиш списък с кадри, които обясняват действие и дават честни монтажни преходи. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Имаш десет красиви детайла на инструменти, но нито един кадър на самата работа."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"B-roll трябва да доказва казаното и да покрива нужните преходи, не да пълни време.\n\nЗа всяко твърдение запиши видимо действие: начало, изпълнение и резултат. Вземи широк, среден и близък план само когато те дават различна информация. Отбележи необходимия звук на действието."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Планирай посоката на движенията и предметите между плановете: от коя ръка се взема материалът, къде се поставя и кога процесът се променя. Не снимай чужди лица или чувствителни екрани само защото са удобен фон. След първия снимачен блок отвори материалите и виж кой конкретен срез още няма покритие; допълни го, докато човекът и обектът са налични.\n\nГраница на решението: B-roll не бива да инсценира доказателство за услуга, която не е извършена."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Разпиши ключовите твърдения или движения.\n2. За всяко запиши начало, действие, резултат и нужен звук.\n3. Сними различни информативни дистанции и посоки.\n4. Прегледай материала и попълни липсващите монтажни връзки.\n\nСтоп-сигнал: Покриваш репликата с произволен кадър на инструмент и внушаваш проверка, която не се вижда.\nВърни се към пробата: Зрителят може да посочи на кадър действието, за което говорителят разказва."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Майстор казва, че всяка поръчка се тества. Заснети са красиви рафтове и усмивка, но няма кадър на самия тест.\n\nРешение: Заснеми реалния тест: подготовка, измерване и резултат, със съответния звук и разрешение.\n\nДоказателство, че работи: Зрителят може да посочи на кадър действието, за което говорителят разказва."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Покриваш репликата с произволен кадър на инструмент и внушаваш проверка, която не се вижда."},"after":{"label":"Как го поправяш","text":"Заснеми реалния тест: подготовка, измерване и резултат, със съответния звук и разрешение. Зрителят може да посочи на кадър действието, за което говорителят разказва."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Вземи тридесет секунди от реален процес и напиши точно три липсващи визуални връзки, които монтажът изисква. Снимай само тях.\n\nВземи доказателство, което би показал на друг монтажист: Зрителят може да посочи на кадър действието, за което говорителят разказва.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Покриваш репликата с произволен кадър на инструмент и внушаваш проверка, която не се вижда.\n\nГраницата: B-roll не бива да инсценира доказателство за услуга, която не е извършена."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „B-roll, който покрива конкретен монтаж“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Вмъкни красив кадър от друга поръчка и го представи като същия тест."},{"id":"b","label":"B-roll трябва да доказва казаното и да покрива нужните преходи, не да пълни време."},{"id":"c","label":"Покриваш репликата с произволен кадър на инструмент и внушаваш проверка, която не се вижда."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"B-roll трябва да доказва казаното и да покрива нужните преходи, не да пълни време. За всяко твърдение запиши видимо действие: начало, изпълнение и резултат. Вземи широк, среден и близък план само когато те дават различна информация. Отбележи необходимия звук на действието."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Майстор казва, че всяка поръчка се тества. Заснети са красиви рафтове и усмивка, но няма кадър на самия тест.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Покриваш репликата с произволен кадър на инструмент и внушаваш проверка, която не се вижда."},{"id":"b","label":"Вмъкни красив кадър от друга поръчка и го представи като същия тест."},{"id":"c","label":"Заснеми реалния тест: подготовка, измерване и резултат, със съответния звук и разрешение."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Заснеми реалния тест: подготовка, измерване и резултат, със съответния звук и разрешение. Зрителят може да посочи на кадър действието, за което говорителят разказва."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"B-roll не бива да инсценира доказателство за услуга, която не е извършена."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Вмъкни красив кадър от друга поръчка и го представи като същия тест."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"B-roll не бива да инсценира доказателство за услуга, която не е извършена."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["B-roll трябва да доказва казаното и да покрива нужните преходи, не да пълни време.","Заснеми реалния тест: подготовка, измерване и резултат, със съответния звук и разрешение.","Не пропускай контрола: Зрителят може да посочи на кадър действието, за което говорителят разказва."],"nextStep":"Вземи тридесет секунди от реален процес и напиши точно три липсващи визуални връзки, които монтажът изисква. Снимай само тях."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. B-roll не бива да инсценира доказателство за услуга, която не е извършена.","items":[{"id":"s3","text":"Сними различни информативни дистанции и посоки."},{"id":"s1","text":"Разпиши ключовите твърдения или движения."},{"id":"s4","text":"Прегледай материала и попълни липсващите монтажни връзки."},{"id":"s2","text":"За всяко запиши начало, действие, резултат и нужен звук."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Разпиши ключовите твърдения или движения. → За всяко запиши начало, действие, резултат и нужен звук. → Сними различни информативни дистанции и посоки. → Прегледай материала и попълни липсващите монтажни връзки."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Процесът вече е приключил и няма разрешение за повторение.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Покриваш репликата с произволен кадър на инструмент и внушаваш проверка, която не се вижда."},{"id":"b","label":"Вмъкни красив кадър от друга поръчка и го представи като същия тест."},{"id":"c","label":"Използвай наличните честни кадри, промени формулировката на твърдението или отбележи липсата за нов снимачен ден."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Използвай наличните честни кадри, промени формулировката на твърдението или отбележи липсата за нов снимачен ден. B-roll не бива да инсценира доказателство за услуга, която не е извършена."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Листът за B-roll е договор между това, което се казва, и това, което действително може да бъде показано.\n\nРаботна карта:\n1. Разпиши ключовите твърдения или движения.\n2. За всяко запиши начало, действие, резултат и нужен звук.\n3. Сними различни информативни дистанции и посоки.\n4. Прегледай материала и попълни липсващите монтажни връзки.\n\nКритерий за предаване: Зрителят може да посочи на кадър действието, за което говорителят разказва."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-08","title":"Колко дубъла стигат?","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще спираш след проверен работещ дубъл и ще знаеш кога допълнителният има смисъл.","hook":"Десетият дубъл е изтощен, а първият е бил добър — само че никой не го е проверил.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще спираш след проверен работещ дубъл и ще знаеш кога допълнителният има смисъл. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Десетият дубъл е изтощен, а първият е бил добър — само че никой не го е проверил."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Преди повторение назови конкретния дефект: факт, тон, кадър, звук или движение.\n\nПървият дубъл често показва естествена енергия; вторият може да изчисти факт или движение. Няма магически брой повторения. Кратко възпроизвеждане със звук спестява повторения без цел."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Раздели „може да се монтира“ от „идеален“. Ако имаш чиста пълна фраза и нужните преходи, снимай вариант само с друга интонация или по-кратък отговор, когато проектът го иска. Ако проблемът е засядане от напрежение, промени въпроса или направи пауза, вместо да повтаряш същата команда. Маркирай успешните дубъли по файл и секунда.\n\nГраница на решението: При сложни движения или неповторимо събитие може да са нужни повече камери/покритие; броят дубъли сам по себе си не дава гаранция."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Определи какво трябва да се види и чуе.\n2. Сними един пълен дубъл и го прослушай.\n3. Назови конкретния проблем, преди да поискаш повторение.\n4. Сними целеви дубъл или продължи, ако материалът вече покрива задачата.\n\nСтоп-сигнал: Повтаряш фразата докато изчезне естественият тон, без да провериш втория файл.\nВърни се към пробата: Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Пекар отговаря добре за процеса на втория дубъл. Режисьорът иска още пет „за всеки случай“, но човекът започва да говори механично.\n\nРешение: Спри и прегледай втория дубъл със звук; ако той работи, премини към действие и детайли.\n\nДоказателство, че работи: Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Повтаряш фразата докато изчезне естественият тон, без да провериш втория файл."},"after":{"label":"Как го поправяш","text":"Спри и прегледай втория дубъл със звук; ако той работи, премини към действие и детайли. Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Симулирай три дубъла на кратка демонстрация. След всеки назови един дефект и реши с конкретен критерий дали повтаряш.\n\nВземи доказателство, което би показал на друг монтажист: Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Повтаряш фразата докато изчезне естественият тон, без да провериш втория файл.\n\nГраницата: При сложни движения или неповторимо събитие може да са нужни повече камери/покритие; броят дубъли сам по себе си не дава гаранция."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Колко дубъла стигат?“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Преди повторение назови конкретния дефект: факт, тон, кадър, звук или движение."},{"id":"b","label":"Повтаряш фразата докато изчезне естественият тон, без да провериш втория файл."},{"id":"c","label":"Снимай фиксирано поне осем дубъла на всяка реплика."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Преди повторение назови конкретния дефект: факт, тон, кадър, звук или движение. Първият дубъл често показва естествена енергия; вторият може да изчисти факт или движение. Няма магически брой повторения. Кратко възпроизвеждане със звук спестява повторения без цел."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Пекар отговаря добре за процеса на втория дубъл. Режисьорът иска още пет „за всеки случай“, но човекът започва да говори механично.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Снимай фиксирано поне осем дубъла на всяка реплика."},{"id":"b","label":"Спри и прегледай втория дубъл със звук; ако той работи, премини към действие и детайли."},{"id":"c","label":"Повтаряш фразата докато изчезне естественият тон, без да провериш втория файл."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Спри и прегледай втория дубъл със звук; ако той работи, премини към действие и детайли. Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Снимай фиксирано поне осем дубъла на всяка реплика."},{"id":"c","label":"При сложни движения или неповторимо събитие може да са нужни повече камери/покритие; броят дубъли сам по себе си не дава гаранция."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"При сложни движения или неповторимо събитие може да са нужни повече камери/покритие; броят дубъли сам по себе си не дава гаранция."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Преди повторение назови конкретния дефект: факт, тон, кадър, звук или движение.","Спри и прегледай втория дубъл със звук; ако той работи, премини към действие и детайли.","Не пропускай контрола: Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен."],"nextStep":"Симулирай три дубъла на кратка демонстрация. След всеки назови един дефект и реши с конкретен критерий дали повтаряш."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. При сложни движения или неповторимо събитие може да са нужни повече камери/покритие; броят дубъли сам по себе си не дава гаранция.","items":[{"id":"s3","text":"Назови конкретния проблем, преди да поискаш повторение."},{"id":"s1","text":"Определи какво трябва да се види и чуе."},{"id":"s4","text":"Сними целеви дубъл или продължи, ако материалът вече покрива задачата."},{"id":"s2","text":"Сними един пълен дубъл и го прослушай."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Определи какво трябва да се види и чуе. → Сними един пълен дубъл и го прослушай. → Назови конкретния проблем, преди да поискаш повторение. → Сними целеви дубъл или продължи, ако материалът вече покрива задачата."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: След паузата откриваш, че най-добрият дубъл има щракване в ключовата дума.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Снимай фиксирано поне осем дубъла на всяка реплика."},{"id":"b","label":"Поискай целеви повторен отговор при същата обстановка и проверен микрофон, вместо да повтаряш целия разговор."},{"id":"c","label":"Повтаряш фразата докато изчезне естественият тон, без да провериш втория файл."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Поискай целеви повторен отговор при същата обстановка и проверен микрофон, вместо да повтаряш целия разговор. При сложни движения или неповторимо събитие може да са нужни повече камери/покритие; броят дубъли сам по себе си не дава гаранция."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Кажи на човека какво вече работи и какво точно искаш да промениш.\n\nРаботна карта:\n1. Определи какво трябва да се види и чуе.\n2. Сними един пълен дубъл и го прослушай.\n3. Назови конкретния проблем, преди да поискаш повторение.\n4. Сними целеви дубъл или продължи, ако материалът вече покрива задачата.\n\nКритерий за предаване: Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-09","title":"План Б за светлина, звук и достъп","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще подготвиш решения за трите отказа, които могат да прекратят снимачния ден.","hook":"Небето се затваря, шумна машина тръгва и отговорният човек напуска — това не е необичаен ден.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще подготвиш решения за трите отказа, които могат да прекратят снимачния ден. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Небето се затваря, шумна машина тръгва и отговорният човек напуска — това не е необичаен ден."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Рискът става управляем, когато има ранно предупреждение, собственик на решение и резервна сцена.\n\nЗапиши критичен риск, вероятен симптом, действие и кой дава разрешение. За светлина може да има резервна позиция, за шум — друг времеви прозорец, за достъп — алтернативен човек или кадър."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Определи условия, при които снимането спира: опасен кабел, липса на право за локация, невъзможен за разбиране звук, непотвърдени права за лице. Не решавай чужди разрешения с подпис „после“. Ако се включи резервният план, съобщи на клиента каква информация или кадри ще се променят, преди да продължиш.\n\nГраница на решението: Резервният план не разрешава нарушаване на правилата на мястото или правата на участниците."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Назови три най-скъпи провала за проекта.\n2. Задай измерим симптом и човек за решение.\n3. Избери безопасна алтернатива преди снимачния ден.\n4. При проблем спри, потвърди промяната и направи нова проба.\n\nСтоп-сигнал: Пускаш машината „само за десет секунди“, защото вече е обещана в сценария.\nВърни се към пробата: Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Видео в работилница трябва да покаже машина. На терен се оказва, че демонстрацията днес не е разрешена по съображения за безопасност.\n\nРешение: Спри този кадър; потвърди друга безопасна демонстрация или пренасрочи и съгласувай промяната с клиента.\n\nДоказателство, че работи: Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Пускаш машината „само за десет секунди“, защото вече е обещана в сценария."},"after":{"label":"Как го поправяш","text":"Спри този кадър; потвърди друга безопасна демонстрация или пренасрочи и съгласувай промяната с клиента. Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"За следващия си снимачен ден напиши три реда „ако X, тогава Y“ и провери дали Y наистина е възможно с наличните хора и време.\n\nВземи доказателство, което би показал на друг монтажист: Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Пускаш машината „само за десет секунди“, защото вече е обещана в сценария.\n\nГраницата: Резервният план не разрешава нарушаване на правилата на мястото или правата на участниците."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „План Б за светлина, звук и достъп“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Пускаш машината „само за десет секунди“, защото вече е обещана в сценария."},{"id":"b","label":"Разчитай на софтуер, за да превърне опасна или несъществуваща сцена в доказателство."},{"id":"c","label":"Рискът става управляем, когато има ранно предупреждение, собственик на решение и резервна сцена."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Рискът става управляем, когато има ранно предупреждение, собственик на решение и резервна сцена. Запиши критичен риск, вероятен симптом, действие и кой дава разрешение. За светлина може да има резервна позиция, за шум — друг времеви прозорец, за достъп — алтернативен човек или кадър."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Видео в работилница трябва да покаже машина. На терен се оказва, че демонстрацията днес не е разрешена по съображения за безопасност.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Спри този кадър; потвърди друга безопасна демонстрация или пренасрочи и съгласувай промяната с клиента."},{"id":"b","label":"Пускаш машината „само за десет секунди“, защото вече е обещана в сценария."},{"id":"c","label":"Разчитай на софтуер, за да превърне опасна или несъществуваща сцена в доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Спри този кадър; потвърди друга безопасна демонстрация или пренасрочи и съгласувай промяната с клиента. Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Разчитай на софтуер, за да превърне опасна или несъществуваща сцена в доказателство."},{"id":"b","label":"Резервният план не разрешава нарушаване на правилата на мястото или правата на участниците."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Резервният план не разрешава нарушаване на правилата на мястото или правата на участниците."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Рискът става управляем, когато има ранно предупреждение, собственик на решение и резервна сцена.","Спри този кадър; потвърди друга безопасна демонстрация или пренасрочи и съгласувай промяната с клиента.","Не пропускай контрола: Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър."],"nextStep":"За следващия си снимачен ден напиши три реда „ако X, тогава Y“ и провери дали Y наистина е възможно с наличните хора и време."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Резервният план не разрешава нарушаване на правилата на мястото или правата на участниците.","items":[{"id":"s3","text":"Избери безопасна алтернатива преди снимачния ден."},{"id":"s1","text":"Назови три най-скъпи провала за проекта."},{"id":"s4","text":"При проблем спри, потвърди промяната и направи нова проба."},{"id":"s2","text":"Задай измерим симптом и човек за решение."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Назови три най-скъпи провала за проекта. → Задай измерим симптом и човек за решение. → Избери безопасна алтернатива преди снимачния ден. → При проблем спри, потвърди промяната и направи нова проба."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: План Б изисква локация, която клиентът не може да предостави.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Отбележи плана като невалиден и потърси вариант, който може да бъде потвърден предварително."},{"id":"b","label":"Пускаш машината „само за десет секунди“, защото вече е обещана в сценария."},{"id":"c","label":"Разчитай на софтуер, за да превърне опасна или несъществуваща сцена в доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Отбележи плана като невалиден и потърси вариант, който може да бъде потвърден предварително. Резервният план не разрешава нарушаване на правилата на мястото или правата на участниците."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Риск без изпълним отговор още е неизвестно. Запиши го честно, преди да обещаеш краен срок.\n\nРаботна карта:\n1. Назови три най-скъпи провала за проекта.\n2. Задай измерим симптом и човек за решение.\n3. Избери безопасна алтернатива преди снимачния ден.\n4. При проблем спри, потвърди промяната и направи нова проба.\n\nКритерий за предаване: Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-10","title":"Репетиция на терен с истинските условия","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще направиш кратка генерална проба с човек, камера, звук и движение преди основния запис.","hook":"Празният кадър е перфектен; щом човекът седне, микрофонът търка сакото и ръката закрива продукта.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще направиш кратка генерална проба с човек, камера, звук и движение преди основния запис. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Празният кадър е перфектен; щом човекът седне, микрофонът търка сакото и ръката закрива продукта."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Репетирай действието, което ще снимаш, а не празна сцена с красив фокус.\n\nВключи истинския човек, облекло, предмет, звук и път на движение. Провери във видеото начало, ключова реплика и край на действието. Не е нужно дълго разиграване, но пробата трябва да покаже какво може да провали кадъра."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Прегледай записа веднага и назови само проверимите проблеми: дреха шуми в определен момент, лице излиза от светлината, ръка закрива етикета. Промени позиция, звук или движение и повтори същата проба. Ако сцената включва неповторим момент, направи съкратена репетиция без да го изхабяваш и подготви резервен план.\n\nГраница на решението: Репетицията не трябва да нарушава безопасност или да изразходва единствения наличен продукт без съгласие."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Постави участник и предмет в истинските им позиции.\n2. Пусни кратко пълно действие със запис на звук.\n3. Прослушай и погледни най-трудния момент.\n4. Поправи една конкретна причина и повтори пробата.\n\nСтоп-сигнал: Казваш „ще оправим в монтажа“ и започваш цялата серия буркани.\nВърни се към пробата: На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Шеф-готвач показва пълнене на буркани. При първа проба етикетът се обръща от камерата, а метален капак удря микрофона.\n\nРешение: Промени страната на поставяне и позицията на микрофона; потвърди с втора кратка проба преди неповторимата работа.\n\nДоказателство, че работи: На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Казваш „ще оправим в монтажа“ и започваш цялата серия буркани."},"after":{"label":"Как го поправяш","text":"Промени страната на поставяне и позицията на микрофона; потвърди с втора кратка проба преди неповторимата работа. На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"За реална демонстрация сними 15-секунден пробен ход и сравни кадъра преди/след промяната. Запиши какво е довело до подобрението.\n\nВземи доказателство, което би показал на друг монтажист: На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Казваш „ще оправим в монтажа“ и започваш цялата серия буркани.\n\nГраницата: Репетицията не трябва да нарушава безопасност или да изразходва единствения наличен продукт без съгласие."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Репетиция на терен с истинските условия“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Сменяй пет настройки наведнъж и запомни кое точно е помогнало."},{"id":"b","label":"Репетирай действието, което ще снимаш, а не празна сцена с красив фокус."},{"id":"c","label":"Казваш „ще оправим в монтажа“ и започваш цялата серия буркани."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Репетирай действието, което ще снимаш, а не празна сцена с красив фокус. Включи истинския човек, облекло, предмет, звук и път на движение. Провери във видеото начало, ключова реплика и край на действието. Не е нужно дълго разиграване, но пробата трябва да покаже какво може да провали кадъра."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Шеф-готвач показва пълнене на буркани. При първа проба етикетът се обръща от камерата, а метален капак удря микрофона.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Казваш „ще оправим в монтажа“ и започваш цялата серия буркани."},{"id":"b","label":"Сменяй пет настройки наведнъж и запомни кое точно е помогнало."},{"id":"c","label":"Промени страната на поставяне и позицията на микрофона; потвърди с втора кратка проба преди неповторимата работа."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Промени страната на поставяне и позицията на микрофона; потвърди с втора кратка проба преди неповторимата работа. На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Репетицията не трябва да нарушава безопасност или да изразходва единствения наличен продукт без съгласие."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Сменяй пет настройки наведнъж и запомни кое точно е помогнало."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Репетицията не трябва да нарушава безопасност или да изразходва единствения наличен продукт без съгласие."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Репетирай действието, което ще снимаш, а не празна сцена с красив фокус.","Промени страната на поставяне и позицията на микрофона; потвърди с втора кратка проба преди неповторимата работа.","Не пропускай контрола: На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори."],"nextStep":"За реална демонстрация сними 15-секунден пробен ход и сравни кадъра преди/след промяната. Запиши какво е довело до подобрението."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Репетицията не трябва да нарушава безопасност или да изразходва единствения наличен продукт без съгласие.","items":[{"id":"s3","text":"Прослушай и погледни най-трудния момент."},{"id":"s1","text":"Постави участник и предмет в истинските им позиции."},{"id":"s4","text":"Поправи една конкретна причина и повтори пробата."},{"id":"s2","text":"Пусни кратко пълно действие със запис на звук."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Постави участник и предмет в истинските им позиции. → Пусни кратко пълно действие със запис на звук. → Прослушай и погледни най-трудния момент. → Поправи една конкретна причина и повтори пробата."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Продуктът може да се използва само веднъж и проба с него не е възможна.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Казваш „ще оправим в монтажа“ и започваш цялата серия буркани."},{"id":"b","label":"Сменяй пет настройки наведнъж и запомни кое точно е помогнало."},{"id":"c","label":"Репетирай с празна опаковка или заместител със сходен размер; осигури достатъчно камери/покритие за единствения истински дубъл."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Репетирай с празна опаковка или заместител със сходен размер; осигури достатъчно камери/покритие за единствения истински дубъл. Репетицията не трябва да нарушава безопасност или да изразходва единствения наличен продукт без съгласие."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Добрият снимачен ден започва със запис, който спокойно можеш да изтриеш — след като си научил от него.\n\nРаботна карта:\n1. Постави участник и предмет в истинските им позиции.\n2. Пусни кратко пълно действие със запис на звук.\n3. Прослушай и погледни най-трудния момент.\n4. Поправи една конкретна причина и повтори пробата.\n\nКритерий за предаване: На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-11","title":"Човек пред камера: свали напрежението с работа","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще помогнеш на притеснен говорител да каже смисъла със свой глас, без да му диктуваш личност.","hook":"Казваш „отпусни се“ и човекът става още по-напрегнат.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще помогнеш на притеснен говорител да каже смисъла със свой глас, без да му диктуваш личност. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Казваш „отпусни се“ и човекът става още по-напрегнат."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Дай проста задача, кратък въпрос и право на повторение; обясни какво ще използваш от записа.\n\nЗапочни с нещо, което човекът прави всеки ден, или с лесен конкретен въпрос. Пази малък брой хора около камерата и дай време за пробен дубъл без публика. Кажи „Това начало работи, нека повторим последната мисъл по-бавно“, вместо обща оценка на човека."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Провери дали напрежението не идва от реално опасение: неясна употреба на видеото, непотвърдени фирмени твърдения или липса на съгласие. Реши причината, не я лекувай с комплименти. Дай на говорителя възможност да не отговори на въпрос и да уточни казаното, без да обещаваш право да пренапише честен факт след монтажа.\n\nГраница на решението: Не всеки човек се чувства удобно пред камера; ако продължава да не иска участие, смени формата или говорителя."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Обясни употреба, време и как протича записа.\n2. Започни с лесно конкретно действие или въпрос.\n3. Дай една точна обратна връзка след проба.\n4. Провери смисъла и звука преди да продължиш.\n\nСтоп-сигнал: Повтаряш „по-естествено!“ без да ѝ кажеш коя част вече е добра.\nВърни се към пробата: Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Счетоводителка трябва да обясни нова услуга. На четвъртия дубъл чете все по-бързо и бърка условие за цена.\n\nРешение: Спрете за минута, уточнете точната цена и условие, попитай я за реален клиентски случай и вземи една кратка мисъл наведнъж.\n\nДоказателство, че работи: Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Повтаряш „по-естествено!“ без да ѝ кажеш коя част вече е добра."},"after":{"label":"Как го поправяш","text":"Спрете за минута, уточнете точната цена и условие, попитай я за реален клиентски случай и вземи една кратка мисъл наведнъж. Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Направи два пробни въпроса на познат човек: абстрактен и за реален случай. Прегледай с него къде се появява конкретен отговор.\n\nВземи доказателство, което би показал на друг монтажист: Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Повтаряш „по-естествено!“ без да ѝ кажеш коя част вече е добра.\n\nГраницата: Не всеки човек се чувства удобно пред камера; ако продължава да не иска участие, смени формата или говорителя."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Човек пред камера: свали напрежението с работа“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Дай проста задача, кратък въпрос и право на повторение; обясни какво ще използваш от записа."},{"id":"b","label":"Повтаряш „по-естествено!“ без да ѝ кажеш коя част вече е добра."},{"id":"c","label":"Промени текста тайно в монтажа така, че участникът да звучи по-уверено."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Дай проста задача, кратък въпрос и право на повторение; обясни какво ще използваш от записа. Започни с нещо, което човекът прави всеки ден, или с лесен конкретен въпрос. Пази малък брой хора около камерата и дай време за пробен дубъл без публика. Кажи „Това начало работи, нека повторим последната мисъл по-бавно“, вместо обща оценка на човека."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Счетоводителка трябва да обясни нова услуга. На четвъртия дубъл чете все по-бързо и бърка условие за цена.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Промени текста тайно в монтажа така, че участникът да звучи по-уверено."},{"id":"b","label":"Спрете за минута, уточнете точната цена и условие, попитай я за реален клиентски случай и вземи една кратка мисъл наведнъж."},{"id":"c","label":"Повтаряш „по-естествено!“ без да ѝ кажеш коя част вече е добра."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Спрете за минута, уточнете точната цена и условие, попитай я за реален клиентски случай и вземи една кратка мисъл наведнъж. Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Промени текста тайно в монтажа така, че участникът да звучи по-уверено."},{"id":"c","label":"Не всеки човек се чувства удобно пред камера; ако продължава да не иска участие, смени формата или говорителя."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Не всеки човек се чувства удобно пред камера; ако продължава да не иска участие, смени формата или говорителя."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Дай проста задача, кратък въпрос и право на повторение; обясни какво ще използваш от записа.","Спрете за минута, уточнете точната цена и условие, попитай я за реален клиентски случай и вземи една кратка мисъл наведнъж.","Не пропускай контрола: Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани."],"nextStep":"Направи два пробни въпроса на познат човек: абстрактен и за реален случай. Прегледай с него къде се появява конкретен отговор."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Не всеки човек се чувства удобно пред камера; ако продължава да не иска участие, смени формата или говорителя.","items":[{"id":"s3","text":"Дай една точна обратна връзка след проба."},{"id":"s1","text":"Обясни употреба, време и как протича записа."},{"id":"s4","text":"Провери смисъла и звука преди да продължиш."},{"id":"s2","text":"Започни с лесно конкретно действие или въпрос."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Обясни употреба, време и как протича записа. → Започни с лесно конкретно действие или въпрос. → Дай една точна обратна връзка след проба. → Провери смисъла и звука преди да продължиш."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Човекът казва, че не желае да говори за личен клиентски случай.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Промени текста тайно в монтажа така, че участникът да звучи по-уверено."},{"id":"b","label":"Премини към анонимизиран процес или друг пример, който той доброволно може да обясни."},{"id":"c","label":"Повтаряш „по-естествено!“ без да ѝ кажеш коя част вече е добра."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Премини към анонимизиран процес или друг пример, който той доброволно може да обясни. Не всеки човек се чувства удобно пред камера; ако продължава да не иска участие, смени формата или говорителя."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Уважението не забавя работата. То прави възможен кадър, в който човекът наистина говори.\n\nРаботна карта:\n1. Обясни употреба, време и как протича записа.\n2. Започни с лесно конкретно действие или въпрос.\n3. Дай една точна обратна връзка след проба.\n4. Провери смисъла и звука преди да продължиш.\n\nКритерий за предаване: Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-12","title":"Интервю: въпросите, които дават истински отговор","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще формулираш въпроси, които извеждат действия, избори и проверими подробности.","hook":"На „Как сте по-добри от конкуренцията?“ получаваш пет общи прилагателни и нито един кадър.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще формулираш въпроси, които извеждат действия, избори и проверими подробности. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"На „Как сте по-добри от конкуренцията?“ получаваш пет общи прилагателни и нито един кадър."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Искай случай и действие: какво се случи, какво избрахте, какъв резултат наблюдавахте.\n\nКраткият въпрос оставя място за разказ. „Разкажи за последния клиент, на когото помогна“ дава по-добър материал от „Кажи, че сте най-добрите“. След конкретния случай попитай за доказателство, ограничение и какво не е проработило."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Изслушай отговора докрай, не задавай втори въпрос върху първия. Отбележи фраза, която изисква проверка: число, срок, резултат или здравно/финансово обещание. Планирай покривни кадри за действията, които участникът описва. Когато отговорът е само лозунг, помоли за един конкретен ден, предмет или действие.\n\nГраница на решението: Не всяка история е публична; пази поверителността и провери кои примери могат да се разказват."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Запиши какво зрителят трябва да разбере.\n2. Задай кратък въпрос за реален случай.\n3. Попитай какво се вижда, как е проверено и какви са границите.\n4. Маркирай ключови факти за потвърждение и кадри за покритие.\n\nСтоп-сигнал: Насочваш го да повтори лозунга с повече ентусиазъм.\nВърни се към пробата: В отговора има конкретно действие и граница, които могат да се проверят и покажат."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Производител на халва казва „качеството е в основата“. Трябва ти видео за реалното производство.\n\nРешение: Попитай как днес проверяват една партида, какво виждат при грешка и кой взема решението да я спре.\n\nДоказателство, че работи: В отговора има конкретно действие и граница, които могат да се проверят и покажат."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Насочваш го да повтори лозунга с повече ентусиазъм."},"after":{"label":"Как го поправяш","text":"Попитай как днес проверяват една партида, какво виждат при грешка и кой взема решението да я спре. В отговора има конкретно действие и граница, които могат да се проверят и покажат."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Вземи общо рекламно твърдение от собствен сайт и направи от него три въпроса за конкретен случай, мярка и ограничение.\n\nВземи доказателство, което би показал на друг монтажист: В отговора има конкретно действие и граница, които могат да се проверят и покажат.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Насочваш го да повтори лозунга с повече ентусиазъм.\n\nГраницата: Не всяка история е публична; пази поверителността и провери кои примери могат да се разказват."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Интервю: въпросите, които дават истински отговор“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Насочваш го да повтори лозунга с повече ентусиазъм."},{"id":"b","label":"Задай наведнъж три въпроса и после избери удобния отговор."},{"id":"c","label":"Искай случай и действие: какво се случи, какво избрахте, какъв резултат наблюдавахте."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Искай случай и действие: какво се случи, какво избрахте, какъв резултат наблюдавахте. Краткият въпрос оставя място за разказ. „Разкажи за последния клиент, на когото помогна“ дава по-добър материал от „Кажи, че сте най-добрите“. След конкретния случай попитай за доказателство, ограничение и какво не е проработило."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Производител на халва казва „качеството е в основата“. Трябва ти видео за реалното производство.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Попитай как днес проверяват една партида, какво виждат при грешка и кой взема решението да я спре."},{"id":"b","label":"Насочваш го да повтори лозунга с повече ентусиазъм."},{"id":"c","label":"Задай наведнъж три въпроса и после избери удобния отговор."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Попитай как днес проверяват една партида, какво виждат при грешка и кой взема решението да я спре. В отговора има конкретно действие и граница, които могат да се проверят и покажат."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Задай наведнъж три въпроса и после избери удобния отговор."},{"id":"b","label":"Не всяка история е публична; пази поверителността и провери кои примери могат да се разказват."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Не всяка история е публична; пази поверителността и провери кои примери могат да се разказват."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Искай случай и действие: какво се случи, какво избрахте, какъв резултат наблюдавахте.","Попитай как днес проверяват една партида, какво виждат при грешка и кой взема решението да я спре.","Не пропускай контрола: В отговора има конкретно действие и граница, които могат да се проверят и покажат."],"nextStep":"Вземи общо рекламно твърдение от собствен сайт и направи от него три въпроса за конкретен случай, мярка и ограничение."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Не всяка история е публична; пази поверителността и провери кои примери могат да се разказват.","items":[{"id":"s3","text":"Попитай какво се вижда, как е проверено и какви са границите."},{"id":"s1","text":"Запиши какво зрителят трябва да разбере."},{"id":"s4","text":"Маркирай ключови факти за потвърждение и кадри за покритие."},{"id":"s2","text":"Задай кратък въпрос за реален случай."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Запиши какво зрителят трябва да разбере. → Задай кратък въпрос за реален случай. → Попитай какво се вижда, как е проверено и какви са границите. → Маркирай ключови факти за потвърждение и кадри за покритие."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Човекът започва да разкрива лични данни на клиент.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Спрете, уточнете какво може да се каже и презаснемете с анонимен, позволен пример."},{"id":"b","label":"Насочваш го да повтори лозунга с повече ентусиазъм."},{"id":"c","label":"Задай наведнъж три въпроса и после избери удобния отговор."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Спрете, уточнете какво може да се каже и презаснемете с анонимен, позволен пример. Не всяка история е публична; пази поверителността и провери кои примери могат да се разказват."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Пет силни въпроса не са фиксиран шаблон: слушането между тях определя какво идва след това.\n\nРаботна карта:\n1. Запиши какво зрителят трябва да разбере.\n2. Задай кратък въпрос за реален случай.\n3. Попитай какво се вижда, как е проверено и какви са границите.\n4. Маркирай ключови факти за потвърждение и кадри за покритие.\n\nКритерий за предаване: В отговора има конкретно действие и граница, които могат да се проверят и покажат."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-13","title":"Естествено поведение с видима камера","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще снимаш реална работа, без да представяш режисирана сцена за случайно наблюдение.","hook":"Когато хората видят камерата, започват да играят „работещи хора“ и забравят реалната задача.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще снимаш реална работа, без да представяш режисирана сцена за случайно наблюдение. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Когато хората видят камерата, започват да играят „работещи хора“ и забравят реалната задача."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Дай време на участника да се върне към познатото действие и снимай истинския процес с ясни правила.\n\nПреди запис обясни коя дейност ще се снима и кой няма да попада в кадър. Не крий камерата като техника за „автентичност“. Избери по-дълъг статичен кадър, остави човека да работи и поддържай малък екип."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Можеш да помолиш за повторение на действие за технически кадър, но не представяй повторението като доказателство за уникално събитие, което не се е случило. Запази последователност от началото до края и истински звук от работата. Ако присъствието на камера променя процедурата или нарушава безопасност, спри и адаптирай кадъра.\n\nГраница на решението: Реакцията „естествено“ не оправдава скрит запис на хора без подходящи права и контекст."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Уточни дейността и границите на снимане.\n2. Постави камерата така, че да не пречи на работата.\n3. Запиши цял цикъл на действие и собствен звук.\n4. Провери дали монтажът не внушава несъществуващ резултат.\n\nСтоп-сигнал: Режисираш последователност, в която липсва реалната проверка, а после твърдиш, че е заснета.\nВърни се към пробата: Видеото показва реалната последователност и участниците знаят кога и защо са заснети."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Майсторка опакова поръчка. Екипът иска тя да се усмихва към камерата при всяка стъпка, но така пропуска контролното теглене.\n\nРешение: Остави реалния работен ред, заснеми тегленето и поискай отделен портретен кадър след приключване.\n\nДоказателство, че работи: Видеото показва реалната последователност и участниците знаят кога и защо са заснети."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Режисираш последователност, в която липсва реалната проверка, а после твърдиш, че е заснета."},"after":{"label":"Как го поправяш","text":"Остави реалния работен ред, заснеми тегленето и поискай отделен портретен кадър след приключване. Видеото показва реалната последователност и участниците знаят кога и защо са заснети."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Сними непрекъснати 30 секунди от доброволно показан процес и после монтирай 10 секунди без да сменяш причинно-следствения ред.\n\nВземи доказателство, което би показал на друг монтажист: Видеото показва реалната последователност и участниците знаят кога и защо са заснети.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Режисираш последователност, в която липсва реалната проверка, а после твърдиш, че е заснета.\n\nГраницата: Реакцията „естествено“ не оправдава скрит запис на хора без подходящи права и контекст."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Естествено поведение с видима камера“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Сложи скрита камера и после искай разрешения."},{"id":"b","label":"Дай време на участника да се върне към познатото действие и снимай истинския процес с ясни правила."},{"id":"c","label":"Режисираш последователност, в която липсва реалната проверка, а после твърдиш, че е заснета."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Дай време на участника да се върне към познатото действие и снимай истинския процес с ясни правила. Преди запис обясни коя дейност ще се снима и кой няма да попада в кадър. Не крий камерата като техника за „автентичност“. Избери по-дълъг статичен кадър, остави човека да работи и поддържай малък екип."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Майсторка опакова поръчка. Екипът иска тя да се усмихва към камерата при всяка стъпка, но така пропуска контролното теглене.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Режисираш последователност, в която липсва реалната проверка, а после твърдиш, че е заснета."},{"id":"b","label":"Сложи скрита камера и после искай разрешения."},{"id":"c","label":"Остави реалния работен ред, заснеми тегленето и поискай отделен портретен кадър след приключване."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Остави реалния работен ред, заснеми тегленето и поискай отделен портретен кадър след приключване. Видеото показва реалната последователност и участниците знаят кога и защо са заснети."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Реакцията „естествено“ не оправдава скрит запис на хора без подходящи права и контекст."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Сложи скрита камера и после искай разрешения."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Реакцията „естествено“ не оправдава скрит запис на хора без подходящи права и контекст."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Дай време на участника да се върне към познатото действие и снимай истинския процес с ясни правила.","Остави реалния работен ред, заснеми тегленето и поискай отделен портретен кадър след приключване.","Не пропускай контрола: Видеото показва реалната последователност и участниците знаят кога и защо са заснети."],"nextStep":"Сними непрекъснати 30 секунди от доброволно показан процес и после монтирай 10 секунди без да сменяш причинно-следствения ред."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Реакцията „естествено“ не оправдава скрит запис на хора без подходящи права и контекст.","items":[{"id":"s3","text":"Запиши цял цикъл на действие и собствен звук."},{"id":"s1","text":"Уточни дейността и границите на снимане."},{"id":"s4","text":"Провери дали монтажът не внушава несъществуващ резултат."},{"id":"s2","text":"Постави камерата така, че да не пречи на работата."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Уточни дейността и границите на снимане. → Постави камерата така, че да не пречи на работата. → Запиши цял цикъл на действие и собствен звук. → Провери дали монтажът не внушава несъществуващ резултат."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: По време на процеса влиза случаен клиент, който не е част от снимките.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Режисираш последователност, в която липсва реалната проверка, а после твърдиш, че е заснета."},{"id":"b","label":"Сложи скрита камера и после искай разрешения."},{"id":"c","label":"Спри или промени кадъра, така че клиентът да не бъде записван/публикуван без подходящо основание."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Спри или промени кадъра, така че клиентът да не бъде записван/публикуван без подходящо основание. Реакцията „естествено“ не оправдава скрит запис на хора без подходящи права и контекст."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Можеш да режисираш рамката и позицията, без да режисираш фалшив факт.\n\nРаботна карта:\n1. Уточни дейността и границите на снимане.\n2. Постави камерата така, че да не пречи на работата.\n3. Запиши цял цикъл на действие и собствен звук.\n4. Провери дали монтажът не внушава несъществуващ резултат.\n\nКритерий за предаване: Видеото показва реалната последователност и участниците знаят кога и защо са заснети."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-14","title":"Снимане на деца: ясни граници преди кадъра","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще организираш детска сцена само след проверени правила, достъп и отговорен възрастен.","hook":"Училището казва „всички са съгласни“, но няма яснота за реклама, съхранение и конкретните деца в кадър.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще организираш детска сцена само след проверени правила, достъп и отговорен възрастен. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Училището казва „всички са съгласни“, но няма яснота за реклама, съхранение и конкретните деца в кадър."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Преди камерата провери с организацията правното основание, употребата, ограниченията и кой отговаря за всяко дете.\n\nРаботи със списък кой може да се снима и за каква конкретна цел, даден от упълномощения организатор. Не записвай имена и излишни лични данни в кадър. Определи безопасни зони за деца извън камерата."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"При училища съгласието може да не е единственото или подходящото правно основание; организацията и нейният отговорник за данните трябва да определят условията. Същият кадър може да има различни правила за вътрешно използване и публична реклама. Не приемай, че общо разрешение за училищна снимка покрива клиентски клип. Изясни съхранение и изтриване, достъп до оригинали, надзор и право на отказ по приложимите правила.\n\nГраница на решението: Въпросите за права на деца зависят от конкретните отношения и закон; редакторът не трябва сам да измисля правно основание."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Установи отговорен възрастен и правилата на организацията.\n2. Провери кои участници и употреби са разрешени.\n3. Подготви кадри, които не разкриват ненужни данни.\n4. Преди публикуване провери финалната версия и обхвата на разрешенията.\n\nСтоп-сигнал: Приемаш вътрешното разрешение за достатъчно и изпращаш рекламата без нова проверка.\nВърни се към пробата: За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"НПО снима детска работилница. Има разрешение за вътрешен отчет, но по-късно иска публична платена реклама със същите лица.\n\nРешение: Спри публикуването и поискай от организацията проверка на правното основание и обхвата за публична платена употреба; подготви вариант без разпознаваеми деца.\n\nДоказателство, че работи: За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Приемаш вътрешното разрешение за достатъчно и изпращаш рекламата без нова проверка."},"after":{"label":"Как го поправяш","text":"Спри публикуването и поискай от организацията проверка на правното основание и обхвата за публична платена употреба; подготви вариант без разпознаваеми деца. За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"За учебен пример с условни лица направи таблица: вътрешен отчет, сайт, платена реклама. Отбележи кои употреби са потвърдени и кои чакат организацията.\n\nВземи доказателство, което би показал на друг монтажист: За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Приемаш вътрешното разрешение за достатъчно и изпращаш рекламата без нова проверка.\n\nГраницата: Въпросите за права на деца зависят от конкретните отношения и закон; редакторът не трябва сам да измисля правно основание."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Снимане на деца: ясни граници преди кадъра“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Преди камерата провери с организацията правното основание, употребата, ограниченията и кой отговаря за всяко дете."},{"id":"b","label":"Приемаш вътрешното разрешение за достатъчно и изпращаш рекламата без нова проверка."},{"id":"c","label":"Публикувай със замъглено лице, без да провериш дали и гласът, името или контекстът разпознават детето."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Преди камерата провери с организацията правното основание, употребата, ограниченията и кой отговаря за всяко дете. Работи със списък кой може да се снима и за каква конкретна цел, даден от упълномощения организатор. Не записвай имена и излишни лични данни в кадър. Определи безопасни зони за деца извън камерата."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"НПО снима детска работилница. Има разрешение за вътрешен отчет, но по-късно иска публична платена реклама със същите лица.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Публикувай със замъглено лице, без да провериш дали и гласът, името или контекстът разпознават детето."},{"id":"b","label":"Спри публикуването и поискай от организацията проверка на правното основание и обхвата за публична платена употреба; подготви вариант без разпознаваеми деца."},{"id":"c","label":"Приемаш вътрешното разрешение за достатъчно и изпращаш рекламата без нова проверка."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Спри публикуването и поискай от организацията проверка на правното основание и обхвата за публична платена употреба; подготви вариант без разпознаваеми деца. За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Публикувай със замъглено лице, без да провериш дали и гласът, името или контекстът разпознават детето."},{"id":"c","label":"Въпросите за права на деца зависят от конкретните отношения и закон; редакторът не трябва сам да измисля правно основание."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Въпросите за права на деца зависят от конкретните отношения и закон; редакторът не трябва сам да измисля правно основание."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Преди камерата провери с организацията правното основание, употребата, ограниченията и кой отговаря за всяко дете.","Спри публикуването и поискай от организацията проверка на правното основание и обхвата за публична платена употреба; подготви вариант без разпознаваеми деца.","Не пропускай контрола: За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани."],"nextStep":"За учебен пример с условни лица направи таблица: вътрешен отчет, сайт, платена реклама. Отбележи кои употреби са потвърдени и кои чакат организацията."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Въпросите за права на деца зависят от конкретните отношения и закон; редакторът не трябва сам да измисля правно основание.","items":[{"id":"s3","text":"Подготви кадри, които не разкриват ненужни данни."},{"id":"s1","text":"Установи отговорен възрастен и правилата на организацията."},{"id":"s4","text":"Преди публикуване провери финалната версия и обхвата на разрешенията."},{"id":"s2","text":"Провери кои участници и употреби са разрешени."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Установи отговорен възрастен и правилата на организацията. → Провери кои участници и употреби са разрешени. → Подготви кадри, които не разкриват ненужни данни. → Преди публикуване провери финалната версия и обхвата на разрешенията."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: В залата влиза дете, за което няма потвърдено разрешение за запис.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Публикувай със замъглено лице, без да провериш дали и гласът, името или контекстът разпознават детето."},{"id":"b","label":"Насочи камерата към работа без разпознаваемо лице или изчакай организацията да изясни условията."},{"id":"c","label":"Приемаш вътрешното разрешение за достатъчно и изпращаш рекламата без нова проверка."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Насочи камерата към работа без разпознаваемо лице или изчакай организацията да изясни условията. Въпросите за права на деца зависят от конкретните отношения и закон; редакторът не трябва сам да измисля правно основание."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Проверка: EDPB разглежда специално съгласието в училищни отношения: https://www.edpb.europa.eu/sites/default/files/files/file1/edpb_guidelines_202005_consent_en.pdf . Уточнявай случая с отговорното лице.\n\nРаботна карта:\n1. Установи отговорен възрастен и правилата на организацията.\n2. Провери кои участници и употреби са разрешени.\n3. Подготви кадри, които не разкриват ненужни данни.\n4. Преди публикуване провери финалната версия и обхвата на разрешенията.\n\nКритерий за предаване: За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-15","title":"Достъп, одобрения и факти във фирмен запис","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще подготвиш права за мястото и проверени твърдения, преди да снимаш фирмено видео.","hook":"Говорителят обещава „гарантиран резултат“, а логото на чужд клиент стои зад него.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще подготвиш права за мястото и проверени твърдения, преди да снимаш фирмено видео. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Говорителят обещава „гарантиран резултат“, а логото на чужд клиент стои зад него."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Раздели разрешение за място, участие на хора, използване на материали и проверка на публичните твърдения.\n\nЕдна фирма може да разреши снимки в офиса, без това да включва служители, клиентски документи, музика на заден план или чужди брандове. Запиши кой от компанията може да одобри всяка част."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Създай кратък списък с факти, които трябва да се потвърдят: цена, срок, обхват, резултати и условия. Запиши датата и източника на потвърждение, както и какво остава неизвестно. Преди снимачен ден прибери видимите чужди данни и набележи къде в кадъра се появяват чужди знаци. При смяна на сценария поискайте ново одобрение за новото твърдение, не го „поправяйте“ с дребен надпис.\n\nГраница на решението: Одобрение на груб монтаж не създава автоматично права върху чужда музика или лични данни."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Запиши всички планирани публични твърдения.\n2. Определи собственик на фактите и разрешенията.\n3. Провери локацията за чужди хора, знаци и документи.\n4. Сними само потвърденото и изпрати фактическия монтаж за одобрение.\n\nСтоп-сигнал: Оставяш числото и документа в кадър, защото ще излезе бързо в социалните мрежи.\nВърни се към пробата: Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Фирма за услуги казва, че работи с „над 500 клиента“, но никой не знае към коя дата е числото. На стена се вижда договор на друг клиент.\n\nРешение: Провери числото с отговорен човек и дата или го махни; прекадрирай така, че договорът да не попада във файла.\n\nДоказателство, че работи: Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Оставяш числото и документа в кадър, защото ще излезе бързо в социалните мрежи."},"after":{"label":"Как го поправяш","text":"Провери числото с отговорен човек и дата или го махни; прекадрирай така, че договорът да не попада във файла. Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Създай „лист на твърденията“ за 30-секундна реклама: факти, обещания, използвано лого и човек за одобрение. За непотвърдено остави празно.\n\nВземи доказателство, което би показал на друг монтажист: Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Оставяш числото и документа в кадър, защото ще излезе бързо в социалните мрежи.\n\nГраницата: Одобрение на груб монтаж не създава автоматично права върху чужда музика или лични данни."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Достъп, одобрения и факти във фирмен запис“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Оставяш числото и документа в кадър, защото ще излезе бързо в социалните мрежи."},{"id":"b","label":"Сложи дребен надпис „резултатите може да варират“ и остави неподкрепения абсолютен текст."},{"id":"c","label":"Раздели разрешение за място, участие на хора, използване на материали и проверка на публичните твърдения."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Раздели разрешение за място, участие на хора, използване на материали и проверка на публичните твърдения. Една фирма може да разреши снимки в офиса, без това да включва служители, клиентски документи, музика на заден план или чужди брандове. Запиши кой от компанията може да одобри всяка част."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Фирма за услуги казва, че работи с „над 500 клиента“, но никой не знае към коя дата е числото. На стена се вижда договор на друг клиент.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Провери числото с отговорен човек и дата или го махни; прекадрирай така, че договорът да не попада във файла."},{"id":"b","label":"Оставяш числото и документа в кадър, защото ще излезе бързо в социалните мрежи."},{"id":"c","label":"Сложи дребен надпис „резултатите може да варират“ и остави неподкрепения абсолютен текст."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Провери числото с отговорен човек и дата или го махни; прекадрирай така, че договорът да не попада във файла. Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Сложи дребен надпис „резултатите може да варират“ и остави неподкрепения абсолютен текст."},{"id":"b","label":"Одобрение на груб монтаж не създава автоматично права върху чужда музика или лични данни."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Одобрение на груб монтаж не създава автоматично права върху чужда музика или лични данни."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Раздели разрешение за място, участие на хора, използване на материали и проверка на публичните твърдения.","Провери числото с отговорен човек и дата или го махни; прекадрирай така, че договорът да не попада във файла.","Не пропускай контрола: Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни."],"nextStep":"Създай „лист на твърденията“ за 30-секундна реклама: факти, обещания, използвано лого и човек за одобрение. За непотвърдено остави празно."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Одобрение на груб монтаж не създава автоматично права върху чужда музика или лични данни.","items":[{"id":"s3","text":"Провери локацията за чужди хора, знаци и документи."},{"id":"s1","text":"Запиши всички планирани публични твърдения."},{"id":"s4","text":"Сними само потвърденото и изпрати фактическия монтаж за одобрение."},{"id":"s2","text":"Определи собственик на фактите и разрешенията."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Запиши всички планирани публични твърдения. → Определи собственик на фактите и разрешенията. → Провери локацията за чужди хора, знаци и документи. → Сними само потвърденото и изпрати фактическия монтаж за одобрение."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: След снимките маркетингът добавя ново твърдение за най-ниска цена.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Върни го за доказателство и одобрение с дата; без него не го поставяй в публичния файл."},{"id":"b","label":"Оставяш числото и документа в кадър, защото ще излезе бързо в социалните мрежи."},{"id":"c","label":"Сложи дребен надпис „резултатите може да варират“ и остави неподкрепения абсолютен текст."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Върни го за доказателство и одобрение с дата; без него не го поставяй в публичния файл. Одобрение на груб монтаж не създава автоматично права върху чужда музика или лични данни."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Вместо да искаш общо „одобрявам“, посочи на клиента точно какви факти и права той потвърждава.\n\nРаботна карта:\n1. Запиши всички планирани публични твърдения.\n2. Определи собственик на фактите и разрешенията.\n3. Провери локацията за чужди хора, знаци и документи.\n4. Сними само потвърденото и изпрати фактическия монтаж за одобрение.\n\nКритерий за предаване: Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-16","title":"Фирмен говорител без заучена реклама","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще изведеш ясна фирмена позиция от човек, който познава работата, и ще пазиш точността.","hook":"Управителят знае всичко, но в кадър казва само „качество, професионализъм, отношение“.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще изведеш ясна фирмена позиция от човек, който познава работата, и ще пазиш точността. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Управителят знае всичко, но в кадър казва само „качество, професионализъм, отношение“."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Попитай как фирмата работи в конкретен ден, после превърни отговора в една полезна за зрителя мисъл.\n\nПодготви до три цели: какъв проблем решава услугата, как протича работата и какво клиентът може да очаква. Поискай реален пример, в който самият говорител е взел решение."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Проверявай дали фирмените фрази са истина за целия клиентски процес. Ако човекът започне да чете страница с суперлативи, спри и го попитай как би обяснил услугата на свой познат. Запиши кратки самостоятелни отговори и чисти начални и крайни изречения за монтаж. Когато чужд отдел трябва да одобри условия, използвай само потвърдените части.\n\nГраница на решението: Няма нужда всеки управител да играе актьор; полезността идва от конкретния процес."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Избери една конкретна зрителска нужда.\n2. Вземи реален случай и проверими действия.\n3. Запиши кратки отговори със собствени думи.\n4. Свери фирмените факти и изгледай целия монтаж с говорителя.\n\nСтоп-сигнал: Оставяш абстрактното обещание, защото звучи добре на камера.\nВърни се към пробата: Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Управител на малък хотел трябва да обясни какво става при късно пристигане. Сценарият казва само „винаги сме на разположение“.\n\nРешение: Попитай за реалната процедура, час и начин на контакт; ако има условие, кажи го ясно и провери с екипа.\n\nДоказателство, че работи: Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Оставяш абстрактното обещание, защото звучи добре на камера."},"after":{"label":"Как го поправяш","text":"Попитай за реалната процедура, час и начин на контакт; ако има условие, кажи го ясно и провери с екипа. Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Сравни 20 секунди лозунги и 20 секунди конкретен отговор. Питай външен зрител кой вариант би му помогнал да вземе решение.\n\nВземи доказателство, което би показал на друг монтажист: Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Оставяш абстрактното обещание, защото звучи добре на камера.\n\nГраницата: Няма нужда всеки управител да играе актьор; полезността идва от конкретния процес."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Фирмен говорител без заучена реклама“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Подложи отговора на тежък ефект и бърз монтаж, за да не личи липсата на конкретика."},{"id":"b","label":"Попитай как фирмата работи в конкретен ден, после превърни отговора в една полезна за зрителя мисъл."},{"id":"c","label":"Оставяш абстрактното обещание, защото звучи добре на камера."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Попитай как фирмата работи в конкретен ден, после превърни отговора в една полезна за зрителя мисъл. Подготви до три цели: какъв проблем решава услугата, как протича работата и какво клиентът може да очаква. Поискай реален пример, в който самият говорител е взел решение."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Управител на малък хотел трябва да обясни какво става при късно пристигане. Сценарият казва само „винаги сме на разположение“.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Оставяш абстрактното обещание, защото звучи добре на камера."},{"id":"b","label":"Подложи отговора на тежък ефект и бърз монтаж, за да не личи липсата на конкретика."},{"id":"c","label":"Попитай за реалната процедура, час и начин на контакт; ако има условие, кажи го ясно и провери с екипа."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Попитай за реалната процедура, час и начин на контакт; ако има условие, кажи го ясно и провери с екипа. Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Няма нужда всеки управител да играе актьор; полезността идва от конкретния процес."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Подложи отговора на тежък ефект и бърз монтаж, за да не личи липсата на конкретика."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Няма нужда всеки управител да играе актьор; полезността идва от конкретния процес."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Попитай как фирмата работи в конкретен ден, после превърни отговора в една полезна за зрителя мисъл.","Попитай за реалната процедура, час и начин на контакт; ако има условие, кажи го ясно и провери с екипа.","Не пропускай контрола: Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени."],"nextStep":"Сравни 20 секунди лозунги и 20 секунди конкретен отговор. Питай външен зрител кой вариант би му помогнал да вземе решение."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Няма нужда всеки управител да играе актьор; полезността идва от конкретния процес.","items":[{"id":"s3","text":"Запиши кратки отговори със собствени думи."},{"id":"s1","text":"Избери една конкретна зрителска нужда."},{"id":"s4","text":"Свери фирмените факти и изгледай целия монтаж с говорителя."},{"id":"s2","text":"Вземи реален случай и проверими действия."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Избери една конкретна зрителска нужда. → Вземи реален случай и проверими действия. → Запиши кратки отговори със собствени думи. → Свери фирмените факти и изгледай целия монтаж с говорителя."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Няма потвърден нощен телефон за връзка.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Оставяш абстрактното обещание, защото звучи добре на камера."},{"id":"b","label":"Подложи отговора на тежък ефект и бърз монтаж, за да не личи липсата на конкретика."},{"id":"c","label":"Не го обещавай; остави потвърдените канали и поискайте актуална информация преди финала."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Не го обещавай; остави потвърдените канали и поискайте актуална информация преди финала. Няма нужда всеки управител да играе актьор; полезността идва от конкретния процес."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Добрият фирмен говорител звучи като човек, който може да помогне, а не като написана секция „За нас“.\n\nРаботна карта:\n1. Избери една конкретна зрителска нужда.\n2. Вземи реален случай и проверими действия.\n3. Запиши кратки отговори със собствени думи.\n4. Свери фирмените факти и изгледай целия монтаж с говорителя.\n\nКритерий за предаване: Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-17","title":"Снимай себе си без да гадаеш кадъра","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще снимаш сам себе си с повторяем кадър, фокус, звук и проверен запис.","hook":"Говориш убедително 20 минути, после откриваш, че фокусът е на рафта зад теб.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще снимаш сам себе си с повторяем кадър, фокус, звук и проверен запис. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Говориш убедително 20 минути, после откриваш, че фокусът е на рафта зад теб."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"При самозаснемане замести липсващия оператор с маркировки, контролен кадър и кратки проверки.\n\nМаркирай къде стоиш, заключи кадъра и провери фокус на истинското място на очите. Избери близък микрофон и прослушай проба. Използвай телефон или монитор за контрол, ако имаш, но не оставяй превюто да спира запис или изтощава батерия."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Раздели текста на кратки мисли и оставяй секунди тишина преди и след всяка. След промяна на позиция, облекло или светлина повтори теста; грешка в един дубъл е по-евтина от грешка в цял снимачен ден. Ако устройството има ограничение на запис или време, провери го предварително на истинската продължителност.\n\nГраница на решението: Автофокус и автоматична експозиция може да работят, но трябва да се тестват при реалното движение."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Маркирай позиция, кадър и разстояние до микрофона.\n2. Запиши проба с движение и най-силната реплика.\n3. Възпроизведи файла и провери очи, глас и таймер.\n4. Снимай на къси сегменти и проверявай след всяка смяна.\n\nСтоп-сигнал: Разчиташ, че широкият кадър ще се поправи с автоматично прекадриране.\nВърни се към пробата: Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Предприемач снима курс сам. Премества стола след първата почивка и продължава; всички следващи клипове имат отрязана ръка.\n\nРешение: Върни се към маркировката, запиши пробен кадър на стола и провери на възпроизведения файл.\n\nДоказателство, че работи: Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Разчиташ, че широкият кадър ще се поправи с автоматично прекадриране."},"after":{"label":"Как го поправяш","text":"Върни се към маркировката, запиши пробен кадър на стола и провери на възпроизведения файл. Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Сними три кратки сегмента с умишлена смяна на мястото между втория и третия; опиши коя проверка хваща разликата навреме.\n\nВземи доказателство, което би показал на друг монтажист: Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Разчиташ, че широкият кадър ще се поправи с автоматично прекадриране.\n\nГраницата: Автофокус и автоматична експозиция може да работят, но трябва да се тестват при реалното движение."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Снимай себе си без да гадаеш кадъра“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"При самозаснемане замести липсващия оператор с маркировки, контролен кадър и кратки проверки."},{"id":"b","label":"Разчиташ, че широкият кадър ще се поправи с автоматично прекадриране."},{"id":"c","label":"Провери само миниатюрата на екрана и изтрий тестовия файл без прослушване."}]},"points":2,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"При самозаснемане замести липсващия оператор с маркировки, контролен кадър и кратки проверки. Маркирай къде стоиш, заключи кадъра и провери фокус на истинското място на очите. Избери близък микрофон и прослушай проба. Използвай телефон или монитор за контрол, ако имаш, но не оставяй превюто да спира запис или изтощава батерия."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Предприемач снима курс сам. Премества стола след първата почивка и продължава; всички следващи клипове имат отрязана ръка.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Провери само миниатюрата на екрана и изтрий тестовия файл без прослушване."},{"id":"b","label":"Върни се към маркировката, запиши пробен кадър на стола и провери на възпроизведения файл."},{"id":"c","label":"Разчиташ, че широкият кадър ще се поправи с автоматично прекадриране."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Върни се към маркировката, запиши пробен кадър на стола и провери на възпроизведения файл. Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Провери само миниатюрата на екрана и изтрий тестовия файл без прослушване."},{"id":"c","label":"Автофокус и автоматична експозиция може да работят, но трябва да се тестват при реалното движение."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Автофокус и автоматична експозиция може да работят, но трябва да се тестват при реалното движение."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["При самозаснемане замести липсващия оператор с маркировки, контролен кадър и кратки проверки.","Върни се към маркировката, запиши пробен кадър на стола и провери на възпроизведения файл.","Не пропускай контрола: Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент."],"nextStep":"Сними три кратки сегмента с умишлена смяна на мястото между втория и третия; опиши коя проверка хваща разликата навреме."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Автофокус и автоматична експозиция може да работят, но трябва да се тестват при реалното движение.","items":[{"id":"s3","text":"Възпроизведи файла и провери очи, глас и таймер."},{"id":"s1","text":"Маркирай позиция, кадър и разстояние до микрофона."},{"id":"s4","text":"Снимай на къси сегменти и проверявай след всяка смяна."},{"id":"s2","text":"Запиши проба с движение и най-силната реплика."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Маркирай позиция, кадър и разстояние до микрофона. → Запиши проба с движение и най-силната реплика. → Възпроизведи файла и провери очи, глас и таймер. → Снимай на къси сегменти и проверявай след всяка смяна."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: Слънцето изчезва след първия сегмент.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Провери само миниатюрата на екрана и изтрий тестовия файл без прослушване."},{"id":"b","label":"Преоцени светлината, направи нов тест за експонация и баланс и запази контролен кадър за съвпадение."},{"id":"c","label":"Разчиташ, че широкият кадър ще се поправи с автоматично прекадриране."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Преоцени светлината, направи нов тест за експонация и баланс и запази контролен кадър за съвпадение. Автофокус и автоматична експозиция може да работят, но трябва да се тестват при реалното движение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Самостоятелната продукция изисква повече дисциплина, не непременно повече техника.\n\nРаботна карта:\n1. Маркирай позиция, кадър и разстояние до микрофона.\n2. Запиши проба с движение и най-силната реплика.\n3. Възпроизведи файла и провери очи, глас и таймер.\n4. Снимай на къси сегменти и проверявай след всяка смяна.\n\nКритерий за предаване: Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент."},"points":1,"required":false}]},{"module_id":"s02-m06","lesson_id":"pv06-18","title":"Финален проект: интервю с истински човек","subtitle":"Подготовка и работа с хора — снимачен ден без гадаене","objective":"Ще планираш, снимаш и предадеш кратко интервю, което издържа проверка на факти, звук, права и монтаж.","hook":"Силният финален въпрос не струва много, ако липсва право да използваш отговора или звукът е непригоден.","estimated_minutes":30,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Какво ще можеш","content":{"body":"Ще планираш, снимаш и предадеш кратко интервю, което издържа проверка на факти, звук, права и монтаж. Провери умението с работен случай, два теста и ред на действията."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Кога се чупи работата","content":{"body":"Силният финален въпрос не струва много, ако липсва право да използваш отговора или звукът е непригоден."},"points":1,"required":true},{"position":2,"block_key":"core","block_type":"rich_text","title":"Основното решение","content":{"body":"Работи с реален доброволен възрастен участник, разрешено място и проверена употреба на видеото.\n\nПодготви едностраничен план с цел, въпроси и задължителни действия за B-roll. На терен запиши проба, кратък разговор, звук от мястото и действия, които действително илюстрират казаното. Не използвай деца за този учебен проект."},"points":2,"required":true},{"position":3,"block_key":"deep_dive","block_type":"rich_text","title":"Какво се случва на терен","content":{"body":"Монтирай 60–90 секунди с ясна основна мисъл и поне един проверим конкретен случай. Прегледай всички числа, чужди лица, брандове и лиценз за музика. Сравни изходен и финален звук, провери синхрон и отвори файла на телефона, на който ще гледа публика. Пази оригинали и бележки за разрешенията; ако даден факт не може да бъде проверен, извади го или го върни за потвърждение.\n\nГраница на решението: Самооценката по чеклист не заменя действителна обратна връзка от зрител и отговорния за фактите."},"points":2,"required":true},{"position":4,"block_key":"method","block_type":"rich_text","title":"Работен ред","content":{"body":"Започни от условията, после променяй само това, което можеш да провериш.\n\n1. Осигури участник, цел, права и конкретни въпроси.\n2. Направи проба и заснеми разговор плюс честен B-roll.\n3. Монтирай за смисъл, разбираем глас и верни факти.\n4. Провери експорта, правата и финалния файл на реално устройство.\n\nСтоп-сигнал: Предаваш проекта като „готов“, защото картината е красива и музиката прикрива аудио грешките.\nВърни се към пробата: Външен зрител разбира кой, какво и как; твърденията и употребата са потвърдени, а речта е ясна без субтитри."},"points":2,"required":true},{"position":5,"block_key":"worked_example","block_type":"example","title":"Разгледай решен случай","content":{"body":"Интервю с пекар разказва как подготвя поръчки. Има жив отговор, но B-roll показва друга поръчка, а цената е казана без дата.\n\nРешение: Замени неточния B-roll с кадър от същия процес или махни внушението; потвърди цената с дата и преработи неразбираемата фраза.\n\nДоказателство, че работи: Външен зрител разбира кой, какво и как; твърденията и употребата са потвърдени, а речта е ясна без субтитри."},"points":2,"required":true},{"position":6,"block_key":"before_after","block_type":"before_after","title":"Грешният ход и корекцията","content":{"before":{"label":"Как се губи контрол","text":"Предаваш проекта като „готов“, защото картината е красива и музиката прикрива аудио грешките."},"after":{"label":"Как го поправяш","text":"Замени неточния B-roll с кадър от същия процес или махни внушението; потвърди цената с дата и преработи неразбираемата фраза. Външен зрител разбира кой, какво и как; твърденията и употребата са потвърдени, а речта е ясна без субтитри."}},"points":2,"required":true},{"position":7,"block_key":"field_diagnostic","block_type":"rich_text","title":"Проверка в истински условия","content":{"body":"Пусни експорта на човек, който не познава бизнеса, и попитай какво е разбрал. После провери по отделен списък права, факти, звук, синхрон и честност на B-roll.\n\nВземи доказателство, което би показал на друг монтажист: Външен зрител разбира кой, какво и как; твърденията и употребата са потвърдени, а речта е ясна без субтитри.\n\nАко резултатът не издържа, не замаскирай проблема с ефект. Върни се към причината: Предаваш проекта като „готов“, защото картината е красива и музиката прикрива аудио грешките.\n\nГраницата: Самооценката по чеклист не заменя действителна обратна връзка от зрител и отговорния за фактите."},"points":2,"required":true},{"position":8,"block_key":"knowledge_check","block_type":"quiz","title":"Избери работещия принцип","content":{"question":"При „Финален проект: интервю с истински човек“ кое решение запазва контрол върху резултата?","options":[{"id":"a","label":"Предаваш проекта като „готов“, защото картината е красива и музиката прикрива аудио грешките."},{"id":"b","label":"Приеми, че публикуването само по себе си доказва качество и налични права."},{"id":"c","label":"Работи с реален доброволен възрастен участник, разрешено място и проверена употреба на видеото."}]},"points":2,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Работи с реален доброволен възрастен участник, разрешено място и проверена употреба на видеото. Подготви едностраничен план с цел, въпроси и задължителни действия за B-roll. На терен запиши проба, кратък разговор, звук от мястото и действия, които действително илюстрират казаното. Не използвай деца за този учебен проект."},"scoring":{"mode":"single_choice"}},{"position":9,"block_key":"decision_case","block_type":"scenario","title":"Реши ситуацията","content":{"prompt":"Интервю с пекар разказва как подготвя поръчки. Има жив отговор, но B-roll показва друга поръчка, а цената е казана без дата.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Замени неточния B-roll с кадър от същия процес или махни внушението; потвърди цената с дата и преработи неразбираемата фраза."},{"id":"b","label":"Предаваш проекта като „готов“, защото картината е красива и музиката прикрива аудио грешките."},{"id":"c","label":"Приеми, че публикуването само по себе си доказва качество и налични права."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Замени неточния B-roll с кадър от същия процес или махни внушението; потвърди цената с дата и преработи неразбираемата фраза. Външен зрител разбира кой, какво и как; твърденията и употребата са потвърдени, а речта е ясна без субтитри."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"boundary_check","block_type":"quiz","title":"Къде свършва правилото","content":{"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?","options":[{"id":"a","label":"Приеми, че публикуването само по себе си доказва качество и налични права."},{"id":"b","label":"Самооценката по чеклист не заменя действителна обратна връзка от зрител и отговорния за фактите."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}]},"points":2,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Самооценката по чеклист не заменя действителна обратна връзка от зрител и отговорния за фактите."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"summary","block_type":"summary","title":"Запомни за следващите снимки","content":{"takeaways":["Работи с реален доброволен възрастен участник, разрешено място и проверена употреба на видеото.","Замени неточния B-roll с кадър от същия процес или махни внушението; потвърди цената с дата и преработи неразбираемата фраза.","Не пропускай контрола: Външен зрител разбира кой, какво и как; твърденията и употребата са потвърдени, а речта е ясна без субтитри."],"nextStep":"Пусни експорта на човек, който не познава бизнеса, и попитай какво е разбрал. После провери по отделен списък права, факти, звук, синхрон и честност на B-roll."},"points":2,"required":true},{"position":12,"block_key":"sequence_practice","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Самооценката по чеклист не заменя действителна обратна връзка от зрител и отговорния за фактите.","items":[{"id":"s3","text":"Монтирай за смисъл, разбираем глас и верни факти."},{"id":"s1","text":"Осигури участник, цел, права и конкретни въпроси."},{"id":"s4","text":"Провери експорта, правата и финалния файл на реално устройство."},{"id":"s2","text":"Направи проба и заснеми разговор плюс честен B-roll."}]},"points":2,"required":false,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред: Осигури участник, цел, права и конкретни въпроси. → Направи проба и заснеми разговор плюс честен B-roll. → Монтирай за смисъл, разбираем глас и верни факти. → Провери експорта, правата и финалния файл на реално устройство."},"scoring":{"mode":"exact_order"}},{"position":13,"block_key":"scenario_transfer","block_type":"scenario","title":"Когато условието се промени","content":{"prompt":"Нов случай: След завършване участникът уточнява, че един кадър съдържа поверителен документ.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Спри този експорт, премахни кадъра и предай проверена нова версия; актуализирай бележките за одобрение."},{"id":"b","label":"Предаваш проекта като „готов“, защото картината е красива и музиката прикрива аудио грешките."},{"id":"c","label":"Приеми, че публикуването само по себе си доказва качество и налични права."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Спри този експорт, премахни кадъра и предай проверена нова версия; актуализирай бележките за одобрение. Самооценката по чеклист не заменя действителна обратна връзка от зрител и отговорния за фактите."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"field_note","block_type":"rich_text","title":"Бележка от снимачния ден","content":{"body":"Финалният файл е резултат от проверими решения на терен и в монтажа, не награда за отметнати страници.\n\nРаботна карта:\n1. Осигури участник, цел, права и конкретни въпроси.\n2. Направи проба и заснеми разговор плюс честен B-roll.\n3. Монтирай за смисъл, разбираем глас и верни факти.\n4. Провери експорта, правата и финалния файл на реално устройство.\n\nКритерий за предаване: Външен зрител разбира кой, какво и как; твърденията и употребата са потвърдени, а речта е ясна без субтитри."},"points":1,"required":false}]}]$curriculum$::jsonb;
 item jsonb;
 part jsonb;
 lesson public.academy_lessons;
 new_version uuid;
 new_block uuid;
 validation_result jsonb;
 n integer := 0;
 rows_updated integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('perfect_video_modules_4_6_v5'));
 IF (SELECT count(*) FROM public.academy_lessons WHERE module_id IN ('s02-m04','s02-m05','s02-m06'))<>43
    OR (SELECT count(*) FROM public.academy_lessons WHERE module_id='s02-m04')<>17
    OR (SELECT count(*) FROM public.academy_lessons WHERE module_id='s02-m05')<>8
    OR (SELECT count(*) FROM public.academy_lessons WHERE module_id='s02-m06')<>18
    OR jsonb_array_length(payload)<>43 THEN
   RAISE EXCEPTION 'Perfect Video 4–6 lesson count changed; release aborted';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.academy_lesson_progress'::regclass
      AND tgname='archive_academy_lesson_progress_version' AND NOT tgisinternal) THEN
   RAISE EXCEPTION 'Progress archive trigger is missing';
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(payload) LOOP
   n:=n+1;
   SELECT * INTO lesson FROM public.academy_lessons
   WHERE module_id=item->>'module_id' AND lesson_id=item->>'lesson_id' FOR UPDATE;
   IF lesson.id IS NULL OR lesson.status<>'published'
      OR lesson.published_version_id IS NULL
      OR lesson.published_version_id IS DISTINCT FROM lesson.draft_version_id
      OR (SELECT count(*) FROM public.academy_lesson_versions WHERE academy_lesson_id=lesson.id)<>2 THEN
     RAISE EXCEPTION 'Unexpected lesson state: %/%',item->>'module_id',item->>'lesson_id';
   END IF;
   IF (SELECT count(*) FROM jsonb_array_elements(item->'blocks'))<>15 THEN
     RAISE EXCEPTION 'Wrong block count: %/%',item->>'module_id',item->>'lesson_id';
   END IF;
   INSERT INTO public.academy_lesson_versions
     (academy_lesson_id,version_number,origin_version_id,title,subtitle,duration,objective,hook,
      estimated_minutes,source_kind,change_note)
   SELECT lesson.id, max(version_number)+1,lesson.published_version_id,
     item->>'title',item->>'subtitle',(item->>'estimated_minutes')||' мин',
     item->>'objective',item->>'hook',(item->>'estimated_minutes')::int,'editor',
     'Редакционна версия v5: практическа програма; 15 стъпки и оценявани решения'
   FROM public.academy_lesson_versions WHERE academy_lesson_id=lesson.id
   RETURNING id INTO new_version;
   FOR part IN SELECT value FROM jsonb_array_elements(item->'blocks') LOOP
     INSERT INTO public.academy_lesson_blocks
       (version_id,block_key,position,block_type,title,content,required,points)
     VALUES(new_version,part->>'block_key',(part->>'position')::int,part->>'block_type',
       part->>'title',part->'content',(part->>'required')::boolean,(part->>'points')::int)
     RETURNING id INTO new_block;
     IF part ? 'answer_key' THEN
       INSERT INTO academy_private.lesson_block_keys(block_id,answer_key,feedback,scoring)
       VALUES(new_block,part->'answer_key',part->'feedback',part->'scoring');
     END IF;
   END LOOP;
   IF (SELECT count(*) FROM academy_private.lesson_block_keys k
        JOIN public.academy_lesson_blocks b ON b.id=k.block_id WHERE b.version_id=new_version)<>5
      OR (SELECT count(*) FROM public.academy_lesson_blocks b WHERE b.version_id=new_version AND b.required)<>13
      OR (SELECT count(*) FROM public.academy_lesson_blocks b WHERE b.version_id=new_version AND b.block_type IN
           ('practical_response','reflection','homework','submission','prompt_builder'))<>0
      OR EXISTS (SELECT 1 FROM public.academy_lesson_blocks b
           JOIN academy_private.lesson_block_keys k ON k.block_id=b.id
           WHERE b.version_id=new_version AND b.block_type IN ('quiz','scenario') AND
             NOT EXISTS (SELECT 1 FROM jsonb_array_elements(b.content->'options') o
                         WHERE o->>'id'=k.answer_key->>'correct')) THEN
     RAISE EXCEPTION 'Invalid block/key structure: %/%',item->>'module_id',item->>'lesson_id';
   END IF;
   validation_result:=academy_private.lesson_validation(new_version);
   IF jsonb_array_length(validation_result->'errors')<>0 OR jsonb_array_length(validation_result->'warnings')<>0 THEN
     RAISE EXCEPTION 'Validation failed for %/%: %',item->>'module_id',item->>'lesson_id',validation_result;
   END IF;
   UPDATE public.academy_lesson_versions SET validation=validation_result WHERE id=new_version;
   INSERT INTO academy_private.lesson_progress_history
     (user_id,academy_lesson_id,version_id,snapshot,archived_at,reason)
   SELECT p.user_id,p.academy_lesson_id,p.version_id,to_jsonb(p),clock_timestamp(),'pre_publish_v5'
   FROM public.academy_lesson_progress p WHERE p.academy_lesson_id=lesson.id
   ON CONFLICT (user_id,academy_lesson_id,version_id) DO UPDATE
   SET snapshot=EXCLUDED.snapshot,archived_at=EXCLUDED.archived_at,reason=EXCLUDED.reason;
   UPDATE public.academy_lessons SET draft_version_id=new_version,
      published_version_id=new_version,status='published',updated_at=now() WHERE id=lesson.id;
   GET DIAGNOSTICS rows_updated=ROW_COUNT;
   IF rows_updated<>1 THEN RAISE EXCEPTION 'Publish lost row for %',item->>'lesson_id'; END IF;
   INSERT INTO public.academy_lesson_audit(academy_lesson_id,version_id,actor_id,action,details)
   VALUES(lesson.id,new_version,NULL,'published',jsonb_build_object(
     'source','perfect_video_modules_4_6_v5','previous_version_preserved',true,'progress_archived',true));
 END LOOP;
 IF n<>43 THEN RAISE EXCEPTION 'Published %, expected 43',n; END IF;
END $release$;
